quests[1] = { id = 1, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kanrethads Quest", description = "Willkommen zurück vom Reich der Toten.\n\nEin ganzes Zeitalter ist es her, seit Ihr ein stolzer Held unter Euresgleichen wart. Doch nun seid Ihr <ein geschlagener Mann/eine geschlagene Frau> -gebrochen, ein Relikt vergangener Tage. Höret nun und ich werde der Legende, die Ihr einst wart, neues Leben einhauchen.\n\nIch werde Waffen und Kräfte, die Ihr verloren habt, wiederherstellen und Euch wieder ins Leben rufen.", sourceObjective = "Sprecht mit Kanrethad, um Eure Talente, Waffen und Euer Reittier wiederherzustellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[2] = { id = 2, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Klaue von Scharfkralle", description = "Der mächtige Hippogryph Scharfkralle wurde getötet und die Klaue der erschlagenen Bestie dient als Beweis für Euren Sieg.\n\nSenani Donnerherz in der Silberwindzuflucht wird zum Beweis Eurer Tat sicher gern diese Trophäe sehen wollen.", sourceObjective = "Bringt Senani Donnerherz in der Silberwindzuflucht die Klaue von Scharfkralle.", progress = "Was habt Ihr denn da, {class}? Ist es wirklich...?", completion = "Ihr habt das Biest erlegt?\n\nIch stehe tief in Eurer Schuld, mein Freund. Diese Bestie hat über die Jahre viele terrorisiert, ihr Tod aber hat für mich eine besondere Bedeutung.\n\nVor Kurzem ist mein Bruder eben diesen Klauen zum Opfer gefallen... Nun kann ich ruhig schlafen, da ich weiß, dass mein Bruder gerächt wurde.", sourceObjectiveStatus = "unverified-source-field" }
quests[5] = { id = 5, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bibbers' knurrender Magen", description = "Ich verstecke mich jetzt schon seit Wochen in dieser Geisterstadt, und die ganze Zeit habe ich nichts gegessen außer Maden und Unkraut! Ich brauche was Anständiges zum Essen, und ich werde mich nicht lumpen lassen.\n\nBringt mir ein Festessen, und ich bezahle Euch gut dafür.\n\nIch habe gehört, dass Küchenchef Grual aus der Taverne \"Zum Roten Raben\" in Dunkelhain ganz ausgezeichnete schwärzliche Krebsküchlein macht...", sourceObjective = "Sprecht mit Küchenchef Grual.", sourceObjectiveStatus = "unverified-source-field" }
quests[6] = { id = 6, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kopfgeld auf Garrick Schleichfuß", description = "Garrick Schleichfuß, ein Dieb und Halsabschneider, der schon seit Wochen unseren Bauern und Händlern das Leben schwer macht, ist bei einem Schuppen in der Nähe der Weinberge gesehen worden. Die Weinberge liegen im Osten der Abtei, auf der anderen Seite der Brücke. Bringt mir den Kopf des Schurken und verdient Euch das Kopfgeld, das auf ihn ausgesetzt ist!\n\nDoch seht Euch vor, {name}. Garrick hat eine Bande von Rohlingen um sich versammelt, also werdet Ihr nicht leicht an ihn herankommen.", sourceObjective = "Tötet Garrick Schleichfuß und bringt seinen Kopf zu Unteroffizier Willem in der Nähe der Abtei von Nordhain.", sourceObjectiveStatus = "unverified-source-field" }
quests[7] = { id = 7, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, description = "Eure erste Aufgabe ist eine Säuberung, {name}. Ein Koboldklan hat sich in den Wäldern im Norden eingenistet. Begebt Euch dorthin und bekämpft das Koboldgezücht, das Ihr dort finden werdet. Dezimiert es, damit wir die Kobolde eines Tages gänzlich aus Nordhain vertreiben können.", sourceObjective = "Tötet 6 von dem Koboldgezücht und kehrt dann zu Marschall McBride zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[8] = { id = 8, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Schurkenhandel", description = "Heda, Kamerad! Wollt Ihr nicht einem jungen Mann, der mehr als seinen Teil an hirnlosen Zombies und Spinnen umgelegt hat, einen Gefallen tun?\n\nIch hab hier einen Brief, der muss nach Brill... zu so einer Gastwirtin namens Renee Irgendwas. Ist eigentlich völlig egal, wie sie mit Nachnamen heißt.\n\nNa egal, jedenfalls ist es ein netter kleiner Ort, wo lauter Opfer der Seuche wohnen, die versuchen, sich irgendwie durchs Leben zu schlagen. Und es wäre ein toller Ort für Euch, an dem Ihr Euch ausruhen könnt, falls das mal nötig wird. Ihr solltet Euch den wirklich mal anseh'n - macht es, und ich bezahl Euch auch noch gut dafür.", sourceObjective = "Liefert den unscheinbaren Brief bei Gastwirtin Renee in Tirisfal ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[9] = { id = 9, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tod auf den Feldern", description = "Jetzt seht Euch nur an, was aus diesem Ort geworden ist! In dieser Gegend lebten einst ehrbare Bauersleute. Die verdammten Diebe haben sie alle vertrieben. Aber mich nicht! Jetzt sieht es allerdings so aus, als hätten einige Erntebehüter sich in den Feldern breitgemacht.\n\nWenn Ihr Euch dem gewachsen fühlt, dann geht hinaus und tötet dort draußen 20 von ihnen. Wenn Ihr fertig seid, kommt zurück und holt Euch Eure Bezahlung ab. Und wenn Ihr alle in meinem Feld erwischt habt, dann räumt auch in den angrenzenden Feldern auf.", sourceObjective = "Bauer Saldean möchte, dass Ihr 20 Erntebehüter tötet.", sourceObjectiveStatus = "unverified-source-field" }
quests[10] = { id = 10, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Erlösung von Kieselschliff", description = "Oh, das ist einfach schrecklich! Ich habe meinen besten Gehilfen, Unterfeldmesser Kieselschliff, in die Wüste südöstlich von hier geschickt. Das ist ein Gebiet, das wir die Klaffende Schlucht nennen. Nun ja, er wird vermisst und in seinem letzten Bericht sprach er davon, dass es dort, wo er war, noch mehr dieser komischen Viecher gäbe. Könnte es sein, dass sie sich jetzt in zwei großen Gebieten der Wüste eingenistet haben?\n\nBegebt Euch bitte für mich zur Klaffenden Schlucht und sucht nach Kieselschliff! Das... oder findet wenigstens seine Feldmesserausrüstung. Ich fürchte, das ist alles, was von dem Armen übrig geblieben ist.", sourceObjective = "Erforscht das Schicksal von Unterfeldmesser Kieselschliff und bringt entweder ihn oder seine Feldmesserausrüstung nach Gadgetzan zum Leitenden Feldmesser Rutenwünschels.", sourceObjectiveStatus = "unverified-source-field" }
quests[11] = { id = 11, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kopfgeld auf die Flusspfotengnolle", description = "Gnolle, brutale Wesen, die in dieser Gegend nichts zu suchen haben, sind entlang der Grenzen des Waldes von Elwynn gesehen worden. Ein großes Rudel, viel zu viele, als dass wir allein mit ihnen fertigwerden könnten, hat sich in den Wäldern südlich von jenem Wachturm dort eingenistet. Eine weitere Gruppe hat sich im Gebiet nahe des Steinhügelsees im Osten eingenistet.\n\nDie Armee von Sturmwind wird jeden belobigen, der dabei hilft, die Gnolle zu töten. Bringt mir ihre bemalten Gnollarmbinden als Beweis für Eure Tat.", sourceObjective = "Bringt Stellvertreter Rainer in der Kaserne 8 bemalte Gnollarmbinden.", progress = "Seid gegrüßt, {name}. Wart Ihr Gnolle töten?", completion = "Wie ich sehe, wart Ihr fleißig! Habt Dank, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12] = { id = 12, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Volksmiliz", description = "Die Volksmiliz hat nur ein einziges Ziel: Westfall zu verteidigen und den Frieden in dieses Land zurückzubringen. Doch leider muss der Frieden nur allzu oft mit Blut bezahlt werden. \n\nEiner meiner Späher hat uns Kunde davon gebracht, dass eine Fallenstellerbande der Defias hier in der Nähe verheerende Schäden anrichtet. Mir liegen Berichte vor, dass einige Fallensteller der Defias in der Nähe des Jangoschachts im Nordwesten gesichtet wurden, ebenso bei Molsens Hof und bei Brauenwirbels Kürbishof. Wenn Ihr unseren Reihen beizutreten wünscht, dann erschlagt 15 Fallensteller der Defias und 15 Schmuggler der Defias und kehrt zu mir zurück.", sourceObjective = "Gryan Starkmantel möchte, dass Ihr 15 Fallensteller der Defias und 15 Schmuggler der Defias tötet und zu ihm auf die Späherkuppe zurückkehrt.", sourceObjectiveStatus = "unverified-source-field" }
quests[13] = { id = 13, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Volksmiliz", description = "Eine Bande heimtückischer Plünderer der Defias ist dabei gesehen worden, wie sie den Goldküstensteinbruch, Mondbruch und Alexstons Bauernhof ausplünderten. Die Volksmiliz kann ein solches Verhalten nicht hinnehmen. Macht Euch unverzüglich auf den Weg, {name}, und zeigt, dass das Licht in Westfall zugegen ist.\n\nDer Goldküstensteinbruch befindet sich in der Nähe der Küste, westlich vom Turm. Im nächsten Schritt Eurer Ausbildung müsst Ihr 15 dieser üblen Plünderer der Defias und 15 Ausplünderer der Defias töten.", sourceObjective = "Gryan Starkmantel möchte, dass Ihr 15 Plünderer der Defias und 15 Ausplünderer der Defias tötet und zu ihm auf die Späherkuppe zurückkehrt.", sourceObjectiveStatus = "unverified-source-field" }
quests[14] = { id = 14, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Volksmiliz", description = "Einige Defias konnten wir bislang nicht erwischen. Mein bester Späher berichtet, dass diese Defias in der ganzen Gegend auf Raubzug gehen und schon bis Süd-Westfall gekommen sind. Wir glauben, dass sie sich in den Dolchhügeln versteckt halten und dort ihren nächsten Schachzug planen. Schaltet diese Verbrecher im Namen der Volksmiliz aus.", sourceObjective = "Gryan Starkmantel möchte, dass Ihr 15 Straßenräuber der Defias, 5 Pfadpirscher der Defias und 5 Knöchelhauer der Defias tötet und zu ihm auf die Späherkuppe zurückkehrt.", sourceObjectiveStatus = "unverified-source-field" }
quests[15] = { id = 15, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überprüfung der Echokammmine", description = "Wie mir meine Späher mitteilen, ist das Koboldproblem größer als wir dachten, {name}. Eine Gruppe Koboldtagelöhner hat ihr Lager in der Nähe der Echokammmine im Norden aufgeschlagen.\n\nBegebt Euch zu der Mine und entfernt die Kobolde. Wir wissen, dass sich mindestens 8 von ihnen dort aufhalten. Tötet sie, seht nach, ob dort noch mehr von ihnen sind, kommt dann zu mir zurück und erstattet Bericht.", sourceObjective = "Tötet 8 Koboldtagelöhner und erstattet dann Marschall McBride Euren Bericht.", sourceObjectiveStatus = "unverified-source-field" }
quests[16] = { id = 16, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Etwas zu trinken für Gerard", progress = "Es macht durstig, das Land zu bestellen, und ich bin immer auf der Suche nach erfrischendem Quellwasser.\n\nWenn Ihr welches habt, dann mache ich einen Tauschhandel mit Euch.", completion = "Danke, {name}! Und kommt jederzeit wieder, wenn Ihr noch einen Handel machen wollt." }
quests[17] = { id = 17, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reagenzsuche in Uldaman", description = "Ich habe von einer neu entdeckten Pilzsorte gehört, den Magentafunguskappen. Sie wachsen in Kolonien bei der Uldaman-Grabungsstätte. Man findet sie häufig in den vorderen Tunnelabschnitten und auch tief in den unerforschten Regionen der Grabungsstätte. Ich möchte ihren potenziellen Nutzen für die Alchemie erforschen und dafür brauche ich Euch.\n\nFindet die Magentafunguskappen-Kolonien und bringt mir ein Dutzend Kappen. Aber seid gewarnt - die Pilze stoßen vielleicht Giftsporen aus, wenn man sie anstößt.\n\nWenn Ihr das für mich tut, dann braue ich Euch einen Schwung von meinem berühmten Regenerierungselixier!", sourceObjective = "Bringt zwölf Magentafunguskappen nach Thelsamar zu Ghak Heilsegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[18] = { id = 18, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bruderschaft der Diebe", description = "Seit Kurzem treibt sich eine neue Diebesbande in Nordhain herum. Sie nennen sich die Bruderschaft der Defias und sind auf der anderen Seite des Flusses im Osten gesehen worden.\n\nIch weiß nicht genau, was sie vorhaben, aber ich bin mir sicher, es ist nichts Gutes! Bringt mir die Kopftücher, die sie tragen, und ich werde Euch mit einer Waffe belohnen.", sourceObjective = "Bringt 8 rote Sackleinenkopftücher zu Unteroffizier Willem in der Nähe der Abtei von Nordhain.", sourceObjectiveStatus = "unverified-source-field" }
quests[19] = { id = 19, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tharil'zun", description = "Zwischen hier und Burg Steinwacht legen Kundschafter und Renegaten des Schwarzfels ständig Hinterhalte. Der Anführer der Kundschafter heißt Tharil'zun und diesen Orc wollen wir haben. Bringt mir den Kopf von Tharil'zun!", sourceObjective = "Bringt den Kopf von Tharil'zun ins Rotkammgebirge zu Marschall Marris.", sourceObjectiveStatus = "unverified-source-field" }
quests[20] = { id = 20, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bedrohung durch den Schwarzfelsklan", description = "Die Orcs des Schwarzfelsklans haben die Brennende Steppe verlassen und Burg Steinwacht im Norden besetzt. Von dort aus ziehen sie marodierend durch das Gebiet nördlich von Seenhain, so dass dessen Bewohner sich nicht mehr aus der Stadt wagen und dort eingesperrt sind wie Vieh in einem zu engen Pferch.\n\nHelft uns, diese Bedrohung von Seenhain zu nehmen! Tötet diese Orcs des Schwarzfels und bringt mir 10 ihrer kampferprobten Äxte zum Beweis.\n\nUnd obwohl der Schwarzfelsklan uns vor allem aus dem Norden bedroht, haben wir auch gehört, dass sich noch weitere Schwarzfelsorcs in der südöstlichen Ecke des Rotkammgebirges aufhalten. Wenn Ihr dort welche findet, solltet Ihr die auch jagen.", sourceObjective = "Bringt 10 kampferprobte Äxte nach Seenhain zu Marschall Marris.", sourceObjectiveStatus = "unverified-source-field" }
quests[21] = { id = 21, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scharmützel in der Echokammmine", description = "Eure Untersuchungen beweisen, dass die Echokammmine gesäubert werden muss. Kehrt in die Mine zurück und helft dabei, sie von den Kobolden zu befreien.\n\nIhr dürft keine Zeit verlieren, {name}. Je länger die Kobolde sich ungehindert in der Mine aufhalten können, umso festere Wurzeln fassen sie in Nordhain.", sourceObjective = "Tötet 8 Koboldhilfsarbeiter und kehrt dann zu Marschall McBride in der Abtei von Nordhain zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[22] = { id = 22, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pastete aus Geiferzahnleber", description = "Die Zwiebeln sind geschält, der Knoblauch ist gehackt, der Rosmarin ist zerstoßen, die Kruste ist gebacken, das Dillkraut ist gewiegt und die Sauce steht auf dem Herd. Jetzt brauche ich für meine berühmte Fleischpastete nur noch 8 Geiferzahnlebern!", sourceObjective = "Salma Saldean braucht 8 Geiferzahnlebern für ihre Pastete aus Geiferzahnleber.", sourceObjectiveStatus = "unverified-source-field" }
quests[23] = { id = 23, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ursangus' Tatze", description = "Der mächtige Bär Ursangus ist nicht mehr!\n\nDas kleine halbmondförmige Emblem auf seiner Tatze bedeutet, dass das Tier von den Nachtelfen dazu abgerichtet wurde, den Wald zu durchstreifen und nach ihren Feinden zu durchsuchen. Niemand kann sagen, wie viele Eurer Hordebrüder und -schwestern diesem Geschöpf zum Opfer gefallen sind.\n\nIhr solltet die Tatze zu Tarkan in die Silberwindzuflucht bringen. Er wird sich freuen, zu erfahren, dass eine solche Waffe aus dem Arsenal des Feindes entfernt worden ist.", sourceObjective = "Bringt Ursangus' Tatze zu Hauptmann Tarkan in der Silberwindzuflucht.", progress = "Was ist, {race}?", completion = "Ah, die Tatze von Ursangus!\n\nHabt Ihr überhaupt eine Vorstellung davon, wie viel Ärger uns dieses Biest über die Jahre bereitet hat? Diese Zeiten sind nun Dank Euch vorbei.\n\nIch werde diese Trophäe zusammen mit Eurem Bericht über den Tod der Bestie nach Orgrimmar schicken, damit sie öffentlich ausgestellt werden kann.\n\nMeinen Glückwunsch!", sourceObjectiveStatus = "unverified-source-field" }
quests[24] = { id = 24, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schattumbras Kopf", description = "Der einstmals so flinke Schattumbra liegt jetzt regungslos vor Euch und der Sieg ist Euer.\n\nDieses legendäre Geschöpf wird von den Nachtelfen verehrt. Sein Kopf dürfte eine beeindruckende Trophäe sein und als Zeichen für das Ende der Allianz im Eschental dienen.\n\nHauptmann Goggath in Höllschreis Wacht wird zweifellos hoch erfreut sein, den Kopf des erschlagenen Nachtsäblers entgegenzunehmen.", sourceObjective = "Bringt Schattumbras Kopf zu Hauptmann Goggath in Höllschreis Wacht.", progress = "Ja, {class}?", completion = "Schattumbras Kopf?\n\nWer weiß, wie viele unserer Hordenbrüder dieser Bestie über die Jahre zum Opfer gefallen sind? Eure Tapferkeit hat sichergestellt, dass niemand mehr diesem Schicksal erliegt.\n\nKriegshäuptling Höllschrei soll von Euren Taten hören, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[25] = { id = 25, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Und dann langsam abkühlen lassen", description = "Das hättet Ihr sehen sollen, {class}! Die Elfen dachten, Silberwind wäre uneinnehmbar. Bei all ihren vielen Verteidigungsmaßnahmen und ihrer Armee von Wasserelementaren hat das auch beinahe gestimmt.\n\nBeinahe.\n\nEinem unserer Magier ist es gelungen, einen verderbten Elementar zu beschwören, der die anderen in wilde Raserei versetzte.\n\nAhh, Ihr hättet nur deren Gesichter sehen sollen!\n\n <Tarkan lacht.>\n\nLeider ist der Magier, der die Beschwörung durchgeführt hat, im Kampf gefallen. Jetzt benötige ich jemanden, der die Misere in Ordnung bringt.", sourceObjective = "Hauptmann Tarkan in der Silberwindzuflucht möchte, dass Ihr Tideress sowie 12 beschmutzte Wasserelementare am Mystralsee erledigt.", completion = "Gut gemacht, {class}.\n\nEin passendes Ende für einen vorbildlichen Angriff.", sourceObjectiveStatus = "unverified-source-field" }
quests[26] = { id = 26, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine wertvolle Lektion", description = "{name}, ich habe Euren Fortschritt mit großem Genuss verfolgt. Ihr entwickelt Euch definitiv zu einem wertvollen Beschützer der Natur.\n\nEs ist an der Zeit für Euch, mehr über einen der diversen Tieraspekte zu lernen, in die wir uns dank Cenarius' Segen verwandeln können... einen, der Euch die Beherrschung des Wassers ermöglicht. Dazu müsst Ihr zur Mondlichtung in das Dorf Nachthafen reisen und mit Dendrite Sternenschauer vom Zirkel des Cenarius sprechen. Er wird Euch weiter anleiten.", sourceObjective = "Sprecht mit Dendrite Sternenschauer im Dorf Nachthafen auf der Mondlichtung.", sourceObjectiveStatus = "unverified-source-field" }
quests[27] = { id = 27, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine wertvolle Lektion", description = "{name}, ich habe Euren Fortschritt mit großem Genuss verfolgt. Ihr entwickelt Euch definitiv zu einem wertvollen Beschützer der Natur.\n\nEs ist an der Zeit für Euch, mehr über einen der diversen Tieraspekte zu lernen, in die wir uns dank Cenarius' Segen verwandeln können... einen, der Euch die Beherrschung des Wassers ermöglicht. Dazu müsst Ihr zur Mondlichtung in das Dorf Nachthafen reisen und mit Dendrite Sternenschauer vom Zirkel des Cenarius sprechen. Er wird Euch weiter anleiten.", sourceObjective = "Sprecht mit Dendrite Sternenschauer im Dorf Nachthafen auf der Mondlichtung.", sourceObjectiveStatus = "unverified-source-field" }
quests[28] = { id = 28, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prüfung des Sees", description = "Als Eure erste Prüfung müsst Ihr in den Tiefen des Sees von Elune'ara nach einem Schreinschmuckstück suchen. Es zerfällt schnell, daher solltet Ihr Euch mit größter Eile zum Schrein von Remulos begeben. Benutzt das Schmuckstück am Schrein und sprecht dann dort mit Tajarri; sie ist eine der vertrauenswürdigsten Aufseherinnen der Mondlichtung.\n\nIhr habt nur eine gewisse Zeitspanne für diese Aufgabe zur Verfügung, und Ihr könntet in Konkurrenz zu anderen Druiden stehen, die ebenfalls nach Schmuckstücken suchen. Geistiges wie körperliches Geschick wird für Euren Erfolg unabdingbar sein.\n\nViel Glück, {name}.", sourceObjective = "Sucht ein Schreinschmuckstück im See von Elune'ara und bringt es zum Schrein von Remulos im Nordwesten der Mondlichtung. Wenn Ihr dort seid, benutzt das Schreinschmuckstück.\n\nIhr müsst anschließend mit Tajarri am Schrein sprechen, um die Prüfung abzuschließen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29] = { id = 29, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prüfung des Sees", description = "Als Eure erste Prüfung müsst Ihr in den Tiefen des Sees von Elune'ara nach einem Schreinschmuckstück suchen. Es zerfällt schnell, daher solltet Ihr Euch mit größter Eile zum Schrein von Remulos begeben. Benutzt das Schmuckstück am Schrein und sprecht dann dort mit Tajarri; sie ist eine der vertrauenswürdigsten Aufseherinnen der Mondlichtung.\n\nIhr habt nur eine gewisse Zeitspanne für diese Aufgabe zur Verfügung, und Ihr könntet in Konkurrenz zu anderen Druiden stehen, die ebenfalls nach Schmuckstücken suchen. Geistiges wie körperliches Geschick wird für Euren Erfolg unabdingbar sein.\n\nViel Glück, {name}.", sourceObjective = "Sucht ein Schreinschmuckstück im See von Elune'ara und bringt es zum Schrein von Remulos im Nordwesten der Mondlichtung. Wenn Ihr dort seid, benutzt das Schreinschmuckstück.\n\nIhr müsst anschließend mit Tajarri am Schrein sprechen, um die Prüfung abzuschließen.", sourceObjectiveStatus = "unverified-source-field" }
quests[30] = { id = 30, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prüfung des Seelöwen", description = "Für die zweite Prüfung benötigt Ihr die zwei Hälften, aus denen der Anhänger des Seelöwen besteht. Die eine Hälfte bezieht ihre Kraft aus der Beweglichkeit des Seelöwen-Aspektes beim Gleiten durchs Wasser; die andere Hälfte bezieht ihre Kraft aus der unglaublichen Ausdauer des Seelöwen-Aspektes. Druiden bedienen sich dieser beiden Eigenschaften gleichermaßen, um den Aspekt ihrer Wassergestalt zu verkörpern.\n\nSprecht mit den Bewohnern der Mondlichtung, um herauszufinden, wo sich die Teile befinden könnten, und bringt beide hierher, um sie miteinander zu vereinen. Bringt den Anhänger zu Dendrite Sternenschauer, wenn Ihr ihn geschaffen habt.", sourceObjective = "Sucht die Anhängerhälfte der Wasserbeweglichkeit und die Anhängerhälfte der Wasserbelastbarkeit. Sprecht mit den Einwohnern der Mondlichtung, um Hinweise darauf zu erhalten, wo sich diese Gegenstände befinden könnten.\n\nFormt den Anhänger des Seelöwen aus den beiden Anhängerhälften. Ihr müsst in der unmittelbaren Nähe des Schreins von Remulos sein, um dies zu tun.\n\nBringt den zusammengefügten Anhänger zu Dendrite Sternenschauer im Dorf Nachthafen auf der Mondlichtung.", sourceObjectiveStatus = "unverified-source-field" }
quests[31] = { id = 31, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wassergestalt", description = "Ihr habt die notwendigen Lektionen gemeistert, die alle jungen Druiden lernen, bevor sie einen Wasseraspekt annehmen können. Kehrt jetzt zu Eurem Lehrer Turak Runentotem nach Donnerfels zurück. Zeigt ihm Euren Anhänger und beweist ihm damit, dass Ihr bereit seid zu lernen, was er Euch lehren kann. Er wird Eure Ausbildung abschließen und Euch ermöglichen, eins mit dem Wasser zu werden.\n\nAuf Wiedersehen. Wir werden uns wieder sprechen.", sourceObjective = "Kehrt nach Donnerfels zurück und zeigt Turak Runentotem den Anhänger des Seelöwen.", sourceObjectiveStatus = "unverified-source-field" }
quests[32] = { id = 32, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rise of the Silithid" }
quests[33] = { id = 33, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wölfe an der Grenze", description = "Was auch immer diese Wölfe sich eingefangen haben, es geht nicht weg. Jeden Tag tauchen weitere kranke Wölfe auf. Es tut mir in der Seele weh, dass jemand diese Schöpfungen der Natur in meinem Namen töten muss, aber wir müssen die erkrankten jungen Wölfe erledigen, bevor die lokale Ansteckung zu einer Epidemie wird.\n\nTötet erkrankte junge Wölfe im Tal und bringt mir ihre Pelze als Beweis Eurer Tat.", sourceObjective = "Bringt Eagan Pelzschneider, den Ihr vor der Abtei von Nordhain findet, 8 Pelze von erkrankten Wölfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[34] = { id = 34, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein ungebetener Gast", description = "Mein Garten ist schon wieder zertrampelt und verwüstet worden. Und ich weiß genau, was für ein Tier das getan hat. Das war dieser elende Eber, der, den Marschall Marris seit einer Weile immer Stopfwanst nennt.\n\nJetzt kann ich die Narzissen erst nächsten Herbst wieder anpflanzen. Hin! Alle hin, und das nur wegen dieses einen gefährlichen Ebers. Bereitet dieser Plage ein Ende! Zeigt mir seinen Hauer und ich werde Euch nur zu gern belohnen. Die meiste Zeit scheint er damit zu verbringen, in den Feldern südwestlich von Seenhain nach Futter zu suchen, doch gelegentlich verirrt er sich auch hierher und in meinen Garten.", sourceObjective = "Martie Jainrose aus Seenhain möchte, dass Ihr Stopfwanst tötet. Bringt ihr den Hauer des Ebers zum Beweis.", sourceObjectiveStatus = "unverified-source-field" }
quests[35] = { id = 35, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weitere Sorgen", description = "Falls Ihr befürchtet, dass die Gerüchte über das Auftauchen von Murlocs wahr sein könnten, dann tut das Folgende: Begebt Euch zur östlichen Brücke von Elwynn und sprecht mit Wache Thomas. Er ist seit einer Woche an der Brücke stationiert und wird deswegen wissen, wie es in der Gegend aussieht.\n\nIch habe hier ein Streitross aus Sturmwind, das Euch zur Wache Thomas tragen wird. Lasst es mich wissen, wenn Ihr das Pferd benutzen wollt.", sourceObjective = "Marschall Dughan möchte, dass Ihr mit Wache Thomas sprecht.", completion = "Ja, es haben sich Murlocs in und an den Flüssen und Bächen des östlichen Elwynn niedergelassen. Wir wissen nicht, warum sie hergekommen sind, aber sie sind aggressiv und zumindest halbwegs intelligent.", sourceObjectiveStatus = "unverified-source-field" }
quests[36] = { id = 36, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Westfalleintopf", description = "Ich hätte nie gedacht, dass jemals der Tag kommen würde, an dem ich den Hof verlasse. Aber in den Feldern wimmelt es nur so von Dieben und es ist hier für uns viel zu gefährlich geworden. Sobald Bauer Brauenwirbel den Wagen repariert hat, machen wir uns auf den Weg.\n\nKönntet Ihr mir vielleicht einen Gefallen tun? Ich schreibe Euch schnell mein Rezept für Westfalleintopf auf. Seid so nett und bringt es Salma Saldean; sie wohnt auf dem Hof dort hinten. Ihr findet den Hof der Saldeans gleich hinter der Gabelung der Straße.", sourceObjective = "Verna Brauenwirbel möchte, dass Ihr ihr Rezept für Westfalleintopf bei Salma Saldean abliefert.", sourceObjectiveStatus = "unverified-source-field" }
quests[37] = { id = 37, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suche nach den vermissten Wachen", description = "Vor ein paar Tagen haben wir zwei Wachen, Rolf und Malakai, losgeschickt, damit sie entlang des Flusses Nachforschungen anstellen, aber bisher sind sie noch nicht zurückgekehrt. Damit ich meinen Bericht fertig schreiben kann, muss ich wissen, was den beiden Männern zugestoßen ist.\n\nSucht den Fluss in Richtung Norden ab und seht zu, dass Ihr die Wachen findet... oder ihre Überreste.", sourceObjective = "Wache Thomas möchte, dass Ihr den Fluss in Richtung Norden nach Rolf und Malakai, den beiden vermissten Wachen, absucht.", completion = "Vom Leichnam selbst ist nicht mehr viel zu erkennen. Doch in der Nähe findet Ihr ein Medaillon, in das die Worte \"Malakai Stone, Soldat\" eingeprägt sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[38] = { id = 38, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Westfalleintopf", description = "Wollt Ihr mir dabei helfen, Westfalleintopf zu kochen? Dann bringt mir die folgenden Zutaten: \n\n 3 Stücke sehniges Geierfleisch \n 3 Geiferzahnschnauzen \n 3 Murlocaugen \n 3 Okraschoten", sourceObjective = "Salma Saldean möchte 3 Stücke sehniges Geierfleisch, 3 Geiferzahnschnauzen, 3 Murlocaugen und 3 Okraschoten.", sourceObjectiveStatus = "unverified-source-field" }
quests[39] = { id = 39, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zustellung von Thomas' Bericht", description = "Berichtet Marschall Dughan, dass Malakai und Rolf ums Leben gekommen sind, und teilt ihm auch mit, dass wir die Murlocs in Ost-Elwynn mit unserer derzeitigen Truppenstärke hier nicht unter Kontrolle halten können.\n\nIch weiß, dass wir nicht viele überzählige Männer haben, aber vielleicht findet Dughan ja doch jemanden.", sourceObjective = "Erstattet Marschall Dughan in Goldhain Bericht.", sourceObjectiveStatus = "unverified-source-field" }
quests[40] = { id = 40, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefahr aus dem Wasser", description = "Eine neue Gefahr bedroht den Wald von Elwynn, {name}! Murlocs kommen die Bäche und Flüsse im östlichen Elwynn hinaufgeschwommen, vertreiben die Fische und greifen einfache Leute an!\n\nIch habe Marschall Dughan bereits gewarnt, aber der macht sich größere Sorgen wegen der Gnolle und der Banditen. Er ist nicht überzeugt davon, dass die Murlocs eine Gefahr darstellen.\n\nBitte sprecht mit Dughan, {name}, und bringt ihn dazu, dass er Verstärkung in den Osten schickt!", sourceObjective = "Remy \"Zweifach\" möchte, dass Ihr in Goldhain mit Marschall Dughan sprecht.", completion = "Ja, ich habe mit Remy darüber gesprochen. Er ist ein guter Händler und ich respektiere ihn, aber alle Berichte von Murlocs im Osten waren bisher bestenfalls bruchstückhaft.\n\nIch nehme Eure Sorgen zur Kenntnis, aber solange ich nicht einen zuverlässigen Bericht aus berufener militärischer Quelle erhalte, der bestätigt, dass die Murlocs tatsächlich eine Bedrohung darstellen, können wir es uns nicht leisten, weitere Soldaten nach Osten zu schicken.", sourceObjectiveStatus = "unverified-source-field" }
quests[45] = { id = 45, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rolfs Schicksal", description = "Als Ihr die Gegend weiter absucht, findet Ihr die Abdrücke von Füßen mit Schwimmhäuten, die entlang dem Ufer des Steinhügelsees nach Osten führen. In der Ferne könnt Ihr im Osten gerade noch so ein Murlocdorf ausmachen.\n\nVielleicht fand Rolfs Leben dort sein Ende...", sourceObjective = "Durchsucht das Murlocdorf nach Rolf - oder nach Anzeichen für seinen Tod.", completion = "Um den Hals trägt der Leichnam ein Medaillon aus Metall, auf dem die Worte \"Rolf Hartford, Soldat\" stehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[46] = { id = 46, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kopfgeld auf die Murlocs", description = "Die Armee von Sturmwind hat ein Kopfgeld auf die Murloclauerer und Murlocfutterwühler ausgesetzt, die sich in Elwynn herumtreiben. Erlegt sie und bringt Wache Thomas ihre zerrissenen Murlocflossen, dann wird die Armee von Sturmwind Euch ansehnlich belohnen.\n\nDie Murlocs haben am Steinhügelsee nördlich von hier ein Dorf errichtet und ein weiteres ihrer Dörfer befindet sich im Süden, wo der Fluss sich teilt.", sourceObjective = "Bringt 8 zerrissene Murlocflossen zu Wache Thomas, den Ihr an der östlichen Brücke von Elwynn findet.", progress = "Wie läuft die Jagd, {name}?", completion = "Habt Ihr die Flossen? Ausgezeichnet! Marschall Dughan ist besorgt wegen der Murlocbedrohung in Ost-Elwynn und ich würde ihm gern berichten können, dass wir die Lage langsam unter Kontrolle bekommen.\n\nMit Euren Taten habt Ihr uns dabei geholfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[47] = { id = 47, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tauschhandel mit Goldstaub", description = "Manchmal haben die Kobolde in dieser Gegend Goldstaub dabei. Das Zeug könnte ich wirklich gut gebrauchen. Bringt mir etwas davon und ich mache Euch den besten Preis in der Stadt... den besten Preis in der Stadt!\n\nDie Kobolde halten sich in der Tiefenschachtmine im Süden und im Bereich der Jaspismine im Nordosten auf.", sourceObjective = "Bringt 10 Einheiten Goldstaub nach Goldhain zu Remy \"Zweifach\". Goldstaub findet Ihr bei den Kobolden im Wald von Elwynn.", progress = "Psst! Habt Ihr den Goldstaub für mich... für mich?", completion = "Danke für den Goldstaub, {name}. Hier habt Ihr Euer Geld und hier habt Ihr noch eine kleine... Zugabe von Freunden von mir. Das könnte Euch vielleicht noch nützlich werden... nützlich werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[48] = { id = 48, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goldbrauner Samt", description = "Weit im Süden, wo die Lianen sich ranken\nLiegt versteckt ein Brunnen, in dem fast versanken\nDie wertvollen Wasser, so rein und so helle - \nBringt mir Wasser von der Heiligen Quelle.", sourceObjective = "Bringt Schnapsbart Donnerbräu Wasser von der Heiligen Quelle.", sourceObjectiveStatus = "unverified-source-field" }
quests[49] = { id = 49, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goldbrauner Samt", description = "Lang schon vermiss ich die Lieb meines Lebens\nGoldbraun und samtig, doch noch wart ich vergebens\nBringt mir, dann vergeht jeder Zorn\nJe einen Sack Gerste, Roggen und Korn.", sourceObjective = "Schnapsbart Donnerbräu möchte einen Sack Gerste, einen Sack Roggen und einen Sack Korn haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[50] = { id = 50, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goldbrauner Samt", description = "Die Maische anrühren, das ist mein Wille\nDoch fehlt mir dann auch noch eine Destille\nFür diese brauch ich ein starkes Metall\nBringt mir Echtsilber, das ist gut in dem Fall!", sourceObjective = "Schnapsbart Donnerbräu braucht Echtsilber.", sourceObjectiveStatus = "unverified-source-field" }
quests[51] = { id = 51, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goldbrauner Samt", description = "Noch ist er nicht fertig, doch schon frisch gebrannt\nJetzt wird als Nächstes der Meiler bemannt\nUm den Whisky zu filtern. Drum bringt mir den Ast\nEines Bergahorns - wenn Ihr könnt, ohne Rast!", sourceObjective = "Bringt Schnapsbart Donnerbräu den Ast eines Bergahorns.", sourceObjectiveStatus = "unverified-source-field" }
quests[52] = { id = 52, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grenzschutz", description = "Seid gegrüßt, {name}. Je weiter wir uns von Goldhain entfernen, umso reizbarer sind die wilden Tiere. Und das Holzfällerlager des Osttals wird beinahe ständig von Wölfen und Bären angegriffen.\n\nWir könnten hier draußen wirklich Eure Hilfe gebrauchen.", sourceObjective = "Tötet 8 Streuner oder graue Forstwölfe und 5 junge Waldbären und kehrt dann zu Wache Thomas an der östlichen Brücke von Elwynn zurück.", completion = "Vielen Dank für Eure Hilfe, {name}. Im Wald muss es irgendetwas geben, das die Tiere so angriffslustig macht.\n\nWas auch immer es sein mag, ich hoffe, es bleibt dort!", sourceObjectiveStatus = "unverified-source-field" }
quests[53] = { id = 53, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goldbrauner Samt", description = "Das Getränk, das ich braue, das reine und klare\nWird goldbraun und samtig im Laufe der Jahre\nDoch ehe er fertig, der Whisky, der weiche\nBraucht's noch ein Fass aus verkohlter Eiche.", sourceObjective = "Bringt Schnapsbart Donnerbräu ein verkohltes Eichenbündel.", sourceObjectiveStatus = "unverified-source-field" }
quests[54] = { id = 54, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meldung in Goldhain", description = "{name}, Ihr habt bewiesen, dass Ihr Euch um die Sicherheit von Nordhain sorgt. Nun erhaltet Ihr die Aufgabe, Euch auch dem Schutz des umliegenden Waldes von Elwynn zu widmen.\n\nWenn Ihr Euch dieser Aufgabe stellen wollt, dann nehmt diese Papiere, die bei Marschall Dughan in Goldhain abgeliefert werden müssen. Goldhain liegt an der südlichen Straße, hinter den Grenztoren.", sourceObjective = "Liefert Marschall McBrides Unterlagen bei Marschall Dughan im Wald von Elwynn ab.", progress = "Ihr bringt Nachricht von McBride? Im Vergleich zum Wald von Elwynn ist Nordhain das reinste Paradies. Wir wollen doch mal sehen, was Marschall McBride so zu berichten hat...\n\nGebt mir doch bitte seine Papiere.", completion = "Oha, hier steht, dass Ihr in den Rang des kommissarisch ernannten Stellvertreters der Marschalls von Sturmwind erhoben worden seid. Herzlichen Glückwunsch.\n\nUnd viel Erfolg bei der Arbeit - Elwynn sicher zu machen ist kein Spaziergang, zumal der größte Teil der Armee sonst wo zugange ist und sonst was für irgendwelche Adligen macht!\n\nEs ist schon schwer, in diesen dunklen Zeiten den Überblick über die Politik zu behalten...", sourceObjectiveStatus = "unverified-source-field" }
quests[55] = { id = 55, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Morbent Teufel", description = "Morbent Teufel hält sich in seinem Unterschlupf verborgen, dem Haus, das hoch oben auf dem Hügel im Osten über dem Friedhof von Rabenflucht thront. Doch seine Zeit in diesem Land neigt sich dem Ende entgegen...\n\nSetzt Morbents Bann gegen ihn ein. Das wird seine schützenden Zauber machtlos machen.\n\nErschlagt ihn. Erschlagt ihn und errettet uns von seiner Verderbtheit. Werdet zum Instrument meiner Rache und damit <zum Helden/zur Heldin> des Dämmerwalds!", sourceObjective = "Verwendet Morbents Bann gegen Morbent Teufel, tötet Morbent Teufel und bringt Morbents Bann anschließend zu Sven in dessen Lager zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[56] = { id = 56, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Nachtwache", description = "Als Kommandantin der Nachtwache habe ich geschworen, die Bürger von Dunkelhain zu beschützen. Sturmwind hat alle offiziell ernannten Wachen von ihren Posten hier abgezogen; damit sind wir uns selbst überlassen.\n\nWenn Ihr glaubt, der Aufgabe gewachsen zu sein, könnten wir Eure Hilfe wirklich gebrauchen! Helft der Nachtwache und wagt Euch in den Friedhof Stille Gärten, der ein Stückchen südlich von Dunkelhain liegt. Tötet dort 8 Skelettkrieger und 6 Skelettmagier. Der Bedrohung durch die Untoten muss ein Ende gemacht werden!", sourceObjective = "Kommandantin Althea Schwarzhaupt aus Dunkelhain möchte, dass Ihr 8 Skelettkrieger und 6 Skelettmagier tötet.", sourceObjectiveStatus = "unverified-source-field" }
quests[57] = { id = 57, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Nachtwache", description = "Ich habe berichtet bekommen, dass im Wald eine wahre Untotenplage ausgebrochen ist, {name}. Wenn Ihr Euch der Aufgabe gewachsen fühlt, dann macht Euch auf den Weg zum Friedhof von Rabenflucht und erschlagt 15 dieser abscheulichen Skelettscheusale und 15 Skelettschrecken. Außerdem sollen im Friedhof Stille Gärten, der sich ein Stückchen südlich von Dunkelhain befindet, Skelette gesehen worden sein. Die Untoten müssen aus dem Dämmerwald vertrieben werden!", sourceObjective = "Kommandantin Althea Schwarzhaupt aus Dunkelhain möchte, dass Ihr 15 Skelettscheusale und 15 Skelettschrecken tötet.", sourceObjectiveStatus = "unverified-source-field" }
quests[58] = { id = 58, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Nachtwache", description = "Die Lage in Rabenflucht ist noch immer sehr bedenklich. Die Sicherheit von Dunkelhain liegt in Euren Händen, {name}. Ich habe einfach nicht genug Behüter, um die Sicherheit in der Stadt zu gewährleisten. Deswegen müsst Ihr Euch erneut nach Rabenflucht aufmachen und das östliche Mausoleum von den Seuchenverbreitern säubern, die sich dort breitgemacht haben. Tötet 20 von ihnen!", sourceObjective = "Kommandantin Althea Schwarzhaupt aus Dunkelhain möchte, dass Ihr im östlichen Mausoleum von Rabenflucht 20 Seuchenverbreiter tötet.", sourceObjectiveStatus = "unverified-source-field" }
quests[59] = { id = 59, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rüstung aus Tuch und aus Leder", description = "Als Dank für Eure Gewitztheit und Euren Mut gebe ich Euch hier einen Gutschein, den Ihr gegen ein Rüstungsteil eintauschen könnt. Bringt den Gutschein ins Holzfällerlager des Osttals zu Sara Roderwald. Wenn Ihr ihr den Gutschein gebt, dann stellt sie die Rüstung für Euch her. Und wenn Ihr sie habt, tragt sie zur Verteidigung von Elwynn, {name}.\n\nIhr findet das Holzfällerlager des Osttals östlich dieses Postens jenseits der Brücke.", sourceObjective = "Gebt Sara Roderwald den Rüstungsgutschein der Armee von Sturmwind.", progress = "Ich bin von der Armee von Sturmwind beauftragt, ihre Soldaten mit Rüstung aus Tuch und aus Leder auszustatten.\n\nWenn Ihr einen Gutschein für mich habt, dann stelle ich gern etwas für Euch her.", completion = "Ja, einen solchen Gutschein meinte ich. Danke! Bitte sucht Euch das Stück aus, das Ihr möchtet.\n\nIch wünsche Euch viel Glück auf Eurem Weg als {class}. Und möge diese Rüstung Euch gute Dienste leisten.", sourceObjectiveStatus = "unverified-source-field" }
quests[60] = { id = 60, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Koboldkerzen", description = "Guten Tag, <werter Herr/werte Dame>! Hättet Ihr einen Moment Zeit für mich?\n\nMein Bruder und ich führen in Sturmwind eine Apotheke und ich bin hier, weil ich große Kerzen suche, ihres Wachses wegen. Könnt Ihr mir vielleicht helfen?\n\nGroße Kerzen könnt Ihr von Kobolden bekommen - und ich habe Gerüchte gehört, dass Kobolde sich in den Minen von Elwynn eingenistet haben: in der Tiefenschachtmine im Süden und in der Jaspismine im Osten. Ich schlage vor, dass Ihr Euch an einem dieser Orte auf die Suche nach Kerzen begebt.", sourceObjective = "Bringt 8 große Kerzen zu William Pestle in Goldhain.", progress = "Habt Ihr schon die Kerzen gesammelt?", completion = "Ihr habt wohl eifrig Kobolde gejagt, hmm? Danke für die Kerzen, {name}. Hier habt Ihr Eure Belohnung.", sourceObjectiveStatus = "unverified-source-field" }
quests[61] = { id = 61, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lieferung nach Sturmwind", description = "In Sturmwind wartet mein Bruder Morgan auf die Lieferung der Kerzen. Ich habe selbst nicht die Zeit, um mich auf die Reise zu begeben, aber wenn Ihr ihm die Lieferung überbringen wollt, so wird er Euch gut bezahlen.\n\nIch habe die Kerzen schon fertig verpackt. Ihr findet Morgan in unserem Geschäft im Handelsdistrikt von Sturmwind. Es heißt Pestles Apotheke.", sourceObjective = "Bringt Williams Lieferung in den Handelsdistrikt von Sturmwind zu Morgan Pestle.", sourceObjectiveStatus = "unverified-source-field" }
quests[62] = { id = 62, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Tiefenschachtmine", description = "Die Mine in Nordhain ist nicht die einzige, mit der es Probleme gibt. Berichten zufolge ist auch die Tiefenschachtmine im Wald von Elwynn zu einem Tummelplatz für Kobolde geworden.\n\nErforscht die Mine, bestätigt diese Berichte und kehrt dann zu mir zurück. Die Mine liegt fast genau südlich von Goldhain, zwischen den Höfen der Steinfelds und der Maclures.", sourceObjective = "Erforscht die Tiefenschachtmine und kehrt dann nach Goldhain zu Marschall Dughan zurück.", completion = "Das sind allerdings schlechte Nachrichten. Was kommt als Nächstes, Drachen?!? Wir werden wohl unsere Patrouillen rund um die Mine verstärken müssen. Habt Dank für Eure Bemühungen, {name}. Und wartet einen Moment... Ich habe vielleicht noch eine andere Aufgabe für Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[63] = { id = 63, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf des Wassers", description = "An der Küste des Silberwalds befindet sich westlich des Grabmals ein Schrein, der von der Seuche besudelt ist. Die Geister dort sprechen nicht länger zu unserem Volk und es ist jetzt an Euch, die Manifestation dort zu besiegen und den Teich zu säubern.\n\nNehmt die Armschienen des Elementars und gebt sie zusammen mit den verbleibenden Tropfen von Brines Trank in die Kohlenpfanne. Das sollte ausreichen, um einen reinen Geist zu beschwören, mit dem Ihr kommunizieren könnt.\n\nBringt mir einen Beweis dafür, dass Ihr die Tat vollbracht habt, dann belohne ich Euch mit Eurem Totem.", sourceObjective = "Besiegt die verderbte Wassermanifestation und legt die Armschienen der verderbten Manifestation und die verbleibenden Tropfen reinsten Wassers im Silberwald auf die Kohlenpfanne von Immerquell.", sourceObjectiveStatus = "unverified-source-field" }
quests[64] = { id = 64, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das vergessene Erbstück", description = "Es war fürchterlich! Verna hat mich aufgeweckt, als sie draußen auf dem Feld so einen Radau gehört hat. Das ganze Feld war voller Rowdys! Wir sind in solcher Eile aufgebrochen und da hab ich vergessen, meine Taschenuhr einzupacken. Die Uhr hat mir Vernas Vater an unserem Hochzeitstag geschenkt und es wird mir fast schlecht, wenn ich dran denke, dass diese Diebe sie jetzt haben. Ich hab die Taschenuhr im Kleiderschrank in unserem Haus liegen lassen. Haltet nach dem Kürbisfeld im Westen Ausschau, dann kommt Ihr zu unserem Hof - Ihr könnt ihn gar nicht verfehlen. Wenn Ihr mir meine Uhr wiederbringen würdet, wäre ich Euch sehr dankbar.", sourceObjective = "Bauer Brauenwirbel möchte, dass Ihr seine Taschenuhr holt. Sie befindet sich im Kleiderschrank des Bauernhauses auf der Kürbisfarm im Westen.", sourceObjectiveStatus = "unverified-source-field" }
quests[65] = { id = 65, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Bruderschaft der Defias", description = "Die Bruderschaft der Defias nennt sich die Bande von Schuften, von der die braven Leute von Westfall aus dem Land vertrieben werden. Ihr müsst für mich diese Bande bespitzeln. Wir müssen erfahren, wer der Kopf der Gruppe ist und wo sie ihr Versteck hat. In Seenhain findet Ihr im Gasthaus einen Schurken namens Wiley, der mir noch einen Gefallen schuldet.\n\nBegebt Euch nach Seenhain im Rotkammgebirge, östlich von Elwynn, und findet heraus, was Ihr könnt.", sourceObjective = "Gryan Starkmantel möchte, dass Ihr in Seenhain mit Wiley sprecht.", sourceObjectiveStatus = "unverified-source-field" }
quests[66] = { id = 66, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Legende von Stalvan", description = "Letzte Nacht verspürte ich in meinem Geist eine schreckliche Erschütterung. Ich wusste, dass sich meine Enkelin Alyssa in großer Gefahr befand. Ich befragte die Karten und aus ihnen starrte mich die Fratze des Todes höhnisch an.\n\nIch begab mich auf eine lange Reise durch eine dunkle Trance und schließlich gelang es mir, einen Hinweis auf dieses schreckliche Geheimnis zu erhaschen. Ein Name erschloss sich mir, der Name Stalvan.\n\nSucht den Amtmann im Rathaus auf und schaut, ob Ihr nicht mehr über diese Person herausfinden könnt. Ich fürchte um unser aller Leben.", sourceObjective = "Sucht Amtmann Daltry im Rathaus von Dunkelhain auf.", sourceObjectiveStatus = "unverified-source-field" }
quests[67] = { id = 67, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Legende von Stalvan", description = "Stalvan, hm? Lasst mich im Stadtverzeichnis nachsehen.\n\nStalvan... Stalvan... mal sehen. Ah, hier ist es! Ich habe hier einen Eintrag über einen gewissen Stalvan Dunstmantel. Die letzte bekannte Adresse ist die Schule in Mondbruch. Liebe Güte, das nenne ich veraltet!\n\nWürdet Ihr mir einen Gefallen tun? Falls Ihr zufällig nach Mondbruch kommt, dann lasst es mich wissen, wenn Ihr an neue Informationen über diese Person geraten solltet. Ich habe meine Unterlagen gern auf dem neuesten Stand.", sourceObjective = "Begebt Euch zur Schule in Mondbruch und bringt Amtmann Daltry alle neuen Informationen über Stalvan Dunstmantel.", sourceObjectiveStatus = "unverified-source-field" }
quests[68] = { id = 68, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Legende von Stalvan", description = "In der alten Schließkiste findet Ihr einen verstaubten, nie abgeschickten Brief.", sourceObjective = "Bringt Amtmann Daltry den verstaubten, nie abgeschickten Brief.", sourceObjectiveStatus = "unverified-source-field" }
quests[69] = { id = 69, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Legende von Stalvan", description = "Ach du liebes bisschen! Das ist mir beim ersten Mal ja glatt entgangen! Hier im Verzeichnis steht beim Eintrag für diesen Stalvan direkt unter der ersten Adresse noch eine weitere, die zum Teil durchgestrichen ist. Es scheint, als wäre er zum Gasthaus \"Zur Höhle des Löwen\" drüben in Goldhain unterwegs gewesen. Vielleicht solltet Ihr dort nachfragen, {name}.", sourceObjective = "Begebt Euch zum Gasthaus \"Zur Höhle des Löwen\" und fragt dort nach, ob jemand schon einmal den Namen Stalvan gehört hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[70] = { id = 70, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Legende von Stalvan", description = "Den Namen Stalvan hab ich schon mal gehört... Ach, jetzt fällt's mir wieder ein.\n\nVor vielen Jahren betrat an einem stürmischen Abend ein Bote dieses Haus, der Unterkunft für die Nacht suchte. Es war noch nicht ganz Mitternacht, da kam der Mann schreiend die Treppe heruntergerannt. Er war bleich wie der Tod vor Angst. Nur mit seinem Nachtgewand bekleidet verschwand er im Regen.\n\nIn der Eile vergaß er seine Briefe in der Truhe oben und kam nie zurück, um sie abzuholen. Es ist ein Brief dabei von diesem Stalvan, den Ihr erwähntet, adressiert an den Kanaldistrikt in Sturmwind. Ihr dürft ihn gern haben.", sourceObjective = "Holt Stalvans niemals zugestellten Brief aus der Truhe und liefert ihn im Kanaldistrikt von Sturmwind ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[71] = { id = 71, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meldung an Thomas", description = "Nun habt Ihr beide Medaillons. Bringt sie an die Brücke zu Wache Thomas, damit er erfährt, welches Schicksal seine beiden Kameraden erlitten haben.", sourceObjective = "Bringt die Medaillons von Rolf und Malakai zu Wache Thomas an die östliche Brücke von Elwynn.", progress = "Hallo, {name}. Habt Ihr herausgefunden, was aus Rolf und Malakai geworden ist?", completion = "Damit bestätigt Ihr meine Befürchtungen, {name}. Die Murlocs sind eine Bedrohung, die wir nicht länger ignorieren können.", sourceObjectiveStatus = "unverified-source-field" }
quests[72] = { id = 72, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Legende von Stalvan", description = "Mein Vater war der Verwalter des Besitzes, lange bevor ich es wurde. Nach dem Massaker war er derjenige, der das Blut aufwischen und aufräumen musste. Aber das tut nichts zur Sache.\n\nDie letzten Gelder aus dem Flintridge-Fonds sind versiegt und jetzt müssen die letzten Stücke aus dem Familienbesitz versteigert werden. Daran sind nur diese Steuereintreiber schuld. Aber wenn Ihr wirklich dringend mehr erfahren wollt, dann dürft Ihr diesen Kram hier gern durchsehen. Wer weiß, was Ihr findet.", sourceObjective = "Durchsucht die verpackten Besitztümer nach Hinweisen.", sourceObjectiveStatus = "unverified-source-field" }
quests[74] = { id = 74, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Legende von Stalvan", description = "In der Kiste findet Ihr verschiedene Dinge: muffige Erbstücke, ein Familienportrait, einige Jagdtrophäen und ein paar alte Bücher. Fast schon am Boden der Kiste findet Ihr unter einer Keramikvase eine zerrissene Tagebuchseite.", sourceObjective = "Die zerrissene Tagebuchseite, die Ihr gefunden habt, gibt Euch den nächsten Hinweis.", sourceObjectiveStatus = "unverified-source-field" }
quests[75] = { id = 75, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Legende von Stalvan", description = "Als ich hier eingezogen bin, stand oben schon eine Truhe mit Pergamenten darin. Kurz nach meinem Einzug habe ich sie mir einmal angesehen, aber bald darauf konnte ich nur noch verschwommen sehen und da hab ich's dann gelassen. \n\nTut einem alten, halb blinden Mann einen Gefallen und seht Euch selbst mal in der Kiste oben um, ob Ihr vielleicht etwas findet, das Euch bei Eurer Suche nach diesem Stalvan weiterhelfen kann. Ich bin mir ziemlich sicher, dass da eine verblasste Tagebuchseite dabei ist, die Euch interessieren müsste. Bringt sie mir und ich werde sehen, was ich tun kann, um Euch zu helfen.", sourceObjective = "Marschall Haggard möchte, dass Ihr in der Kiste oben nach der verblassten Tagebuchseite sucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[76] = { id = 76, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Jaspismine", description = "Dank Euch wissen wir jetzt, dass Kobolde sich in der Tiefenschachtmine eingenistet haben. Jetzt brauchen wir noch einen Späher, der die weiter entfernte Jaspismine untersucht.\n\nErforscht die Jaspismine und bestätigt mir, ob sich dort tatsächlich Kobolde aufhalten. Die Mine erreicht Ihr, indem Ihr der Straße nach Osten folgt, bis Ihr zum Turm von Azora kommt. Wenn Ihr Euch am Turm nach Norden wendet, dann findet Ihr die Mine im Vorgebirge.", sourceObjective = "Erforscht die Jaspismine und kehrt dann nach Goldhain zu Marschall Dughan zurück, um ihm Bericht zu erstatten.", completion = "Kobolde in der Jaspismine, sagt Ihr? Verflucht noch eins! Die Lage wird von Minute zu Minute schlimmer!\n\nVielen Dank für Euren Bericht, {name}. Aber ich wünschte mir, Ihr hättet bessere Nachrichten gebracht.", sourceObjectiveStatus = "unverified-source-field" }
quests[77] = { id = 77, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine schleimige Angelegenheit", description = "Ich besitze Originalverpackungsmaterialien für den Wein, den Dran Droffers will. Ich werde Euch dabei helfen, den Wein für Maltons ungehobelten Vater zu verpacken... für einen Unkostenbeitrag in Höhe zweier weiterer Flaschen besagten Weins. Sie befinden sich in Kisten, die Ihr in dem verlassenen Stützpunkt der Horde in der Nähe vom Lauerfels findet.\n\nDas heißt, dass es eine anstrengende Aufgabe wird. Ihr werdet bei den Ruinen stinkende Schleime und Schlamme vorfinden; angeblich werden sie von einer Art Oberschlamm geführt. Beschafft dessen ungeachtet den Wein und kehrt hierher zu mir zurück, um ihn zu verpacken.", sourceObjective = "Holt 10 Flaschen Hinterländer Honigwein aus den Kisten, die sich rund um den verlassenen Stützpunkt der Horde am Lauerfels befinden.", sourceObjectiveStatus = "unverified-source-field" }
quests[78] = { id = 78, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Legende von Stalvan", description = "Ich kenne jemanden, der Euch vielleicht helfen könnte. Damals, als ich noch die Wachen von Sturmwind kommandierte, haben wir immer in der Taverne \"Zum Roten Raben\" in Dunkelhain gesessen und etwas getrunken. Smitts, der Gastwirt dort, kannte sich mit den örtlichen Lehren ziemlich gut aus. Zeigt ihm diese Seite, mal sehen, was er dazu zu sagen hat.", sourceObjective = "Bringt die verblasste Tagebuchseite zu Schankwart Smitts nach Dunkelhain im Dämmerwald.", sourceObjectiveStatus = "unverified-source-field" }
quests[79] = { id = 79, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Legende von Stalvan", description = "Ich habe die Geschichten um diesen Stalvan jahrelang verfolgt. Als vor ein paar Jahren diese Adligen, die hier zu Besuch waren, ermordet wurden, hab ich Haggard bei seinen Nachforschungen begleitet. Ich habe damals diese schlammverschmierten Seiten gefunden, aber es ist uns nie gelungen, die Handschrift mit diesem Verrückten in den Wäldern in Verbindung zu bringen. Eure Spur der Beweise zeigt aber, dass er schuldig ist. Bringt dies sofort zu Kommandant Schwarzhaupt und sagt ihr, was Ihr entdeckt habt!", sourceObjective = "Bringt Kommandant Schwarzhaupt die schlammverschmierte Seite.", sourceObjectiveStatus = "unverified-source-field" }
quests[80] = { id = 80, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Legende von Stalvan", description = "Ich beobachte diesen Widerling Stalvan jetzt schon eine ganze Weile. Aber wenn diese Seite tatsächlich von seiner Hand geschrieben wurde, dann beweist das seine Schuld ohne den letzten Zweifel.\n\nSo lange, wie Amtmann Daltry das Stadtverzeichnis jetzt schon verwaltet, ist er ein wahrer Experte darin geworden, Handschriften zu identifizieren. Zeigt ihm diese Seite und stellt fest, ob die Schrift dieselbe ist wie diejenige der Unterschrift im Verzeichnis.", sourceObjective = "Zeigt Amtmann Daltry die blutbefleckte Tagebuchseite.", sourceObjectiveStatus = "unverified-source-field" }
quests[81] = { id = 81, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weinlieferung", description = "Ich habe zusätzliche Vorsichtsmaßnahmen getroffen und nicht nur Drans verpackte Welle in dem Fass sicher untergebracht, sondern auch die zusätzlichen Wellenflaschen, die er klaut. Auch wenn ich nicht viel von Dran halte, so gibt es doch nichts Schlimmeres als ein durchgeschütteltes Wellenbouquet. Bitte, bitte, keine Ursache.\n\nBringt jetzt Euer Fass zu Dran Droffers in seinem Kramladen in Orgrimmar. Entbietet meine besten Grüße bitte auch Malton und lasst ihn wissen, dass uns sein Besuch eine große Ehre wäre, falls es ihn jemals nach einem feinen Getränk und noch feineren Trinkkumpanen gelüstet.", sourceObjective = "Liefert das Fass nach Orgrimmar an Dran Droffers.", sourceObjectiveStatus = "unverified-source-field" }
quests[82] = { id = 82, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erkundung des Giftigen Unterschlupfes", description = "Tja, diese Berichte über die Käfer... wir wissen, dass sie die Teiche trocken legen, die sich dort befanden, wo sich der Giftige Unterschlupf befindet. Was wir NICHT wissen, ist, na ja, alles andere.\n\nWir müssen als Erstes herausfinden, wer unser Feind ist! Begebt Euch bitte in den Giftigen Unterschlupf und besorgt ein paar Stücke dieser Tierwesen. Holt fünf von diesen Teilen von den dortigen Centipaar und bringt sie dem Alchemisten Stößelbruch zur Untersuchung. Wenn er sich damit beschäftigt, werden wir schon herausfinden, worum es sich handelt!", sourceObjective = "Bringt fünf Centipaarinsektenteile vom Giftigen Unterschlupf nach Gadgetzan zum Alchemisten Stößelbruch.", sourceObjectiveStatus = "unverified-source-field" }
quests[83] = { id = 83, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feine Leinenwaren", description = "Die Schläger in Elwynn tragen Leinenstoff, aus dem ich feine Leinenwaren herstellen kann.\n\nBringt mir Leinenfetzen und ich mache euch daraus etwas Nützliches.\n\nIhr findet diese gesetzlosen Verbrecher in kleinen Lagern überall in Elwynn.", sourceObjective = "Bringt 6 Leinenfetzen ins Holzfällerlager des Osttals zu Sara Roderwald.", progress = "Ich habe fast kein Leinen mehr, {name}. Bringt Ihr mir welches?", completion = "Ah ja, das sind schöne Stofffetzen, obwohl der Stoff ein wenig rau ist...\n\nHier, bitte schön!", sourceObjectiveStatus = "unverified-source-field" }
quests[84] = { id = 84, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück zu Billy", description = "Hier, bitte schön. Und wenn Ihr Billy die Pastete gebt, dann sagt ihm, ich hoffe, er erstickt daran!", sourceObjective = "Bringt die Schweinebauchpastete zu Billy Maclure in den Weinbergen der Maclures.", progress = "Aaah... Ich bin am Verhungern! Habt Ihr die Pastete für mich, {name}?", completion = "Mmmm, lecker! Diese Pastete ist perfekt!\n\nIch glaube, langsam kommt mein Gedächtnis wieder...", sourceObjectiveStatus = "unverified-source-field" }
quests[85] = { id = 85, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die verlorene Halskette", description = "Ich habe meine Halskette verloren und ich glaube, dieser Tunichtgut Billy Maclure hat sie genommen! Normalerweise treibt er sich immer wie eine kleine Ratte in den Weinbergen der Maclures östlich von hier herum. \n\nBringt mir meine Halskette zurück, wenn Ihr das Herz einer alten Witwe erfreuen wollt.", sourceObjective = "Sprecht mit Billy Maclure.", completion = "Ihr habt was verloren? Also ich hab keine Kette genommen, denn ich bin kein Dieb!\n\nIch weiß vielleicht, wer's war, aber... <grins>... ich hab einfach zu viel Hunger, um drauf zu kommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[86] = { id = 86, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pastete für Billy", description = "Wenn ich 'ne Pastete kriegen würde, dann könnte ich Euch vielleicht sagen, wer die Kette hat. Ach, und wisst Ihr was? Diese alte Dame Bernice auf dem anderen Hof da macht ganz tolle Schweinebauchpasteten. \n\nWenn Ihr ihr ein bisschen zartes Eberfleisch von den Ebern bringt, die immer um unsere Höfe herumstromern, und ihr sagt, dass es für einen guten Zweck ist, dann backt sie Euch vielleicht eine Pastete.", sourceObjective = "Bringt 4 Portionen zartes Eberfleisch zu Tantchen Bernice Steinfeld auf dem Hof der Steinfelds.", progress = "Ich halte es nicht für richtig, den frechen Jungen, der meine Kette überhaupt erst gestohlen hat, dafür auch noch zu füttern, aber wenn es sein muss, damit ich mein Eigentum wiederbekomme, dann soll es eben so sein.\n\nHabt Ihr das Eberfleisch?", completion = "Das Fleisch von wilden Ebern ist zwar fade, aber wenn man es lange genug mit den richtigen Gewürzen köcheln lässt, dann wird eine ganz vorzügliche Pastete daraus!", sourceObjectiveStatus = "unverified-source-field" }
quests[87] = { id = 87, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goldzahn", description = "Ich hab in der Nähe von der Tiefenschachtmine gespielt und da hab ich, glaub ich, die Kette von der alten Dame fallenge... äääh, gesehen. Fragt mich nicht, wie die dahin gekommen ist, ich war's nicht!\n\nNa egal, jedenfalls hab ich diesen großen Kobold gesehen, der hatte einen Goldzahn und der hat die Kette aufgehoben und ist zurück in seinen Bau über der Mine gerannt. Wenn Ihr diesen Kobold findet, dann findet Ihr auch die Halskette, ehrlich! Ich schwör's!", sourceObjective = "Bringt Berenices Halskette zu \"Tantchen\" Berenice Steinfeld auf dem Hof der Steinfelds.", progress = "Hallo, {name}. Habt Ihr meine Halskette gefunden?", completion = "Oh, Ihr habt sie tatsächlich gefunden! Danke, danke, mein Lieber!\n\nHier, nehmt dies. Es hat meinem Mann gehört und er sagte immer, dass es Glück brächte. Wenn er es doch nur auf seinem letzten Feldzug nicht vergessen hätte! *schnief*", sourceObjectiveStatus = "unverified-source-field" }
quests[88] = { id = 88, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prinzessin muss sterben!", description = "Die Brackbrunns haben eine preisgekrönte Sau namens Prinzessin. Dass dieses Tier so riesig geworden ist, das kommt nur daher, dass es immer hier herübergeschlichen kommt und mein Gemüse frisst!\n\nZufällig ist die Sau gerade hier. Sie muss sterben! Bringt mir ihr Halsband zum Beweis und ich werde Euch für Eure Mühen entlohnen.\n\nIhr findet Prinzessin mitten in unserem Wassermelonenbeet. Schnappt sie Euch!", sourceObjective = "Tötet Prinzessin, nehmt ihr Halsband an Euch und bringt es zu Mutter Steinfeld auf dem Hof der Steinfelds.", progress = "Habt Ihr sie schon gesehen? Habt Ihr sie erwischt?", completion = "Welch ein Glück! Dieses Schwein war schon so fett, dass es bestimmt bald unsere gesamte Ernte gefressen hätte! Ich danke Euch, {name}.\n\nNun, könnt Ihr mit einem dieser Dinge hier etwas anfangen?", sourceObjectiveStatus = "unverified-source-field" }
quests[89] = { id = 89, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Immerruhbrücke", description = "Während der letzten Invasion der Orcs waren wir gezwungen, unser Eisen einzuschmelzen, um Kugeln, Schwerter und Rüstungen herzustellen. Wir haben Sturmwind benachrichtigt, dass wir eine neue Lieferung Materialien benötigen. Aber eine Bande von Rotkammgnollen hat die Karawane überfallen und sich dann in die Hügel hinter Seenhain zurückgezogen.\n\nJetzt gehen uns langsam die Vorräte aus, die wir brauchen, um die Brücke wieder aufzubauen. Wenn Ihr mir 5 Eisenspitzen und 5 Eisennieten bringt, {name}, dann sollt Ihr dafür belohnt werden. \n\nUnd jetzt an die Arbeit!", sourceObjective = "Bringt 5 Eisenspitzen und 5 Eisennieten nach Seenhain zu Großknecht Oslow.", sourceObjectiveStatus = "unverified-source-field" }
quests[90] = { id = 90, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gewürzte Wolfkebabs", description = "Gewürzter Wolfskebab ist eine Spezialität des Hauses! Natürlich kann ich Euch welchen machen. Aber ich brauche erst die Zutaten dafür. Bringt mir 10 magere Wolfflanken sowie Würzkräuter aus Sturmwind. Hier im Wald streifen so viele Wölfe herum, da werdet Ihr kein Problem haben, an die Wolfflanken zu kommen, da bin ich mir sicher. Und für die Kräuter sucht ihr am besten Felicia Gump in ihrem Blumenladen im Kanaldistrikt von Sturmwind auf.", sourceObjective = "Beschafft Euch 10 magere Wolfflanken und Würzkräuter aus Sturmwind und kehrt dann zu Küchenchef Grual nach Dunkelhain zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[91] = { id = 91, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Gesetz des Solomon", description = "Ein Feind Sturmwinds hat sich im östlichen Vorläufer des Rotkammgebirges niedergelassen. Dieser verderbte Schurke bedient sich des Übernatürlichen, um unsere Stadt und ihre Einwohner in Angst und Schrecken zu versetzen. Er betreibt sein übles Geschäft unter dem Namen Morganth.\n\nMorganth kontrolliert jetzt den Schattenfellklan. Die Gnolle tun alles, was er ihnen befiehlt. Wie es das Gesetz von Seenhain vorsieht, steht auf die Unterstützung eines im Königreich gesuchten Verbrechers die Todesstrafe.\n\nDiese abscheulichen Gnolle verdienen den Tod!\n\nGebt 10 Schattenfellanhänger bei mir ab, dann erhaltet Ihr eine Belohnung.", sourceObjective = "Bringt 10 Schattenfellanhänger ins Rathaus von Seenhain zu Büttel Conacher.", sourceObjectiveStatus = "unverified-source-field" }
quests[92] = { id = 92, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rotkammgulasch", description = "Ich würde liebend gern Rotkammgulasch für Euch kochen. Aber es gibt da ein kleines Problem. Erst kürzlich musste ich während des Orcaufstands eine ganze Brigade von Soldaten der Armee von Sturmwind verpflegen. Jetzt ist meine Vorratskammer leer. Aber wenn Ihr mir die Zutaten besorgt, dann mache ich das gern für Euch.\n\nBringt mir einfach 5 Stücke zähes Kondorfleisch, 5 große Geiferzahnschnauzen und 5 Portionen knuspriges Spinnenfleisch.", sourceObjective = "Küchenchefin Breanna aus Seenhain möchte 5 Stücke zähes Kondorfleisch, 5 große Geiferzahnschnauzen und 5 Portionen knuspriges Spinnenfleisch.", sourceObjectiveStatus = "unverified-source-field" }
quests[93] = { id = 93, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwärzliche Krebsküchlein", description = "Ich verrate Euch ein kleines Geheimnis: Schwärzliche \"Krebs\"-Küchlein werden eigentlich aus Spinnenbeinen gemacht! Ich weiß, das ist irgendwie eklig, aber die Küchlein schmecken lecker, ein bisschen scharf und eignen sich ganz ausgezeichnet zum Knabbern. Wenn Ihr mir einige klebrige Spinnenbeine bringt, dann zaubere ich Euch ein paar.\n\nIch habe gehört, dass sich Giftweberspinnen ausgezeichnet dafür eignen - sie haben ihr Nest im Norden, zwischen dem Vorgebirge und dem Fluss.", sourceObjective = "Beschafft 6 klebrige Spinnenbeine und bringt sie nach Dunkelhain zu Küchenchef Grual.", sourceObjectiveStatus = "unverified-source-field" }
quests[94] = { id = 94, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein wachsames Auge", description = "Mein Widersacher Morganth ist ein böser Magier von großer Macht, der im Turm von Ilgalar im Rotkammgebirge lebt. Ich habe eine Methode entwickelt, mit der ich ihn ausspionieren kann: Mit dem Auge von Azora ist es mir möglich, ihn von weitem zu sehen.\n\nDoch um seine Gedanken zu erforschen... ja, dazu benötige ich noch weitere Hilfe.\n\nWenn Ihr gewillt seid, dies zu tun, dann bringt meine Glyphe von Azora zum Turm von Ilgalar. Legt sie auf die Löwenstatue in der Nähe des Turms.\n\nSobald dieses getan ist, wird die Macht von Azora mir Visionen von Morganths zukünftigen Plänen gewähren.", sourceObjective = "Bringt die Glyphe von Azora zur Löwenstatue in der Nähe des Turms von Ilgalar im Rotkammgebirge.", sourceObjectiveStatus = "unverified-source-field" }
quests[95] = { id = 95, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Svens Rache", description = "Früher arbeitete ich auf einem der Höfe im Südosten... bis einmal in meiner Abwesenheit Dunkle Reiter vom Gebirgspass der Totenwinde herunterkamen, meinen Hof überfielen und meine Familie abschlachteten.\n\nAls ich zurückkehrte, sah ich eine schattenhafte Gestalt, die sich bei meiner Scheune herumtrieb und dort etwas vergrub. Sie floh, ehe ich sie erreichen konnte, und ich hatte keine Zeit, mich mit ihr aufzuhalten, da ich den Dunklen Reitern dicht auf den Fersen war. Und so habe ich nie entdeckt, was die Gestalt dort versteckte.\n\nWenn Ihr herausfinden könntet, was jene schattenhafte Gestalt dort vergrub, dann wäre ich Euch dankbar. Das Versteck befindet sich hinter dem alten Baumstumpf in der Nähe meiner Scheune.", sourceObjective = "Begebt Euch zu Svens Hof und findet heraus, was hinter dem alten Baumstumpf vergraben wurde.", sourceObjectiveStatus = "unverified-source-field" }
quests[96] = { id = 96, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf des Wassers", description = "Nehmt Splitter. Nehmt Splitter und gebt Leben.\n\nGebt Leben und versteht. Versteht, Wasser ist Leben... Verderbnis beendet Leben.\n\nIhr schützt und gebt Leben mit der Macht des Wassers.Ihr erlernt:", sourceObjective = "Bringt den Splitter des Wassers zu Islen Wasserdeuter am Tidustritt im Brachland.", sourceObjectiveStatus = "unverified-source-field" }
quests[97] = { id = 97, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Legende von Stalvan", description = "Kommandant Schwarzhaupt muss unverzüglich erfahren, dass die Handschriften identisch sind, {name}! Ihr Verdacht hat sich also bestätigt.", sourceObjective = "Berichtet Kommandant Schwarzhaupt die Neuigkeiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[98] = { id = 98, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Legende von Stalvan", description = "Stalvan Dunstmantel hat ein Leben der Verworfenheit gelebt und unschuldige Opfer starben von seiner Hand. Zweifellos hat er noch zahllose andere Verbrechen begangen und nun wird Dunkelhain von diesem Wahnsinnigen bedroht. Das Licht allein weiß, welche schmutzigen Pläne er jetzt ausheckt. Deswegen brauche ich Eure Hilfe, {class}. Begebt Euch zu seiner Hütte ein kleines Stück nördlich der Stadt und schaltet Stalvan ein für alle Mal aus.\n\nSobald die Tat vollbracht ist, begebt Euch zu Madame Eva und zeigt Ihr den Ring seiner Familie. Schließlich war es ihre Vorahnung, die zu dieser entsetzlichen Entdeckung führte. Doch jetzt kann ganz Dunkelhain dank ihr wieder ruhiger schlafen.", sourceObjective = "Tötet Stalvan Dunstmantel und zeigt Madame Eva den Ring seiner Familie.", sourceObjectiveStatus = "unverified-source-field" }
quests[99] = { id = 99, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arugals Torheit", description = "Je mehr ich über Arugals Magie erfahre, umso mehr wächst meine Verachtung für diesen jämmerlichen Narren. Bald werde ich meine Studien zu seiner so genannten 'Arznei' beendet haben.\n\nMein Wissen wird vollständig sein, sobald ich herausgefunden habe, welche Verzauberung die seltsamen Zustände in Lohenscheit verursacht. Tagsüber scheinen die Arbeiter dort ganz gewöhnliche Menschen zu sein. Doch sobald die Sonne untergeht, verwandeln sich die Dorfbewohner in Mondzornworgs.\n\nIch muss Energie aus den verzauberten Fesseln ziehen, die Arugal auf sie gewirkt hat. Bringt mir 6 verzauberte Lohenscheitfesseln, {name}.", sourceObjective = "Bringt Dalar Morgenweber 6 Lohenscheitfesseln zum Grabmal.", sourceObjectiveStatus = "unverified-source-field" }
quests[100] = { id = 100, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf des Wassers", description = "Noch während die Zauberformel, die Ihr gesprochen habt, verhallt, zuckt ein Meer von Lichtern um Euch herum auf. Das Zischen der Wassertropfen, die mit den Flammen in Berührung kommen, lässt nach und Eure überreizten Sinne spüren, wie die verderbten Geister in Eurer Nähe vernichtet werden.", sourceObjective = "Sprecht mit der schwachen Wassermanifestation am Nördlichen Gezeitenstrom im Silberwald.", sourceObjectiveStatus = "unverified-source-field" }
quests[101] = { id = 101, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Totem des Gegenschlages", description = "Nun, da übernatürliche Mächte den Wald durchziehen, besteht ganz zweifellos die Notwendigkeit, sich zu schützen, {name}. Leise flüstern mir die Winde von einer großen Gefahr, die auf Euch lauert und der Ihr Euch in nicht allzu ferner Zukunft gegenübersehen werdet.\n\nAuch <ein tapferer/eine tapfere:c> {class} wie Ihr sollte sich schützen. Falls Ihr dies wünscht, so bringt mir 10 Ghulfangzähne, 10 Skelettfinger und 5 Phiolen Spinnengift. Dann stelle ich Euch ein Totem des Gegenschlages her und belege es mit einem Zauber, durch den es all denjenigen schadet, die gegen Euch Gewalt anwenden wollen.", sourceObjective = "Bringt 10 Ghulfangzähne, 10 Skelettfinger und 5 Phiolen Spinnengift nach Dunkelhain zu Madame Eva.", sourceObjectiveStatus = "unverified-source-field" }
quests[102] = { id = 102, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Patrouille durch Westfall", description = "Sturmwind hat uns im Stich gelassen. Der üble Gestank der Verderbtheit weht über die Ebenen von Westfall. Dies war und ist mein Heimatland und ich werde die Bürger, die sich zum Bleiben entschlossen haben, nicht verlassen. Wir, die wir früher Bauern waren, werden Widerstand leisten.\n\nEure Aufgabe, so Ihr sie denn annehmt, wird es sein, im Grasland von Westfall auf Patrouille zu gehen. Spürt die widerwärtigen Gnolle auf, die augenscheinlich mit den Dieben aus den Todesminen zusammenarbeiten, und tötet sie. Bringt mir 8 Gnolltatzen und ich werde Euren Mut zu belohnen wissen.", sourceObjective = "Bringt 8 Gnolltatzen auf die Späherkuppe zu Hauptmann Danuvin.", sourceObjectiveStatus = "unverified-source-field" }
quests[103] = { id = 103, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bewahrer der Flamme", description = "Die Nacht, in der die Familie des Leuchtturmwärters starb, war schrecklich. Hilflos musste ich mit ansehen, wie Trübauge der Alte den Angriff befehligte. Doch was geschehen ist, ist geschehen. Nun sorge ich mich vor allem um das Leben der Seeleute, die das Große Meer besegeln und deren Schiffe den trügerischen Felsen vor der Küste gefährlich nahe kommen. Da hier niemand mehr lebt, der die Flamme bewacht, obliegt die Verantwortung nun mir.\n\nHelft mir dabei, die Fackel am Leuchten zu erhalten, und bringt mir 5 Fläschchen Öl von den Erntemonstern.", sourceObjective = "Bringt 5 Fläschchen Öl zu Kapitän Grausohn beim Leuchtturm von Westfall.", sourceObjectiveStatus = "unverified-source-field" }
quests[104] = { id = 104, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bedrohung an der Küste", description = "Als ich auf den Felsen mein Leben aushauchte, hatte ich keine Ahnung, was das Leben nach dem Tode für mich bereithalten würde. In jener Nacht war der Leuchtturm erloschen, weil Trübauge der Alte die Familie des Leuchtturmwärters vertrieben hatte. Die Familie kehrte zurück und zündete die Flamme wieder an, doch Trübauge brachte die willensschwächeren Murlocs dazu, den Leuchtturm noch einmal mit ihm zusammen anzugreifen. Beim zweiten Mal hatte die Familie nicht so viel Glück. Vor meinen Augen starben sie alle, ohne sich wehren zu können.\n\nTötet Trübauge den Alten, wenn Ihr ihn am Ufer seht, und bringt mir eine seiner Schuppen, dann werdet Ihr eine Belohnung erhalten.", sourceObjective = "Bringt Kapitän Grausohn am Leuchtturm von Westfall eine Schuppe von Trübauge dem Alten.", sourceObjectiveStatus = "unverified-source-field" }
quests[105] = { id = 105, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weh dir, Andorhal", description = "Endlich ist die Zeit gekommen Andorhal anzugreifen und den Lich, der die Stadt kontrolliert, zu vertreiben.\n\nDer Lich - Araj der Beschwörer - herrscht von innerhalb der Ruinen der Stadt aus. Er wird von zahlreichen Angehörigen der Geißel bewacht, die über die Überreste des Stadtzentrums wachen, auch sein Gefolge an Leibwächtern ist ausgezeichnet. Ihr werdet einige Verbündete brauchen, um auch nur einen Hauch von einer Chance zu haben, wenn Ihr Euch ihm gegenüberstellen wollt.\n\nVernichtet Araj, {name}, und bringt mir einen Splitter seines Phylakteriums als Beweis!", sourceObjective = "Bringt den Splitter von Arajs Phylakterium zu Hochexekutor Derrington ins Bollwerk in den Westlichen Pestländern.", sourceObjectiveStatus = "unverified-source-field" }
quests[106] = { id = 106, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Junge Liebende", description = "Oh, ein Fluch lastet auf mir! Mein Herz gehört Tommy Joe Steinfeld, aber unsere Familien sind aufs Ärgste miteinander verfeindet. Daher kann ich mich nicht mit ihm treffen, obwohl ich mich doch so sehr danach sehne, sein geliebtes Gesicht zu sehen!\n\nBitte nehmt diesen Brief und gebt ihn Tommy Joe. Normalerweise hält er sich am Fluss im Westen des Hofs der Steinfelds auf, das ist auch von hier aus genau westlich.", sourceObjective = "Gebt Tommy Joe SteinfeldMaybells Liebesbrief.", progress = "Ihr habt was?? Maybell ist der einzige Lichtstrahl in meinem trüben Leben. Schnell, lasst mich ihren Brief sehen!", completion = "Ach! Ich kann es nicht ertragen, dass wir getrennt sind. Ich muss sie unbedingt sehen!", sourceObjectiveStatus = "unverified-source-field" }
quests[107] = { id = 107, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nachricht an William", description = "Ich möchte wetten, William Pestle hat einen Trank, der unsere beiden Liebenden zusammenbringen kann.\n\nHier, bringt William diese Nachricht. Er wohnt im Gasthaus \"Zur Höhle des Löwen\" in Goldhain.", sourceObjective = "Bringt Oma Steinfelds Nachricht zu William Pestle.", progress = "Ihr habt da eine Nachricht von \"Oma\" Steinfeld, hm? Ich habe Mildred schon seit Jahren nicht mehr gesehen! Ich frage mich, was so wichtig ist, dass sie mir schreibt...", completion = "Maybell und Tommy Joe, diese armen Kinder, haben mein ganzes Mitgefühl. Ich kann mich noch gut daran erinnern, wie ich mich einst fühlte, als ich selbst noch jung und verliebt war...\n\nEs muss doch etwas geben, das ich tun kann, um ihnen zu helfen! Lasst mich einen Moment nachdenken...", sourceObjectiveStatus = "unverified-source-field" }
quests[109] = { id = 109, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meldung bei Gryan Starkmantel", description = "Es scheint mir, {class}, als hättet Ihr schon etliche Kämpfe überstanden. Falls Ihr das noch nicht getan habt, solltet Ihr Euch bei Gryan Starkmantel melden. Er ist der Anführer der Volksmiliz, die es sich zur Aufgabe gemacht hat, das Ackerland von Westfall zu beschützen. Ich möchte wetten, er könnte Eure Hilfe gebrauchen. Normalerweise findet man ihn im Steinturm auf der Späherkuppe, ein kleines Stückchen von der Straße weg, mitten in Westfall.", sourceObjective = "Sprecht mit Gryan Starkmantel. Normalerweise findet man ihn im Steinturm auf der Späherkuppe, ein kleines Stückchen von der Straße weg, mitten in Westfall.", sourceObjectiveStatus = "unverified-source-field" }
quests[110] = { id = 110, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Insektenteil-Analyse", description = "Ich werde einige Zeit brauchen, um Kieselschliffs Feldmesserausrüstung durchzusehen... und seine persönlichen Angelegenheiten zu regeln. Mein Bauch sagt mir, dass dies nicht der letzte Verlust ist, den wir durch die Käfer hinnehmen müssen.\n\nGeht bitte zu Alchemist Stößelbruch, um zu sehen, ob er etwas mit den Insektenteilen anfangen konnte, die wir ihm geschickt haben. Wenn sie fertig sind, bringt sie mir.", sourceObjective = "Begebt Euch nach Gadgetzan zu Alchemist Stößelbruch und erkundigt Euch nach der Analyse der Insektenteile.", sourceObjectiveStatus = "unverified-source-field" }
quests[111] = { id = 111, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gespräch mit Oma", description = "Bitte sprecht mit meiner Großmutter, {name}. Wenn irgendjemand einen Weg weiß, wie ich mit Maybell zusammen sein kann, dann ist sie das.\n\nIhr findet sie in unserem Haus, östlich von hier.", sourceObjective = "Sprecht mit Oma Steinfeld.", completion = "Solange die Feindschaft zwischen unseren Familien besteht, sehe ich keine gemeinsame Zukunft für Tommy Joe und Maybell... Aber vielleicht können wir sie ja wenigstens für kurze Zeit zusammenbringen.\n\nHmm, was kann man da machen...", sourceObjectiveStatus = "unverified-source-field" }
quests[112] = { id = 112, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Suche nach dem Tang", description = "Ich könnte einen Unsichtbarkeitsschnaps für Maybell brauen, damit sie sich aus den Weinbergen der Maclures fortstehlen und Tommy Joe sehen kann. Aber um den Schnaps herzustellen, brauche ich etwas Kristalltang.\n\nDieser Tang wächst zwar normalerweise im Meer, aber manchmal wird er auch von den Murlocs gesammelt. Geht und schaut, ob die Murlocs am Kristallsee welchen haben. Der Kristallsee liegt ein kleines Stück östlich von Goldhain.", sourceObjective = "Bringt 4 Kristalltangwedel nach Goldhain zu William Pestle.", progress = "Habt Ihr den Kristalltang? Ich bin mir sicher, Maybell kann es kaum erwarten, zu ihrem Verehrer zu kommen.", completion = "Ihr habt den Tang bekommen. Ausgezeichnet! Wartet noch einen kleinen Moment, während ich den Trank braue...", sourceObjectiveStatus = "unverified-source-field" }
quests[113] = { id = 113, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Insektenteil-Analyse", description = "Der Leitende Feldmesser Rutenwünschels muss diesen Bericht sofort sehen. Eigentlich muss jeder, der lesen kann, diesen Bericht sehen. Wir stehen einer großen und ernsten Bedrohung gegenüber, die nicht nur Tanaris und Gadgetzan, sondern das ganze südliche Kalimdor betrifft, wenn wir nichts unternehmen. Möglicherweise ist sogar ganz Azeroth gefährdet. Dieses Ding macht nicht den Eindruck, als würde es das Interesse verlieren.\n\nLasst Rutenwünschels ein Duplikat des Berichts anfertigen, den Ihr dann an Eure Verbündeten verteilen könnt. Jeder muss von dieser Bedrohung erfahren!", sourceObjective = "Bringt den Bericht nach Gadgetzan zum Leitenden Feldmesser Rutenwünschels. Lasst Euch von ihm eine Kopie des Berichts geben, wie Alchemist Stößelbruch gefordert hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[114] = { id = 114, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Flucht", description = "Bringt der jungen Maybell diesen Unsichtbarkeitsschnaps. Seine Wirkung sollte so lange anhalten, dass sie Tommy Joe besuchen kann.", sourceObjective = "Bringt Maybell Maclure den Unsichtbarkeitsschnaps.", progress = "Habt Ihr Tommy Joe meinen Brief überbracht? Was hat er gesagt?", completion = "Ach du liebe Zeit! Ich fühle mich schuldig, weil ich meine Familie täuschen muss, aber meine Gefühle für Tommy Joe sind einfach zu stark. Ich kann sie nicht ignorieren.\n\nIch danke Euch, {name}. Ich werde den Schnaps trinken, sobald ich eine Möglichkeit dazu habe, und mich zu meinem Liebsten schleichen.\n\nUnd Ihr... bitte nehmt dies.", sourceObjectiveStatus = "unverified-source-field" }
quests[115] = { id = 115, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schattenmagie", description = "Von den Orcs des Schwarzfelsklans wurden zur Unterstützung ihrer Angriffe auf das Rotkammgebirge Schattenzauberer rekrutiert, die von einer dunklen Macht erfüllte Vorrichtungen mit sich führten - Mitternachtskugeln. Diese Kugeln haben den Verteidigern vom Rotkammgebirge schwere Verluste zugefügt und es ist von äußerster Wichtigkeit, dass wir diese dämonbesudelten Gegenstände aus dem Konflikt entfernen.\n\nDurchsucht erschlagene Schattenzauberer des Schwarzfels nach Mitternachtskugeln und bringt sie mir. Ich werde die Kugeln dann vernichten lassen, denn ohne sie wäre die Welt ein wesentlich besserer Ort.", sourceObjective = "Bringt 3 Mitternachtskugeln nach Seenhain zu Marschall Marris.", sourceObjectiveStatus = "unverified-source-field" }
quests[116] = { id = 116, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trockene Zeiten", description = "Mir werden hier gerade die Vorräte knapp, {name}. Alle Flaschen sind fast leer, und die letzte Schnapslieferung hätte schon längst hier eintreffen sollen. Die Orcinvasion ist einfach die Hölle.\n\nVielleicht könnt Ihr Euch ja für mich an die Arbeit machen?\n\nIhr müsst für mich bei Schnapsbart Donnerbräu in den Hügeln von Westfall ein Fässchen Donnerbräu Lagerbier besorgen, ebenso ein Fässlein Merlot aus Sturmwind, eine Flasche Fusel aus Dunkelhain und einen Schlauch mit süßem Rum aus Goldhain. Bringt mir all diese Dinge, dann werde ich dafür sorgen, dass Ihr belohnt werdet.", sourceObjective = "Barkeeper Daniels aus Seenhain braucht ein Fässchen Donnerbräu Lagerbier, ein Fässlein Merlot, eine Flasche Fusel und einen Schlauch mit süßem Rum.", sourceObjectiveStatus = "unverified-source-field" }
quests[117] = { id = 117, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Donnerbräu Lagerbier", description = "Ihr müsst eilen, <mein Freund/Madame>, sollt nicht ruhen, noch rasten\nDenn für unser Lagerbier lohnt sich's zu hasten\nEs schmeckt allen Männern, es schmeckt allen Frauen\nDoch ich brauche noch Hopfen, um das Bier zu brauen.", sourceObjective = "Bringt Schnapsbart Donnerbräu 5 Hopfen, damit er sein besonderes Bier brauen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[118] = { id = 118, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Preis für Hufeisen", description = "Ich habe so viel Eisen dafür verwenden müssen, die Wachen von Sturmwind auszurüsten, dass ich nicht mehr genug Eisen übrig habe, um die Pferde im Stall zu beschlagen!\n\nBringt diese Nachricht zu Schmied Argus nach Goldhain. Darin erkläre ich ihm mein Problem und bitte ihn um eine Lieferung Hufeisen.", sourceObjective = "Bringt Verners Nachricht zu Schmied Argus nach Goldhain im Wald von Elwynn.", sourceObjectiveStatus = "unverified-source-field" }
quests[119] = { id = 119, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück zu Verner", description = "Gut, er soll seine 50 Hufeisen haben.\n\nHier sind sie, schön in eine Kiste verpackt und bereit zum Abmarsch. Sagt Verner, dass es ein Vergnügen war, mit ihm Geschäfte zu machen, und sagt ihm, dass er unbedingt die Nachricht lesen soll, die ich ihm an die Kiste geheftet habe!", sourceObjective = "Kehrt zu Verner Gutmark nach Seenhain im Rotkammgebirge zurück. Gebt ihm die Kiste mit Hufeisen.", sourceObjectiveStatus = "unverified-source-field" }
quests[120] = { id = 120, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Botschaft nach Sturmwind", description = "Wir leben in schwierigen Zeiten, {class}. Unsere Ortschaft ist einer ständigen Belagerung ausgesetzt. Wenn wir keine Verstärkung bekommen, ist unsere Niederlage so gut wie besiegelt. Die Botschaft, die ich Euch nun anvertrauen werde, ist von äußerster Wichtigkeit. Bringt diesen Bericht unverzüglich zu General Marcus Jonathan nach Sturmwind. Sobald Ihr die Nachricht abgeliefert habt, kehrt umgehend zu mir zurück und überbringt mir alle Neuigkeiten, ganz gleich, ob gut oder schlecht. \n\nDoch nun eilt!", sourceObjective = "Magistrat Solomon hat Euch einen Bericht übergeben, der bei General Marcus Jonathan in Sturmwind abgeliefert werden muss. Der Richter möchte, dass Ihr zu ihm zurückkehrt, sobald Ihr die Nachricht zugestellt habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[121] = { id = 121, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Botschaft nach Sturmwind", description = "Während ich auf Antwort vom König warte, möchte ich, dass Ihr diesen Brief zu Magistrat Solomon bringt. \n\nWeggetreten, {class}!", sourceObjective = "Bringt General Marcus Jonathans Antwortschreiben nach Seenhain zu Magistrat Solomon.", sourceObjectiveStatus = "unverified-source-field" }
quests[122] = { id = 122, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bauchschuppen", description = "Ich brauche einige Bauchschuppen von schwarzen Großdrachenwelpen, damit ich die Hufeisen bezahlen kann, die Argus mir aus Goldhain geschickt hat. Wenn Ihr mir 6 solcher Schuppen besorgt, dann kann ich mit einem Teil davon Argus bezahlen - und habe dann immer noch einen Rest übrig, aus dem ich etwas für Euch herstellen kann.\n\nSchwarze Großdrachenwelpen fliegen häufig über das Gebiet südlich von Seenhain, aber sie wandern auch gern herum. Haltet einfach die Augen offen und jagt sie, wenn Ihr sie seht.", sourceObjective = "Sammelt 6 Welpenbauchschuppen von schwarzen Großdrachenwelpen ein und bringt sie ins Rotkammgebirge zu Verner Gutmark.", sourceObjectiveStatus = "unverified-source-field" }
quests[123] = { id = 123, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Sammler", description = "Bei der Notiz handelt es sich um eine Tabelle mit Daten und Zeiten, zu denen jemand, der in der Notiz nur als \"der Sammler\" bezeichnet wird, je eine Lieferung Gold aus den Minen des Waldes von Elwynn erhalten soll.\n\nAus dem Plan geht hervor, dass sich der Sammler anscheinend in der Nähe von Brackbrunns Kürbisbeet in Ost-Elwynn aufhält.\n\nDas klingt, als sei es wichtig. Ihr solltet Marschall Patterson im Holzfällerlager des Osttals davon berichten.", sourceObjective = "Begebt Euch zu Marschall Patterson ins Holzfällerlager des Osttals und gebt ihm den Zeitplan des Sammlers.", progress = "Was?!? Schon seit Monaten arbeiten unsere Leute nicht mehr in den Minen von Elwynn!\n\nZeigt mir mal diese Notiz, die Ihr da habt...", completion = "Hm... Ich habe von diesem \"Sammler\" schon gehört, aber ich weiß nicht, für wen er arbeitet. Vielen Dank für diesen Zeitplan. Er wird uns dabei helfen, das Rätsel zu lösen.", sourceObjectiveStatus = "unverified-source-field" }
quests[124] = { id = 124, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Bellen der Gnolle", description = "Als ob Orcangriffe nicht genug wären! Jetzt schleichen auch noch Gnollschläger und Gnollmystiker auf dem Hügelkamm nördlich von meinem Stall herum und fallen meine Pferde an, wenn diese sich auch nur etwas zu weit vom Stall entfernen...\n\nWenn Ihr diese Gnolle beseitigen könntet, wären meine Pferde und ich Euch sehr dankbar.", sourceObjective = "Tötet 10 Schläger der Rotkammgnolle und 8 Mystiker der Rotkammgnolle und kehrt anschließend zu Verner Gutmark zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[125] = { id = 125, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die verlorenen Werkzeuge", description = "Ich könnte hier wirklich etwas Hilfe gebrauchen, {name}. Jetzt, wo die Stadt belagert wird, bekommen wir hier nur schwer Nachschub. Meine Werkzeuge sollten mit dem Karren von Goldhain aus angeliefert werden, aber die Brücke wurde in die Luft gejagt. Also legten wir die Werkzeuge in ein Boot, aber die Orcs beschossen es mit einem Katapult und trafen auch noch. Na, und bei meinem Pech ist mein Werkzeugkasten natürlich geradewegs bis auf den Grund des Sees gesunken.\n\nWenn Ihr mir meinen Werkzeugkasten wiederbeschafft, {name}, dann soll es Euer Schaden nicht sein.", sourceObjective = "Großknecht Oslow aus Seenhain möchte, dass Ihr seinen Werkzeugkasten vom Grunde des Immerruhsees heraufholt.", sourceObjectiveStatus = "unverified-source-field" }
quests[126] = { id = 126, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheul in den Hügeln", description = "Die Gnolle sind immer noch da draußen, {name}. Ich kann sie bellen hören, wenn sie in den Hügeln oberhalb von Seenhain jagen. Und das Geheul eines Gnolls ist lauter als das aller anderen - das von Jauler, ihrem Anführer.\n\nTötet Jauler und vertreibt sein Rudel in alle vier Winde! Bringt mir seine Tatze zum Beweis.\n\nAber seid vorsichtig! Dieser Gnoll ist nicht umsonst der Anführer seines Rudels. Er ist kein einfacher Köter...", sourceObjective = "Bringt Jaulers Tatze nach Seenhain zu Verner Gutmark.", sourceObjectiveStatus = "unverified-source-field" }
quests[127] = { id = 127, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fischhandel", description = "Der Immerruhsee ist für seinen gefleckten Sonnenfisch berühmt. Die Nachfrage nach diesen Fischen ist enorm hoch - und ich habe bald keine mehr vorrätig!\n\nBringt mir 10 Stück, dann werden wir uns schon handelseinig werden. Und wenn Ihr nicht selbst angeln möchtet oder könnt - na ja, vielleicht bekommt Ihr die Fische ja von den Murlocs!", sourceObjective = "Bringt 10 gefleckte Sonnenfische nach Seenhain zu Dockmeister Baren.", sourceObjectiveStatus = "unverified-source-field" }
quests[128] = { id = 128, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kopfgeld auf den Schwarzfelsklan", description = "Der Schwarzfelsklan muss vernichtet werden. Der Feind ist in unser Land eingedrungen. Diese Berge unterliegen der Oberhoheit des Königs von Sturmwind. Aus bestimmten Quellen haben wir erfahren können, dass die Anführer jeder Einheit im Klan Helden genannt werden. Ihr findet sie in ihrem Lager im Norden, ein kleines Stück westlich von der Straße, die in die Brennende Steppe führt.\n\nMagistrat Solomon möchte diese garstigen Bestien tot sehen. Erschlagt 15 Helden des Schwarzfels und kehrt zu mir zurück.", sourceObjective = "Tötet 15 Helden des Schwarzfels, dann erhaltet Ihr von Wache Howe aus Seenhain eine Belohnung.", sourceObjectiveStatus = "unverified-source-field" }
quests[129] = { id = 129, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein geschenktes Mittagessen", description = "Könntet Ihr mir einen Gefallen tun? Ich habe für Wache Parker ein Mittagessen gemacht, aber er ist gerade auf Patrouille unterwegs... Er ist groß und stark und noch dazu eine Wache von Sturmwind, also kann er auf sich selbst aufpassen, aber ich bin nur eine kleine Stadtbewohnerin - für mich ist das da draußen viel zu gefährlich!\n\nWenn Ihr ihm also sein Mittagessen bringt und anschließend wieder herkommt, dann bekommt Ihr auch ein Mittagessen von mir - umsonst! Parker patrouilliert die Straße, die in den Dämmerwald führt.", sourceObjective = "Bringt Parkers Mittagessen zu Wache Parker. Er ist auf der Straße nach Dunkelhain auf Patrouille.", sourceObjectiveStatus = "unverified-source-field" }
quests[130] = { id = 130, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Besuch im Kräuterladen", description = "Könnt Ihr Darcy ein paar Blumen von mir bringen, wenn Ihr wieder zu ihr geht? Die Blumen bekommt Ihr im Kräuterladen von Seenhain, am westlichen Ende des Ortes.\n\nAber wenn Ihr die Blumen holt, dann sagt Martie, der Kräuterkundigen, nicht, für wen sie bestimmt sind oder wer Euch beauftragt hat, ja?", sourceObjective = "Sprecht mit der Kräuterkundigen des Rotkammgebirges, Martie Jainrose.", sourceObjectiveStatus = "unverified-source-field" }
quests[131] = { id = 131, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Narzissen für eine Dame", description = "Hier habt Ihr Euren Blumenstrauß. Ich habe Narzissen für Euch ausgesucht. Narzissen sind meine Lieblingsblumen.", sourceObjective = "Gebt Darcy den Narzissenstrauß.", sourceObjectiveStatus = "unverified-source-field" }
quests[132] = { id = 132, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Bruderschaft der Defias", description = "Was ich Euch jetzt erzähle, könnte mich das Leben kosten. Die Bande der Defias plant irgendwas Großes. Das Letzte, was ich gehört habe, war, dass sie mit unterschiedlichen Gnollen, Kobolden und sogar Goblins zusammenarbeiten.\n\nBringt Starkmantel diese Nachricht. Darin steht alles, was ich zu dem Thema sagen kann.", sourceObjective = "Bringt Wileys Nachricht nach Westfall zu Gryan Starkmantel.", sourceObjectiveStatus = "unverified-source-field" }
quests[133] = { id = 133, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Ghulbildnis", description = "Ich wohne so weit weg von der Stadt und dem Schutz, den sie bietet, dass es ein Wunder ist, dass die Ghule und die wandelnden Toten mich noch nicht aufgefressen haben! Tatsächlich hat erst gestern ein Rudel Knochenkauer gegen die Wände meines Hauses gehämmert.\n\nIch möchte ein Bildnis herstellen - eine Art \"Vogelscheuche\", nur für Ghule. Dafür brauche ich ein paar Ghulrippen. Die bekommt Ihr von Fleischfressern, Knochenkauern, Hirnfressern, Verfaulten und Seuchenverbreitern.\n\nWenn Ihr mir die Rippen beschafft, bezahle ich Euch in barer Münze.", sourceObjective = "Sammelt 7 Ghulrippen und bringt sie zu Calvinius in seiner Hütte.", sourceObjectiveStatus = "unverified-source-field" }
quests[134] = { id = 134, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ogerdiebe", description = "Vor ein paar Wochen wurde ich von einer Bande Ogern angegriffen, als ich draußen Kräuter sammelte, ziemlich weit von meinem Haus entfernt. Ich lief davon und musste eine Kiste mit wertvollen Werkzeugen und Kräutern zurücklassen.\n\nNachdem sie mich vertrieben hatten, stolzierten die Oger zurück zum Ogerhort im südlichen Dämmerwald. Ich bin mir sicher, dass meine Kiste irgendwo in der Nähe des Hügels sein muss.\n\nBitte, {name}, beschafft mir diese Kiste wieder, denn sie fehlt mir sehr.", sourceObjective = "Bringt Calvinius' Kiste zu Calvinius.", sourceObjectiveStatus = "unverified-source-field" }
quests[135] = { id = 135, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Bruderschaft der Defias", description = "Ich möchte zu gern wissen, was Wiley meinte, als er die Steinmetze erwähnte. Vielleicht ist ihm da nur etwas rausgerutscht. Könnten die Defias irgendwas mit den Steinmetzen zu tun haben? Nur ein Mann weiß das mit Sicherheit: Mathias Shaw, Kopf von SI:7. Zeigt ihm Wileys Nachricht und stellt fest, ob er noch etwas zu diesem immer verzwickter werdenden Rätsel beitragen kann. Falls Ihr Probleme habt, Shaw zu finden, seht in der Kaserne in der Altstadt nach.", sourceObjective = "Bringt Wileys Nachricht nach Sturmwind zu Mathias Shaw.", sourceObjectiveStatus = "unverified-source-field" }
quests[136] = { id = 136, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Käpt'n Sanders' versteckter Schatz", description = "Wenn Ihr das hier lesen tut, dann heißt das, dass der alte Käpt'n Sanders in den Fluten begraben is'. Also tut mein Schatz jetz' Euch gehör'n, Ihr braucht bloß den Hinweisen folgen. \n\nErst müsst Ihr ma' meine Schließkiste finden. Wahrscheinlich is' die jetz' da an der Westküste von Westfall in der Nähe von dem Schiffswrack schon halb im Sand verschwunden. 's gibt da an der Küste massig Schiffswracks, aber bloß einen rostigen Anker. Wenn Ihr den Anker finden tut, dann habt Ihr auch meine Schließkiste gefunden. Da müsst ihr reingucken, denn da steht der nächste Hinweis drin.", sourceObjective = "Findet Käpt'n Sanders Schließkiste und durchsucht sie, um den nächsten Hinweis zu erhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[138] = { id = 138, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Käpt'n Sanders' versteckter Schatz", description = "Der Hinweis auf den Schatz lautet folgendermaßen: Gut gemacht, Kumpel! Jetz' müsst Ihr Euch imma nach Osten halten. Im Osten die Steilhänge hoch, dann weiter nach Osten bis zur Straße. Schaut Euch nach so 'nem ollen verfallenen Kamin nahe bei der Straße um. Dort findet Ihr 'n altes Fass mit Eurem nächsten Hinweis drin.", sourceObjective = "Findet das alte Fass in der Nähe des verfallenen Kamins und durchsucht es nach Eurem nächsten Hinweis.\n\nBereitgestellter Gegenstand:", sourceObjectiveStatus = "unverified-source-field" }
quests[139] = { id = 139, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Käpt'n Sanders' versteckter Schatz", description = "Als Ihr das Fass durchsucht, findet Ihr ein weiteres Stück Pergament. Darauf steht: Also, von dem Fass dort müsst Ihr Euch nach Norden halten tun. Un' dann geht Ihr immer der Nase nach schnurstracks geradeaus, bis Ihr den leeren Henkelkrug sehen tut, der da irgendwo bei so 'ner einzeln stehenden Windmühle oben auf dem Steilhang über dem Meer liegt. Wenn Ihr Euch den Henkelkrug mal genau anguckt, dann findet Ihr vielleicht sogar, was Ihr sucht.", sourceObjective = "Durchsucht den leeren Henkelkrug neben der Windmühle nach dem nächsten Hinweis.\n\nBereitgestellter Gegenstand:", sourceObjectiveStatus = "unverified-source-field" }
quests[140] = { id = 140, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Käpt'n Sanders' versteckter Schatz", description = "Und tatsächlich, ganz unten, fast am Boden des alten Henkelkruges findet sich der nächste Hinweis auf Sanders Schatz. An manchen Stellen ist die Tinte verwischt und das Papier riecht nach Whisky, aber zum Teil kann man den Text noch lesen: Jetz', wo Ihr mein'n alten Whiskykrug gefunden habt, habt Ihr den Schatz schon so gut wie in der Tasche. Von der Flasche aus müsst Ihr Euch einfach nach Westen halten und runter zum Strand geh'n. Und dann heißt es schwimmen! Schwimmt schnurstracks nach Westen, bis Ihr an der Insel seid, da wo meine Schatztruhe drauf is'!", sourceObjective = "Findet Käpt'n Sanders' Truhe und öffnet sie. Darin befindet sich Eure Belohnung.\n\nBereitgestellter Gegenstand:", sourceObjectiveStatus = "unverified-source-field" }
quests[141] = { id = 141, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Bruderschaft der Defias", description = "Die Gilde der Steinmetze wurde von einem Mann namens Edwin van Cleef geführt. Van Cleef war dafür verantwortlich, dass Sturmwind wieder aufgebaut wurde, nachdem die Orcs es im Ersten Krieg dem Boden gleichgemacht hatten. Anscheinend waren van Cleef und seine Leute nicht zufrieden damit, wie der König sie behandelte, nachdem der Wiederaufbau vollendet war. Das könnte den einen oder anderen Sachverhalt erklären.\n\nIch habe Eurem Meister in Westfall einen ausführlicheren Bericht geschrieben. Bringt ihn sofort zu ihm!", sourceObjective = "Bringt Shaws Bericht nach Westfall zu Gryan Starkmantel.", sourceObjectiveStatus = "unverified-source-field" }
quests[142] = { id = 142, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Bruderschaft der Defias", description = "Wir müssen herausfinden, wo genau sich das Versteck der Defias befindet. {name}, meine Späher berichten mir, dass ein Bote der Defias auf der Straße zwischen Mondbruch, dem Goldküstensteinbruch und dem Jangoschacht gesehen worden ist. Ich möchte, dass Ihr ihn fangt. Wenn er Widerstand leistet, tötet ihn und bringt mir alles, was er bei sich trägt.", sourceObjective = "Spürt den Boten der Defias in Westfall auf und bringt die Nachricht, die er bei sich hat, zu Starkmantel.", sourceObjectiveStatus = "unverified-source-field" }
quests[143] = { id = 143, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Botschaft nach Westfall", description = "Irgendetwas stimmt mit der Armee von Sturmwind nicht. Sie hätte längst mit einem größeren Aufgebot hier sein müssen. Doch Zeit ist ein Luxus, den wir nicht haben. Ich werde nicht dabeistehen und tatenlos zusehen, wie die Bewohner von Seenhain ihr Leben geben. Nein. Ich muss versuchen, von anderer Stelle her Hilfe zu gewinnen. Ich habe gehört, dass sich in Westfall eine Volksmiliz gebildet hat.\n\nBringt dieses Hilfegesuch ihrem Anführer, Gryan Starkmantel. Vielleicht können Starkmantels Männer uns hier unterstützen, bis der König Verstärkung schickt.", sourceObjective = "Magistrat Solomon möchte, dass Ihr sein Hilfegesuch nach Westfall zu Gryan Starkmantel bringt.", sourceObjectiveStatus = "unverified-source-field" }
quests[144] = { id = 144, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Botschaft nach Westfall", description = "Es schmerzt mich, Magistrat Solomons Schreiben zu lesen. Offensichtlich hat er von dem Krieg, der hier in Westfall tobt, keine Ahnung. Sonst wäre er nicht so naiv, Hilfe von der Miliz zu erwarten. Wenn Sturmwind nicht auch uns im Stich gelassen hätte, dann hätte es keinen Grund gegeben, die Miliz ins Leben zu rufen.\n\nBringt Eurem Herrn im Rotkammgebirge diese Antwort, {class}. Und lasst ihn wissen, dass mir das Herz schwer wird, wenn ich an all die tapferen Leute denke, die ihr Leben verloren haben.", sourceObjective = "Kehrt mit Gryan Starkmantels Antwort zu Magistrat Solomon zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[145] = { id = 145, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Botschaft nach Dunkelhain", description = "Ein weiteres Mal brauche ich Eure Hilfe. Ich habe an Lord Schwarzhaupt geschrieben und ihn gebeten, seine gut ausgebildete Nachtwache hierher zu schicken, damit diese bei der Verteidigung von Seenhain hilft. Es ist von ausnehmender Wichtigkeit, dass diese Nachricht ihn so bald wie möglich erreicht. Doch Ihr müsst äußerste Vorsicht walten lassen. Schwarzhaupt ist der Bürgermeister von Dunkelhain, und das liegt im Herzen des Dämmerwalds. Entfernt Euch nicht von der Straße.", sourceObjective = "Magistrat Solomon möchte, dass Ihr einen Brief zu Lord Schwarzhaupt nach Dunkelhain bringt.", sourceObjectiveStatus = "unverified-source-field" }
quests[146] = { id = 146, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Botschaft nach Dunkelhain", description = "Wenn mir Magistrat Solomon nicht persönlich bekannt wäre, würde ich sagen, der Mann hat den Verstand verloren. Die Nachtwache nach Seenhain schicken, weil Sturmwind die Hilfe verweigert? Die Nachtwache wurde gegründet, weil Sturmwind uns verließ, als diese elende Magie langsam das Land überzog. Wenn ich meine Nachtwache jetzt fortschicke, dann würde diese Stadt vom Bösen überrannt werden, noch ehe die Wachen den Waldrand erreicht hätten.\n\nBringt Eurem Meister in Seenhain dieses Antwortschreiben.", sourceObjective = "Kehrt mit Lord Schwarzhaupts Antwortschreiben zu Magistrat Solomon zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[147] = { id = 147, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Menschenjagd", description = "Wenn der \"Sammler\" Gold aus unseren Minen entnimmt, dann bestiehlt er das Königreich! Führt den Sammler seiner gerechten Strafe zu und bringt mir den Ring, der in dem Abholplan, den Ihr mir gegeben habt, erwähnt wurde.\n\nIm Abholplan steht, dass der Sammler sich bei Brackbrunns Kürbisbeet versteckt hält. Dort solltet Ihr nach ihm suchen.", sourceObjective = "Findet den \"Sammler\" und tötet ihn, dann kehrt mit dem Ring des Sammlers zu Marschall Patterson zurück.", progress = "Habt Ihr den Sammler gefunden? Konntet Ihr herausfinden, für wen er arbeitet?", completion = "Ihr habt ihn gefunden? Gut gemacht, {name}. Der wird nie wieder seine \"Sammlung\" aus den Minen Elwynns bereichern!\n\nUnd dieser Ring, den Ihr gefunden habt, ist interessant... es ist ein Mitgliedschaftsring der alten Steinmetzgilde Sturmwinds. Von denen habe ich schon seit Jahren keine mehr gesehen, seit die Bruderschaft der Defias diese Gegend unsicher gemacht hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[148] = { id = 148, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lieferung aus Dunkelhain", description = "Ach, was soll ich armer, alter Mann nur machen? Ich brauche einige Vorräte aus Dunkelhain, aber das Dorf ist so weit weg und ich bin so alt und schwach... ich würde die Reise niemals überstehen.\n\nKönnt Ihr nach Dunkelhain reisen und mir etwas Geisterhaarfaden mitbringen? Den bekommt Ihr im Haus von Madame Eva am Dorfplatz von Dunkelhain.", sourceObjective = "Sprecht mit Madame Eva.", sourceObjectiveStatus = "unverified-source-field" }
quests[149] = { id = 149, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geisterhaarfaden", description = "Es gibt da einen armen, traurigen Geist, die blinde Mary, die in einem alten Bauernhaus in den Hügeln südlich von Dunkelhain spukt.\n\nHier, nehmt diesen spektralen Kamm und bittet die blinde Mary, sich die Haare zu kämmen. Bringt mir anschließend den Kamm zurück, dann entnehme ich ihm das Geisterhaar, das ich für den Faden brauche.\n\nUnd seht Euch vor, denn in der Nähe dieses Hauses lauern üble Dinge...", sourceObjective = "Bringt der blinden Mary den spektralen Kamm.", sourceObjectiveStatus = "unverified-source-field" }
quests[150] = { id = 150, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Murlocwilderer", description = "Die Murlocs werden zu einem Problem. Große Gruppen der Fischwesen werfen entlang der Ufer des Immerruhsees Anker und fischen, was das Zeug hält! Sie müssen verschwinden, ehe sie den ganzen See leer gefischt haben.\n\nGeht Murlocs jagen! Bringt mir 8 ihrer Flossen, dann habe ich vielleicht etwas für Euch...", sourceObjective = "Bringt 8 Murlocflossen zu Dockmeister Baren in Seenhain.", sourceObjectiveStatus = "unverified-source-field" }
quests[151] = { id = 151, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die arme Graumähne", description = "Die arme Graumähne! Das arme Pferd ist völlig entkräftet nach all der Arbeit, die wir ihm aufgebürdet haben. Ich habe es gefüttert, ehe wir den Hof verließen, aber wir haben natürlich nicht damit gerechnet, dass uns der Wagen kaputtgehen würde. Wenn Ihr der Stute ein paar Hände voll Hafer vom Feld bringen könntet, wäre ich Euch dankbar.\n\nIch wette, es lässt sich rund um die Höfe in Westfall etwas Hafer finden; Ihr müsst nur diesen entsetzlichen Maschinen aus dem Weg gehen, die hier alles übernommen haben. Es gibt einige Höfe südwestlich von hier.", sourceObjective = "Verna Brauenwirbel in Westfall möchte, dass Ihr ihr 8 Hände voll Hafer bringt.", sourceObjectiveStatus = "unverified-source-field" }
quests[152] = { id = 152, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ärger an der Küste", description = "Die vielen Schiffswracks entlang der Küste sind Euch ja vermutlich schon aufgefallen. Das Große Meer ist überaus tückisch. Die Küste von Westfall muss freigehalten werden, damit die Seeleute sicher sind, wenn sie unsere Ufer erreichen. Aber die Murlocs sind ein Problem.\n\nTötet 7 Gezeitenjäger, 7 Krieger, 7 Orakel und 7 Küstenläufer, dann sorge ich dafür, dass Ihr belohnt werdet.", sourceObjective = "Tötet 7 Gezeitenjäger, 7 Krieger, 7 Orakel sowie 7 Küstenläufer und kehrt dann zu Kapitän Grausohn beim Leuchtturm von Westfall zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[153] = { id = 153, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rote Lederkopftücher", description = "Die Defias sind ständig in Bewegung. Ich überwache ihre Aktivitäten jetzt schon seit einiger Zeit. Und dabei habe ich festgestellt, dass viele Bandenmitglieder an den roten Lederkopftüchern zu erkennen sind, die sie tragen.\n\nBringt mir 15 dieser Kopftücher, dann werde ich dafür sorgen, dass Ihr belohnt werdet.", sourceObjective = "Bringt 15 rote Lederkopftücher auf die Späherkuppe zu Späher Galiaan.", sourceObjectiveStatus = "unverified-source-field" }
quests[154] = { id = 154, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr mit dem Kamm", description = "NEIN!!!!!\n\nNehmt ihn weg, nehmt diesen Kamm weg!\n\nIch bin ein Monster und niemand wird mich jemals wieder für schön halten!", sourceObjective = "Bringt den Geisterhaarkamm zu Madame Eva nach Dunkelhain.", sourceObjectiveStatus = "unverified-source-field" }
quests[155] = { id = 155, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Bruderschaft der Defias", description = "Starkmantel denkt also wirklich, <ein/eine:r> {race} wie Ihr könne mich beschützen? Tja, Ihr werdet wohl reichen müssen. Bringt am besten ein paar Freunde mit. \n\nIhr wisst ja, wie's läuft, oder? Ihr haltet mir den Rücken frei und ich bringe Euch zum Versteck der Defias. Aber Ihr solltet besser in meiner Nähe bleiben, denn die Bande der Defias will jetzt meinen Kopf. Wenn die mich mit Euch sehen, werden sie versuchen, mich umzubringen.\n\nSagt mir einfach Bescheid, wenn Ihr und irgendwelche Freunde, die Ihr noch zusammentrommeln könnt, bereit seid loszuziehen.", sourceObjective = "Eskortiert den Verräter der Defias zum Geheimversteck der Defiasbruderschaft. Sobald der Verräter der Defias Euch gezeigt hat, wo sich van Cleef und seine Männer aufhalten, kehrt Ihr mit der Information zu Gryan Starkmantel zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[156] = { id = 156, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Sammeln von Faulblüten", description = "Wenn Ihr mir ein paar Faulblüten bringt, dann kann ich Euch einen Kessel Zombiesaft brauen.\n\nFaulblüten wachsen an seltsamen Orten. Vor allem, habe ich gehört, findet man sie in den Schädeln von Skelettschrecken und Skelettscheusale - nicht, dass ich selbst schon mal nah genug dran war, um nachzusehen!\n\nDer Friedhof von Rabenflucht ist voll von diesen Skeletten. Wenn Ihr die auf Eurer Suche nach den Faulblüten auch noch dezimiert, dann schlagt Ihr zwei Fliegen mit einer Klappe, und ganz Dunkelhain wäre Euch dankbar.", sourceObjective = "Sammelt 8 Faulblüten und bringt sie nach Dunkelhain zu Schankwart Smitts.", sourceObjectiveStatus = "unverified-source-field" }
quests[157] = { id = 157, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abliefern des Fadens", description = "Hier ist Euer Faden, {name}. Man kann tausend Dinge damit machen, zum Beispiel böse Geister binden oder unbelebte Gegenstände mit Leben erfüllen.", sourceObjective = "Bringt Calvinius den Geisterhaarfaden in seine Hütte nördlich des Friedhofs von Rabenflucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[158] = { id = 158, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zombiesaft", description = "Ich brauche eine Flasche eines bestimmten Schnapses, und zwar Zombiesaft. Schankwart Smitts aus der Taverne \"Zum Roten Raben\" in Dunkelhain sollte welchen haben.\n\nUnd bitte sputet Euch, {name}. Die Nächte sind kalt und ich brauche den Schnaps, um meine Adern wieder mit Feuer zu erfüllen!", sourceObjective = "Sprecht mit Schankwart Smitts.", sourceObjectiveStatus = "unverified-source-field" }
quests[159] = { id = 159, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saftlieferung", description = "Hier habt Ihr Euren Zombiesaft...\n\n... aber passt mir mit dem Zeug auf. Es ist stark genug, um die Toten zu erwecken!", sourceObjective = "Bringt Calvinius den Zombiesaft in seine Hütte.", sourceObjectiveStatus = "unverified-source-field" }
quests[160] = { id = 160, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Brief für den Bürgermeister", description = "Bringt diese Nachricht zu Ello Schwarzhaupt, dem Bürgermeister von Dunkelhain.\n\nEr und ich sind alte Freunde, und wenn er den Zettel liest und herausfindet, was Ihr für mich getan habt... dann freut er sich bestimmt genauso sehr, wie ich das tue! Hahahaha!", sourceObjective = "Bringt Calvinius' Brief zu Ello Schwarzhaupt, dem Bürgermeister von Dunkelhain.", sourceObjectiveStatus = "unverified-source-field" }
quests[161] = { id = 161, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine dunkle Bedrohung", description = "Falls mein Verdacht sich bestätigt, ist dies eine Art Sprengpulver. Es muss von einem Sprengstoffexperten analysiert werden, damit wir genau wissen, womit wir es hier zu tun haben. \n\nEs gibt nur einen Mann für diese Aufgabe. Ashlan Schmunzelstein wurde eingeteilt, die Oger in der Festung Mo'grosh im Osten zu beobachten. Begebt Euch dorthin und macht ihn ausfindig, sodass er Licht darauf werfen kann, worum es sich bei der Substanz handelt.", sourceObjective = "Chefingenieur Hinderweir möchte, dass Ihr das sonderbar riechende Pulver zu Ashlan Schmunzelstein, dem Sprengstoffexperten am Mo'grosh Lager bringt.", sourceObjectiveStatus = "unverified-source-field" }
quests[162] = { id = 162, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufstieg der Silithiden", description = "Ihr solltet mit diesem Bericht zu jemandem gehen, der ausreichend Kenntnis von solchen Dingen hat.\n\nIch kenne da diese Nachtelfengelehrte namens Gracina Glaubensmacht. Sie hat viel Zeit mit dem Studium der Lebensformen verbracht, die in der Ökologie von Azeroth einzigartig sind, und sie ist noch dazu Historikerin! Wenn Euch jemand dabei helfen soll herauszufinden, was genau diese Bedrohung ausmacht, und noch viel wichtiger, wie sie zu stoppen ist, gebt ihr den Bericht. Wir werden die Hilfe brauchen.\n\nDas Letzte, was ich hörte, war, dass sie im Tempel des Mondes in Darnassus lebt.", sourceObjective = "Bringt den Bericht über Insektenanalyse nach Darnassus zu Gracina Glaubensmacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[163] = { id = 163, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rabenflucht", description = "Irgendetwas stimmt nicht in Rabenflucht, {name}. Calor schwört, dass jemand - oder etwas - in den Gebäuden dort umgeht. Zwei Nächte in Folge hat er jetzt schon gesehen, wie sich die Schatten bewegten, und in der Nacht vorher habe er Licht in einem der Fenster gesehen, sagte er.\n\nWenn Euch, wie Ihr sagt, die Sicherheit des Dämmerwalds am Herzen liegt, dann findet heraus, welches Monster in Rabenflucht umgeht.", sourceObjective = "Findet heraus, was in Rabenflucht umgeht.", sourceObjectiveStatus = "unverified-source-field" }
quests[164] = { id = 164, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lieferung an Sven", description = "Kennt Ihr Sven? Das ist mal ein Mann, der das Werk des Lichtes vollbringt! Er und seine Anhänger haben ein Lager am nordwestlichen Rand des Dämmerwalds.\n\nLeider sind sie so wenige, dass noch nicht einmal ein einziger Mann abkömmlich ist, um Vorräte aus der Stadt zu holen. Würdet Ihr diese Vorräte bei ihm abliefern?", sourceObjective = "Liefert die Vorräte an Sven.", sourceObjectiveStatus = "unverified-source-field" }
quests[165] = { id = 165, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Einsiedler", description = "Es gab einmal einen alten Mann, der recht häufig in die Stadt kam, um Vorräte einzukaufen, aber ich habe ihn jetzt schon ziemlich lange nicht mehr gesehen. Er lebt draußen in einer Hütte, von der aus man den Friedhof von Rabenflucht überblicken kann, wenn ich mich recht erinnere. Vielleicht solltet Ihr einmal nachsehen gehen, ob dort alles in Ordnung ist.", sourceObjective = "Schaut in der Nähe des Friedhofs von Rabenflucht nach dem alten Mann in der Hütte.", sourceObjectiveStatus = "unverified-source-field" }
quests[166] = { id = 166, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Bruderschaft der Defias", description = "Jetzt gibt es für Euch nur noch eine Aufgabe zu erledigen. Edwin van Cleef muss getötet werden. Zwar stimmt es mich traurig, einen Menschen zum Tode zu verurteilen, doch es ist zum Besten des Volkes von Westfall, wenn van Cleef ein für alle Mal aus dem Verkehr gezogen wird. Bringt mir den Kopf des Schurken, sobald die Tat getan ist.", sourceObjective = "Tötet Edwin van Cleef und bringt seinen Kopf zu Gryan Starkmantel.", sourceObjectiveStatus = "unverified-source-field" }
quests[167] = { id = 167, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oh Bruder...", description = "Wir waren tief unten in einer großen Mine in Westfall, deren Eingang unter einer Scheune in Mondbruch versteckt lag. Keine Ahnung, wo dieses elende Diebesgesindel herkam. Egal, jedenfalls stürzte der Minentunnel über uns ein. Ich hab's nach draußen geschafft, aber die anderen... na ja... von den anderen hat seither niemand mehr etwas gehört.\n\nIhr seht aus, als könntet Ihr vielleicht etwas mehr Glück haben, wenn Ihr dort hineingeht. Wenn Ihr nach meinem Bruder suchen könntet, wäre ich Euch dankbar. Er trug immer sein Forscherliga-Abzeichen bei sich. Wenn Ihr ihn selbst nicht finden könnt, dann würde zumindest das Abzeichen mir etwas Seelenfrieden verschaffen.", sourceObjective = "Bringt Großknecht Distelklettes Abzeichen der Forscherliga nach Sturmwind zu Wilder Distelklette.", sourceObjectiveStatus = "unverified-source-field" }
quests[168] = { id = 168, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Suche nach Andenken", description = "Viele meiner Freunde starben an jenem schrecklichen Tag, als der Minentunnel einstürzte. Wenn Eure Abenteuer Euch in jenen Abschnitt der Mine in Mondbruch führen sollten, dann haltet doch bitte die Augen offen nach jedem Zeichen, anhand dessen man sie identifizieren könnte. Wenn Ihr zum Beispiel ihre Gewerkschaftsausweise finden solltet, so bringt sie mir, dann sehe ich zu, dass ihre Familien informiert werden und damit wenigstens eine Art Schlussstrich unter diesen schrecklichen Unfall ziehen können.", sourceObjective = "Beschafft 4 Gewerkschaftsausweise und bringt sie nach Sturmwind zu Wilder Distelklette.", sourceObjectiveStatus = "unverified-source-field" }
quests[169] = { id = 169, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Gath'Ilzogg", description = "Gesucht! Gath'llzogg, Rädelsführer hinter den Angriffen des Schwarzfelsklans auf Burg Steinwacht und den Überfällen auf die Ortschaft Seenhain. \n\nGath'llzogg ist äußerst gefährlich. Berichten zufolge hat er sich in der kürzlich eroberten Burg eingenistet und plant dort die weiteren Verbrechen des Schwarzfelsklans gegen die menschliche Bevölkerung. Die Orcplage muss um jeden Preis eingedämmt werden. Der tapferen Seele, die Magistrat Solomon den Kopf von Gath'llzogg übergeben kann, winkt eine großzügige Belohnung.", sourceObjective = "Erledigt Gath'llzogg und bringt seinen Kopf zu Magistrat Solomon in Seenhain, um die Belohnung zu erhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[170] = { id = 170, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine neue Bedrohung", description = "Ich hoffe, Ihr seid hier, um uns zu helfen, {class}. Nach dem letzten Angriff der Troggs können wir alle Hilfe gebrauchen, die wir kriegen können.\n\nIch habe gehört, die kleinen Biester sind überall im ganzen Land aufgetaucht, und wie es scheint, ist das Eisklammtal keine Ausnahme. Sie sind kreuz und quer in den Hügeln im Südosten und in der Nähe des gefrorenen Sees gesehen worden.\n\nUnd das ist noch nicht alles. Vor ein paar Nächten haben sie unser Lager im Westen angegriffen und überrannt! \n\nWir haben hier zu wenig Leute, <Jungchen/Mädel>, und wir brauchen ein paar starke Arme, die dabei helfen, die Troggs zurückzutreiben.", sourceObjective = "Balir Frosthammer möchte, dass Ihr 6 Felsenkiefertroggs und 6 bullige Felsenkiefertroggs tötet.", sourceObjectiveStatus = "unverified-source-field" }
quests[171] = { id = 171, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tageseltern der Allianz", description = "Ihr wart die ganze Zeit so gut zu mir, {name}. Nie hätte ich erwartet, während der Kinderwoche so viel Spaß zu haben! Danke schön.\n\nIch wünschte, all die anderen Waisenkinder hätten das Glück, so tolle Dinge zu unternehmen, wie wir. Meint Ihr, wir können Craggle Schlingerkreisel wiederfinden und bekommen einen Schaumstoffschwertständer von ihm? Ich glaube, er schiebt noch immer seinen Karren an den Kanälen rund um den Handelsdistrikt herum. So könnten alle anderen im Waisenhaus ihren Spaß haben!\n\nDanach wird es Zeit für mich, nach Hause zu gehen.", sourceObjective = "Kauft einen Schaumstoffschwertständer von Craggle Schlingerkreisel und bringt dann Euren Schützling in das Waisenhaus von Sturmwind zurück, indem Ihr die Pfeife des Menschenwaisenkindes an Waisenmatrone Nachtigall im Kathedralenviertel übergebt.", progress = "Es ist schön, Euch wiederzusehen, {name}. Habt Ihr die Euch auferlegten Pflichten, für die Ihr Euch während der Kinderwoche freiwillig gemeldet habt, sorgfältig erfüllt?", completion = "Was ist das denn? Ein Geschenk für die Waisenkinder!\n\nMöge der Himmel Euch segnen, {name}. Ihr habt für Randis mehr getan, als es jemand anderem je in den Sinn gekommen wäre. Vielen Dank - Ihr seid ein funkelnder Stern am Himmel der Allianz.\n\nRandis hatte so viel Spaß mit Euch, {name}. Er hat mich gebeten Euch eines seiner Lieblingstierchen zu geben, damit Ihr Euch stets an ihn erinnert.", sourceObjectiveStatus = "unverified-source-field" }
quests[172] = { id = 172, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kinderwoche", description = "Ihr wollt uns tatsächlich hier im Waisenhaus zur Hand gehen? Seid gesegnet, Freund. Eure Unterstützung in der Kinderwoche ist für uns von unschätzbarem Wert.\n\nNehmt diese Pfeife. Sie kann sieben Tage lang verwendet werden – über die ganze Dauer der Kinderwoche hinweg. Durch Benutzung der Pfeife könnt Ihr mit dem Waisenkind sprechen, auf das Ihr aufpasst. Verwendet sie erneut, um das Kind wieder zu entlassen.\n\nDas Kind ist schon ganz aufgeregt und freut sich darauf Euch kennenzulernen. Worauf wartet Ihr noch, {name}, benutzt die Pfeife und trefft Euren Schützling.", sourceObjective = "Benutzt die Pfeife des Orcwaisenkindes, um während der Kinderwoche mit Eurem Schützling zu sprechen.\n\nBereitgestellter Gegenstand:", completion = "Zug zug! Mein Name ist Grunz und ich vermute, Ihr sucht nach mir? Ihr seid ein Abenteurer, genauso wie meine Mama und mein Papa. Meine Matrone sagt immer, dass sie ehrenhaft in der Schlacht gefallen sind. Ich bin so glücklich, Euch zu treffen!\n\nHoffentlich erleben wir zusammen viele lustige Sachen. Es gibt so viele Sachen, die ich gerne einmal machen würde, und die Matrone hat gesagt, dass Ihr diese Woche so etwas wie mein großer Bruder seid. Das finde ich toll!", sourceObjectiveStatus = "unverified-source-field" }
quests[173] = { id = 173, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worgen in den Wäldern", description = "Es scheint, als würden dunkle Dinge unaufhaltsam in den Dämmerwald gezogen. Meister Treuwein hat sich der Aufgabe verschrieben, das Böse und die Ketzerei zu vertreiben. Dank unserer Anstrengungen lebt das Volk von Dunkelhain in Sicherheit.\n\nIhr glaubt, Ihr seid würdig, Euch unserer Gruppe anzuschließen?\n\nEinst dachte ich wie Ihr. Die Selbstzufriedenheit der Wache hatte mich meiner Illusionen beraubt und so schloss ich mich Meister Treuwein an. Wenn Ihr Euch beweisen möchtet, so kann dies nicht durch Worte geschehen.\n\nMesst Eure Fertigkeiten an den Schattenwirkern der Nachtheuler im Schattenhain und im Verrottenden Obstgarten.", sourceObjective = "Tötet für Calor aus Dunkelhain 6 Schattenwirker der Nachtheuler.", sourceObjectiveStatus = "unverified-source-field" }
quests[174] = { id = 174, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Blick zu den Sternen", description = "Mein Freund Cog, der Gnom, hat mir versprochen, mir beim Bau eines Gerätes zu helfen, mit dem ich in die Sterne blicken kann. Jenseits der Magie existiert eine Wahrheit, mit deren Hilfe sich die seltsame Verwandlung des Waldes erklären lässt.\n\nBringt mir eine Bronzeröhre, die von einem geschickten Ingenieur hergestellt wurde. Wenn man nach Cogs Blaupause geht, ist das der erste Schritt.", sourceObjective = "Viktori Prism'Antras aus Dunkelhain möchte, dass Ihr ihm eine Bronzeröhre bringt.", sourceObjectiveStatus = "unverified-source-field" }
quests[175] = { id = 175, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Blick zu den Sternen", description = "Laut Cogs Blaupause brauche ich jetzt etwas, mit dem Licht reflektiert werden kann. Ich erinnere mich an eine Frau namens Mary, die hier in der Gegend eine gewisse Bekanntheit erlangte, weil sie immer einen Handspiegel bei sich trug. Vielleicht könnt Ihr diese Mary aufspüren und sie fragen, ob sie ihn uns für unser Vorhaben vielleicht leiht, weil wir ja eine reflektierende Oberfläche brauchen... Ich glaube, sie wohnte früher im südlichen Dämmerwald...", sourceObjective = "Findet Mary und überredet sie, einen Gegenstand mit reflektierender Oberfläche zu Viktoris Projekt beizusteuern.", sourceObjectiveStatus = "unverified-source-field" }
quests[176] = { id = 176, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: \"Hogger\"", description = "Gesucht: Hogger\n\nEin riesiger Gnoll, Hogger, streunt im südwestlichen Elwynn durch den Wald. Er hat bislang alle Versuche, ihn zu fangen, vereiteln können.\n\nDie Armee von Sturmwind hat ein großzügiges Kopfgeld auf den Gnoll ausgesetzt. Kopfgeldjäger, die sich die Belohnung verdienen möchten, sollten in die Wälder reisen und die Bestie beseitigen.", sourceObjective = "Kümmert Euch um die \"Hogger-Situation\" und kehrt zu Marschall Dughan zurück.", completion = "WAS hat er getan?\n\nNa großartig, jetzt haben wir eine blutrünstige Bestie unter den Pflastersteinen Sturmwinds, die eine ganze Armee von Gnollen befehligt. Definitiv eine Verbesserung. Ich fühle mich schon viel sicherer.\n\nHier habt Ihr Eure Belohnung, {name}. Versprecht mir aber, dass ihr bei Gelegenheit bei den Verlieswachen in Sturmwind vorbeischaut, nur, damit wir auch sicher sein können, dass alles reibungslos verläuft.", sourceObjectiveStatus = "unverified-source-field" }
quests[177] = { id = 177, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Blick zu den Sternen", description = "Der Handspiegel war eines meiner wertvollsten Besitztümer bis zu... dem Vorfall. Danach warf ich den Spiegel hinter der Scheune fort. Es gab da einen irrsinnigen Ghul, der sich früher dort hinten herumgetrieben hat. Vielleicht hat der ihn aufgehoben und mitgenommen. Gerüchten zufolge haust die teuflische Bestie im Friedhof Stille Gärten.", sourceObjective = "Nehmt dem irrsinnigen Ghul den Handspiegel der blinden Mary ab und gebt ihn Viktori in Dunkelhain.", sourceObjectiveStatus = "unverified-source-field" }
quests[178] = { id = 178, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wiederbeschaffung für Theocritus", description = "<Ihr hört eine körperlose Stimme:>\n\nIhr müsst nicht erschrecken. Ich bin Theocritus, Hochmagier des Turms von Azora im Wald von Elwynn. Der Anhänger, den Ihr in Händen haltet, ist ein Mittel zur Kommunikation zwischen den Schattenfellgnollen und Morganth, ihrem Meister.\n\nNach langen Monaten der Forschung glaube ich, dass nun auch ich durch diese Anhänger kommunizieren kann. Wenn Ihr diese Nachricht hören könnt, dann war mein Zauber erfolgreich.\n\nBringt mir diesen Anhänger und ich werde Euch für Eure Dienste belohnen.", sourceObjective = "Bringt den verblassten Schattenfellanhänger zu Theocritus, dem Magier. Er befindet sich im Turm von Azora im Wald von Elwynn.", sourceObjectiveStatus = "unverified-source-field" }
quests[179] = { id = 179, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zwergenausstatter", description = "Was haben wir denn hier? Ihr seht aus, als könntet Ihr was brauchen, was Euch die Hände warm hält, hm?\n\nIch sag Euch, was da helfen würde: ein paar schöne, warme Handschuhe. Und weil ich so ein netter Kerl bin, geb ich Euch doch gern so ein Paar. Unter einer Bedingung, versteht sich.\n\nIhr müsst mir etwas Wolfsfleisch besorgen. Ist doch 'n guter Handel, oder? Ihr bringt mir etwas Wolfsfleisch und ich sorge dafür, dass Ihr Euch keine Frostbeulen an den Fingern holt. Na, was sagt Ihr?", sourceObjective = "Sten Starkarm hätte gern 8 Stücke zähes Wolfsfleisch.", sourceObjectiveStatus = "unverified-source-field" }
quests[180] = { id = 180, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Leutnant Fangor", description = "Gesucht: Leutnant Fangor\n\nBekannter Anführer des Gnollklans der Schattenfelle; arbeitet für Morganth, den Feind der Stadt und des Königreiches. Auf Geheiß von Magistrat Solomon wird der Tod dieses üblen Verräters an Sturmwind gewünscht. Zeigt dem Magistraten seine Tatze zum Beweis, dass er tot ist.", sourceObjective = "Tötet Leutnant Fangor und kehrt mit seiner Tatze zu Magistrat Solomon nach Seenhain zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[181] = { id = 181, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Blick zu den Sternen", description = "Jetzt brauchen wir nur noch einen weiteren Gegenstand, um das Gerät fertig zu stellen. Laut Cogs Blaupause wird eine Linse oder etwas in der Art benötigt. Die einzige Linse, von der ich weiß, dass sie groß genug wäre, wird sehr schwierig zu beschaffen sein.\n\nEs gibt da einen Oger namens Zzarc'Vul, der im Ogerhort im Süden des Dämmerwalds haust. Wenn Ihr könnt, bringt mir sein Monokel, dann werde ich das als unsere Linse verwenden.", sourceObjective = "Findet Zzarc'Vul im südlichen Ogerhort des Dämmerwalds und bringt sein Monokel zu Viktori nach Dunkelhain.", sourceObjectiveStatus = "unverified-source-field" }
quests[182] = { id = 182, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Trollbedrohung", description = "Die Trolle benehmen sich seltsam. Mehr als normalerweise, meine ich. Wir haben sie ja schon vorher Kriegstruppen aufstellen sehen, aber diesmal ist es... anders.\n\nAm wichtigsten ist jetzt, dass wir Ambossar weiter beschützen. Ich habe nicht vor, diese Trolle Ambossar flankieren zu lassen, während es sich auf die Troggs konzentriert. Geht und dünnt ihre Reihen ein wenig aus. Sie müssen sehen, dass wir keinesfalls ohne Verteidigungen dastehen.", sourceObjective = "Tötet 10 Trollwelpen der Frostmähnen.", completion = "Ich hoffe, das reicht aus. Ambossar sollte fürs Erste vor Trollen sicher sein. Jetzt lasst uns herausfinden, was die Trolle so in Aufruhr versetzt hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[183] = { id = 183, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Eberjäger", description = "Es geht doch nichts über einen Tag auf der Eberjagd, wie?\n\nNa ja, hier im Eisklammtal gibt es so viele Eber, dass es fast schon keinen Spaß mehr macht. Man muss sie gar nicht mehr reizen. Sie sind schon aggressiv und angriffslustig, ohne dass man nachhilft. Um genau zu sein, streifen in letzter Zeit so viele Eber durch die Gegend, dass es gefährlich für mich geworden ist, auf die Jagd zu gehen.\n\nIch mach's kurz: Wenn Ihr mir dabei helfen könntet, einige der Eber zu töten, dann würde ich das zu schätzen wissen.", sourceObjective = "Talin Kühnauge möchte, dass Ihr 12 kleine Klippeneber tötet.", sourceObjectiveStatus = "unverified-source-field" }
quests[184] = { id = 184, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brauenwirbels Urkunde", description = "Dies ist eine Besitzurkunde für ein Stück Ackerland in Westfall. Es ist von einem gewissen Theodore Brauenwirbel und seiner Frau Verna unterzeichnet. Auf der Rückseite der Besitzurkunde stehen ein paar hastig hingekritzelte Worte:\n\n\"Wir haben Brauenwirbel etwas bearbeitet und ihm seine Besitzurkunde abgeluchst. Wäre vielleicht ganz nützlich, wenn Ihr Euch auch so eine fälschen wolltet.\n\nUm die Brauenwirbels müssen wir uns jedenfalls keine Sorgen machen. Zuletzt sah ich sie kurz hinter Westfall in einem Wagen mit gebrochener Achse.\"\n\nIhr denkt, die Brauenwirbels hätten ihre Besitzurkunde vielleicht gern zurück...", sourceObjective = "Bringt Brauenwirbels Besitzurkunde zu Jansens Hof in Westfall.", progress = "Wir brauchen hier keine Zivilisten, die sich als Hüter der Gerechtigkeit aufspielen. Überlasst das den Profis.", completion = "Das hat so keinen Sinn. Seht Euch nur das Datum auf diesem Schreiben an. Die Brauenwirbels hocken jetzt schon seit fünf Jahren auf Jansens Hof.\n\nSie haben es nie geschafft, ihren Wagen zu... reparieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[185] = { id = 185, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tigerjagd", description = "Als ich noch ein kleines Mädchen war, brachte mein Vater mir die Kunst der Tigerjagd bei.\n\nIhr werdet feststellen, dass die jungen Katzen sich wesentlich leichter aufspüren und töten lassen. Man findet die jungen Tiger oftmals in der Nähe des Expeditionslagers.\n\nÜbt Euch im Fährtenlesen und seht zu, ob Ihr nicht einige der Wildtiere zur Strecke bringen könnt. Beginnt Eure Jagd im Süden in der Nähe unseres Lagers.", sourceObjective = "Jagt 10 junge Schlingendorntiger.", sourceObjectiveStatus = "unverified-source-field" }
quests[186] = { id = 186, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tigerpirsch", description = "Junge Tiger sind das Eine. Ausgewachsene Tiger zu jagen ist aber eine ganz andere Angelegenheit. Die erwachsenen Schlingendorntiger zu erlegen sollte sich als eine noch größere Herausforderung erweisen.\n\nDie erwachsenen Katzen halten sich meistens im Süden von Kurzens Truppenlager auf der Ostseite des Flusses auf.", sourceObjective = "Jagt 10 Schlingendorntiger.", sourceObjectiveStatus = "unverified-source-field" }
quests[187] = { id = 187, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tigerhatz", description = "Alte Schlingendorntiger sind die stärksten Tiger, die es gibt. Viele Jäger vor Euch sind ihren rasiermesserscharfen Zähnen und schweren Krallen zum Opfer gefallen.\n\nAjeck wird sich freuen, wenn sie hört, dass Ihr gegen sie bestehen konntet. Das größte Rudel dieser Raubkatzen ist im Süden zu finden, in der Nähe der Zerschlagung an der Grenze zum Schlingendornkap.", sourceObjective = "Jagt 5 Alte Schlingendorntiger.", sourceObjectiveStatus = "unverified-source-field" }
quests[188] = { id = 188, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beherrschen der Tigerjagd", description = "Legenden sprechen von einer schwer aufzuspürenden Tigerin... einer Raubkatze, deren Macht selbst die der ausgewachsenen Männchen in den Schatten stellt. Die Jäger von Nesingwarys Expedition haben ihr ohne Erfolg nachgestellt und viele von ihnen sind ihren reißenden Krallen zum Opfer gefallen. Die Leichen dieser Unglücklichen verwesen nun am Fuße ihres Hügels, nördlich von Grom'gol.\n\nDer Name der Bestie lautet Sin'dall.\n\nIhr entschließt Euch, das zu tun, was noch <kein/keine:r> {race} zu Wege gebracht hat: Sin'dall zu jagen, zu töten und ihre Tatze als Trophäe zu erbeuten.", sourceObjective = "Jagt Sin'Dall und kehrt mit ihrer Tatze zurück.", progress = "Wie läuft die Jagd?", completion = "Äußerst beeindruckend, das muss ich schon sagen! Ihr seid wahrlich ein Meisterjäger, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[189] = { id = 189, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ohren der Blutskalpe", description = "Verdammte Trolle! Sie haben im Dschungel schon etliche unserer Agenten getötet und ich habe bereits einige meiner besten Wachen in Scharmützeln mit ihnen verloren. Was das alles kostet! Wie soll ich das nur Baron Revilgaz erklären?\n\nEntschieden handeln... Denk nach, Kebok... Du bist auf den Posten, den du heute hast, nicht durch Rumsitzen gekommen... Ha, ich hab's! Ihr... {name}, richtig? Ihr helft mir doch, oder? Es gibt auch Geld zu verdienen!\n\nFolgender Handel... Ihr bringt mir die Ohren von 15 Trollen der Blutskalpe und ich bezahle Euch gut dafür.", sourceObjective = "Verschafft Euch 15 Ohren der Blutskalpe und bringt sie Kebok in Beutebucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[190] = { id = 190, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pantherjagd", description = "Wenn Ihr zusammen mit dieser Elitegruppe, die Hemet Jr. zusammengestellt hat, an der Jagd teilnehmen wollt, dann müsst Ihr erst beweisen, dass Ihr <ein fähiger Pantherjäger/eine fähige Pantherjägerin> seid. Ihr solltet aber klein anfangen: beschränkt Euch fürs Erste auf die jungen Panther. Mit der Zeit werdet Ihr geübter werden und mehr Erfahrung als Jäger sammeln. Dann werdet Ihr auch ohne Zweifel auf immer gefährlichere Beute stoßen.\n\nBegebt Euch zunächst nach Osten. Kehrt zu mir zurück, wenn Ihr die Pantherjagd gemeistert habt.", sourceObjective = "Jagt 10 junge Panther.", sourceObjectiveStatus = "unverified-source-field" }
quests[191] = { id = 191, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pantherpirsch", description = "Die jüngsten Panther sind für Euch eine leichte Beute gewesen. Panther, die aber schon herangewachsen sind, werden natürlich stärker, schneller und schwieriger zu besiegen sein.\n\nGrößere Pantherfährten führen nach Westen.", sourceObjective = "Jagt 10 Panther.", sourceObjectiveStatus = "unverified-source-field" }
quests[192] = { id = 192, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pantherhatz", description = "Jetzt kommt der schwierige Teil. Je älter ein Panther wird, desto gerissener wird er auch, wird eins mit seiner Umgebung und lässt sich nur noch schwer aufspüren. Diese verschlagenen Panther sind unter dem Namen \"Schattentatzenpanther\" bekannt, weil sie die Angewohnheit haben, plötzlich aus der Dunkelheit über einen herzufallen... und zwar mit einem hungrigen Maul voller Zähne.\n\nWenn Ihr Euch als <ein wahrer Pantherjäger/eine wahre Pantherjägerin> beweisen wollt, dann sind die Schattentatzenpanther der einzige Weg zum Ziel. Sie streifen im Südosten umher, am anderen Flussufer.", sourceObjective = "Jagt 5 Schattentatzenpanther.", sourceObjectiveStatus = "unverified-source-field" }
quests[193] = { id = 193, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beherrschen der Pantherjagd", description = "Ihr habt schon fast bewiesen, dass Ihr die Kunst der Pantherjagd meisterlich versteht. Ein Panther jedoch hat sich Euch bisher entzogen.\n\nEs wird in Liedern von einem mächtigen Panther erzählt, der den Namen Bhag'thera trägt. Ihr werdet ausprobieren, ob es Euch mit Euren Fähigkeiten gelingt, das große Tier zu erlegen.\n\nWenn Ihr den Fangzahn von Bhag'thera zu Erlgadin bringen könnt, sollte das Beweis genug sein, dass Ihr <ein Meister der Pantherjagd/eine Meisterin der Pantherjagd> seid.", sourceObjective = "Erhaltet den Fangzahn von Bhag'thera.", progress = "Ihr seid noch am Leben! Ausgezeichnet! Wie verläuft die Jagd?", completion = "Der große Bhag'thera ist also tot! Meinen Beifall, {name}. Ihr seid wahrlich ein großer {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[194] = { id = 194, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raptorenjagd", description = "Soso, Ihr glaubt also, Eure Jagdfertigkeiten sind erstklassig? Das lässt sich ganz leicht feststellen. Zieht hinaus in den Dschungel und tötet zehn Schlingendornraptoren. Dann werden wir ja sehen, wie gut Ihr als Großwildjäger wirklich seid.\n\nUnd nein, ich werde Euch nicht sagen, wo Ihr sie finden könnt! Die Viecher aufzuspüren ist Teil der Aufgabe.\n\nNa gut. Ihr müsst nach Westen.", sourceObjective = "Jagt 10 Schlingendornraptoren.", sourceObjectiveStatus = "unverified-source-field" }
quests[195] = { id = 195, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raptorenpirsch", description = "Jetzt machen wir die Herausforderung ein wenig schwieriger. Begebt Euch in den Dschungel und erlegt 10 dieser Schmetterschwanzraptoren. Ihr werdet feststellen, dass diese stärker sind, als die Raptoren, die Ihr schon erlegt habt.\n\nDie Schmetterschwanzraptoren halten sich meistens südöstlich von hier auf, in der Nähe der Ruinen von Kal'ai.", sourceObjective = "Jagt 10 Schmetterschwanzraptoren.", sourceObjectiveStatus = "unverified-source-field" }
quests[196] = { id = 196, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raptorenhatz", description = "Eine besonders gerissene Art von Raptor, die bei den Einheimischen als \"Dschungelpirscher\" bekannt ist, treibt sich südlich des Flusses im Wald herum. Diese sind viel schwieriger aufzuspüren und zu töten, als die anderen Arten, an denen Ihr Euch versucht habt.\n\nDiese Dschungelpirscher zu erlegen sollte mit Sicherheit eine gute Lagerfeuergeschichte abgeben.", sourceObjective = "Jagt 10 Dschungelpirscher.", sourceObjectiveStatus = "unverified-source-field" }
quests[197] = { id = 197, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beherrschen der Raptorenjagd", description = "Bevor Ihr zu Nesingwarys Expedition zurückkehrt, müsst Ihr das Unmögliche wagen: Macht Jagd auf den Raptor, den noch kein anderer Jäger fangen konnte. Dieses Tier ist unter dem Namen Tethis bekannt und versetzt die südöstlichen Gegenden des Nördlichen Schlingendorntals in Angst und Schrecken.\n\nDie Kralle von Tethis bei diesem Zwergenjäger abzuliefern sollte Beweis genug sein, dass Ihr <kein gewöhnlicher/keine gewöhnliche:r> {race} seid.", sourceObjective = "Jagt Tethis.", progress = "Wie läuft die Jagd auf Tethis? Ihr habt sie wohl den ganzen Weg bis hierher ins Lager verfolgt, wie?", completion = "Meister {name}, der Raptorentöter!\n\nKlingt gar nicht schlecht, wie?", sourceObjectiveStatus = "unverified-source-field" }
quests[198] = { id = 198, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorräte für den Gefreiten Thorsen", description = "Hmm. Ja, es gibt tatsächlich etwas, das Ihr tun könntet. Leutnant Doren und seine Leute oben im Norden warten auf ihre turnusmäßige Vorratslieferung von uns.\n\nDie Vorräte wurden noch nicht bei ihnen abgeliefert und jetzt, wo die Trolle ständig angreifen, brauche ich jemanden, der das erledigt. Dorens Lager liegt im Nordwesten der Straße, dort, wo man vom Dämmerwald aus ins Schlingendorntal kommt. Gebt die Vorräte dem Gefreiten Thorsen. Wenn er nicht im Lager ist, dann patrouilliert er südlich davon. Er wird sie in Empfang nehmen und verstauen.\n\nAber dass eines klar ist: Wenn Ihr versagt, dann müsst Ihr mir Ersatz leisten.", sourceObjective = "Liefert die verschiedenen Goblinvorräte bei dem Gefreiten Thorsen ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[199] = { id = 199, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine dunkle Bedrohung", description = "Ihr nehmt eine Probe von dem sonderbar riechenden Pulver.", sourceObjective = "Kehrt zu Chefingenieur Hinderweir zurück und zeigt ihm den Hinweis, den Ihr entdeckt habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[200] = { id = 200, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Buchmacher Herod", description = "Wenn Kurzen Thorsens Geheimnis kennt, dann haben wir einen Spion in unseren Reihen. Wir müssen herausfinden, wie das Geheimnis verraten werden konnte!\n\nThorsens Kontaktperson in Kurzens Lager war der Buchmacher Herod. Herod ist Kurzens Nachschubsoffizier und weiß alles über den Betrieb in Kurzens Truppenlager. Wenn Ihr Herods Unterlagen oder Aufzeichnungen beschaffen könntet, fänden wir vielleicht heraus, wie Thorsen entdeckt werden konnte.\n\nAls wir noch unter Kurzen dienten, war das Büro des Buchmachers im oberen Stock des einzigen zweistöckigen Gebäudes im Lager. Seine Aufzeichnungen sind vermutlich immer noch dort zu finden.", sourceObjective = "Findet Buchmacher Herods Aufzeichnungen.", sourceObjectiveStatus = "unverified-source-field" }
quests[201] = { id = 201, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Untersuchung des Lagers", description = "Ich habe Berichte gehört, nach denen eine Gruppe von Jägern ihr Lager flussaufwärts vom Bergbaucamp der Venture Company am Nazferitisee aufgeschlagen hat. Das wäre mir normalerweise völlig egal, aber ich habe gehört, dass Hemet Nesingwary Jr. einer der Jäger dort sein soll. Das ist zwar absolut unwahrscheinlich, aber... na ja, er hat sehr gute Beziehungen, wenn Ihr wisst, was ich meine, und man kann nie vorsichtig genug sein.\n\nWollt Ihr nicht hin und Euch das Lager einmal anschauen, {name}, und sehen, was die vorhaben?", sourceObjective = "Lokalisiert das Jägerlager und teilt dann Krazek in Beutebucht mit, wo es sich befindet.", sourceObjectiveStatus = "unverified-source-field" }
quests[202] = { id = 202, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Colonel Kurzen", description = "Ihr habt Euren Wert wieder und wieder unter Beweis gestellt und Euer Einfallsreichtum scheint sich mit dem von Kurzen selbst messen zu können. Ihr könntet die Rettung für unseren Rebellentrupp sein... falls Ihr Euch gegen Kurzen stellen und siegen könnt!\n\nEr erteilt die Befehle an seine Männer von tief aus dem Vorratslager heraus. Ihr müsst Euch Zutritt zu dieser Höhle verschaffen, an seinen Verteidigern vorbei, und dann Kurzen und seinen Führungsoffizieren gegenübertreten.\n\nLebt wohl, {name}. All meine Hoffnung, ebenso das Schicksal meiner Männer, ruht in Euren Händen.", sourceObjective = "Tötet 6 von Kurzens Elitesoldaten, 4 von Kurzens Stabschefs und bringt Kurzens Kopf ins Rebellenlager zu Leutnant Doren.", sourceObjectiveStatus = "unverified-source-field" }
quests[203] = { id = 203, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die zweite Rebellion", description = "Wir kämpfen einen aussichtslosen Kampf gegen Colonel Kurzen. Nicht nur, dass der Mann ein brillanter Taktiker ist, seine Männer sind uns auch noch zahlenmäßig mindestens 10 zu 1 überlegen! Um überleben zu können, müssen wir seine eigenen, auf Heimlichkeit basierenden Taktiken gegen ihn anwenden.\n\nBetretet sein Lager im Osten und tötet seine Leute. So viele Ihr könnt. Und verschwindet wieder, bevor seine Verstärkung Euch in die Zange nehmen kann.", sourceObjective = "Tötet 15 von Kurzens Dschungelkämpfern.\n\nKehrt ins Rebellenlager zu Unteroffizier Yohwa zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[204] = { id = 204, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlechte Medizin", description = "Um überhaupt eine Chance gegen Kurzen zu haben, müssen wir ihm die Möglichkeit nehmen, seine Truppen zu heilen. Er hat um sich eine große Anzahl an Medizinmännern versammelt, die seine Streitkräfte mit Dschungelarzneien heilen und unsere Kämpfer mit Giftfarnextrakt vergiften.\n\nWir brauchen diese Arzneien und Extrakte für uns selbst. Sucht in Kurzens Truppenlager: Seine Medizinmänner und Dschungelkämpfer haben die Arzneien und die Extrakte werden vermutlich irgendwo in den Vorratskisten im Lager verstaut sein.", sourceObjective = "Bringt Unteroffizier Yohwa im Rebellenlager 7 Dschungelarzneien und 1 Giftfarnextrakt.", sourceObjectiveStatus = "unverified-source-field" }
quests[205] = { id = 205, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trollhexerei", description = "Während ich die Legenden studiere, die Ihr beschafft habt, sammelt bitte für mich die Gerätschaften der bösen Trollmagie. Begebt Euch in das Gebiet der Schädelspaltertrolle, eines zweiten Stammes weit entfernt im Süden, und beschafft Euch dort Fetische der Schädelspalter von ihren Hexendoktoren und Mystikern.", sourceObjective = "Bringt Bruder Nimetz 4 Fetische der Schädelspalter ins Rebellenlager.", sourceObjectiveStatus = "unverified-source-field" }
quests[206] = { id = 206, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mai'Zoth", description = "Kurzen mag vielleicht tot sein, doch das, was ihn zum Bösen trieb, ist noch am Leben! Mittels meiner Studien habe ich Folgendes entdeckt: Ein Ogermagier namens Mai'Zoth lebt in einem Ogerhort in den östlichen Bergen des Schlingendorntals. Gerüchten zufolge wendet er Magie an, mit deren Hilfe er in die Gedanken anderer eindringen und diese kontrollieren kann, und ich bin mir sicher, dass er es war, der Kurzen verderbt hat.\n\nBleibt Mai'Zoth am Leben, dann beeinflusst er vielleicht noch andere und vielleicht würde dann sogar ein zweiter Kurzen entstehen.\n\nTötet ihn und bringt mir sein Gedankenauge, das Artefakt, mit dem er andere Wesen verderbt.", sourceObjective = "Bringt das Gedankenauge zu Bruder Nimetz ins Rebellenlager.", sourceObjectiveStatus = "unverified-source-field" }
quests[207] = { id = 207, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Geheimnis um Kurzen", description = "Colonel Kurzen war einst ein großer, ein edler Mann - ich muss herausfinden, wie es zu seiner Entartung kommen konnte! Es ist möglich, dass er dem Einfluss von Trollmagie unterliegt. Um diesen Verdacht zu bestätigen, muss ich einige ihrer Legenden studieren.\n\nIn den Trollruinen des Schlingendorntals liegen 4 Schrifttafeln versteckt. Ich muss wissen, was auf diesen Tafeln geschrieben steht! Schreibt die Zeichen ab, die Ihr auf den Tafeln findet, und bringt mir die Abschriften.\n\nDie erste Schrifttafel befindet sich in den Ruinen von Bal'lal, die zweite im Finsteren Riff und die dritte und vierte Schrifttafel findet Ihr in den Ruinen von Zul'Kunda.", sourceObjective = "Findet die 4 Schrifttafeln und bringt ihre Legenden zu Bruder Nimetz zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[208] = { id = 208, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Großwildjagd", description = "{name}, Ihr seid <ein Jäger, der/eine Jägerin> die; unserer Gesellschaft wahrlich würdig ist. Von den Schlachtfeldern von Lordaeron bis in den tiefsten Dschungel hinein habe ich selten jemanden gesehen, der so geschickt mit den Waffen umgegangen ist wie Ihr.\n\nIhr habt die furchterregende Sin'Dall, den schwer fassbaren Bhag'thera und die tückische Tethis erlegt. Doch die wahre Trophäe ist der Kopf von König Bangalash. Dieser weiße Tiger ist der Grund, warum ich hier bin. Und doch verspottet er mich von seinem Schlafplatz im Süden aus. Wenn Ihr König Bangalash tötet, dann steht ein für alle Mal fest, dass Euer jägerisches Können von niemandem übertroffen wird.", sourceObjective = "Jagt nach dem Kopf von König Bangalash, dem großen weißen Tiger.", progress = "Ah, wie ich sehe, seid Ihr zurück, alter Junge. Auch mich hat König Bangalash schon oft dazu gebracht, dass ich auf Händen und Füßen ins Lager zurückgekrochen kam. Haltet durch.", completion = "Verdammt gut gemacht! Ausgezeichnet! Glückwunsch, {name}! Ihr wart erfolgreich, wo andere versagt haben.\n\nIch fühle mich geehrt, dass Ihr ein Teil unserer großartigen Jagdgesellschaft hier seid. Niemand wird jemals Euer Können in Bezug auf das Jagen und Fährtenlesen in Frage stellen!\n\nEuch gebührt Beifall, sage ich! Beifall!", sourceObjectiveStatus = "unverified-source-field" }
quests[209] = { id = 209, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hauer der Schädelspalter", description = "Es ist teuer und anstrengend, genug Tiger zu töten, um damit den Bedarf an Tigerzähnen für den Export auf die Inseln in den Südlichen Meeren decken zu können. Glücklicherweise haben wir eine gewisse Technik entwickelt, mit deren Hilfe wir aus einfachem hornähnlichen Material nicht nachweisbare Fälschungen herstellen können.\n\nErstaunlicherweise eignen sich die Hauer von Schädelspaltertrollen dafür am besten.\n\nUnd bevor Ihr irgendwas sagt - was der Käufer nicht weiß, macht ihn nicht heiß, hab ich nicht Recht? Bringt mir so viele Hauer wie möglich, damit wir mit der monatlichen Lieferung anfangen können!", sourceObjective = "Besorgt 18 Hauer der Schädelspalter und bringt sie zu Kebok.", sourceObjectiveStatus = "unverified-source-field" }
quests[210] = { id = 210, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kochen mit Krazek", description = "Meistens bin ich es, der hier im Lager kocht. Und das war auch immer ganz schön viel Arbeit, bis ich von einem Goblinhändler in Beutebucht einen mechanischen Kochtopf gekauft habe. Der Topf ist einfach unglaublich. Er hat mir unzählige Stunden Arbeit erspart - bis er kaputtgegangen ist!\n\nKönnt Ihr den Topf dem Goblin zurückbringen, damit er ihn mir repariert? Der Händler heißt Krazek.", sourceObjective = "Bringt Krazeks Spezialtopf zu Krazek, dem Goblin.", sourceObjectiveStatus = "unverified-source-field" }
quests[211] = { id = 211, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weh dir, Andorhal", description = "Endlich ist die Zeit gekommen, Andorhal anzugreifen und den Lich, der die Stadt kontrolliert, zu vertreiben.\n\nIhr habt vielleicht einen Beschwörungskristall in den von Euch markierten Wachtürmen bemerkt. Wir glauben, dass diese dem Lich die Kraft geben, die er zur Kontrolle der Stadt benötigt. Ihr müsst alle vier ausschalten. Wird einer davon zerstört, dürfte das zweifellos weitere Truppen des Lichs auf den Plan rufen. Wenn alle vier vernichtet wurden, dürfte der Lich selbst auftauchen, um das Herz der Stadt zu verteidigen.\n\nVernichtet den Lich, {name}, und bringt mir einen Splitter seines Phylakteriums als Beweis!", sourceObjective = "Bringt den Splitter von Arajs Phylakterium zu Kommandant Ashlam Ehrenschlag auf der Zugwindspitze in den Westlichen Pestländern.", sourceObjectiveStatus = "unverified-source-field" }
quests[212] = { id = 212, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine kalte Mahlzeit", description = "Eines meiner berühmtesten Gerichte ist gekühlter Basilisk an Limonenvinaigrette. Das Problem ist nur: Das Fleisch lässt sich unmöglich frisch halten und ich muss das Gericht heute Abend anlässlich des Geburtstags eines Edelmannes servieren!\n\nWenn Ihr mir also schnell einen gekühlten Basiliskenschenkel von einem frisch getöteten Kaltaugenbasilisken bringen könnt, dann schulde ich Euch ein Festessen, das eines Königs würdig wäre!\n\nKaltaugenbasilisken streifen durch die Stranddünen im Nordwesten des Schlingendorntals, also habt Ihr eine lange Reise vor Euch. Und macht schnell!", sourceObjective = "Tötet einen Kaltaugenbasilisken, beschafft Euch einen gekühlten Basiliskenschenkel und bringt ihn Angus Stern im Blauen Eremiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[213] = { id = 213, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feindliche Übernahme", description = "Diesmal ist er zu weit gegangen! Schlimm genug, dass Gelriz dabei ist, die von den Handelsbaronen eingesetzten Moguln rauszudrängen, jetzt versucht er auch noch, den berüchtigtsten aller Piraten mit hineinzubringen!\n\nDas lässt Revilgaz sich nicht bieten und er hat mir aufgetragen, das Problem auf meine Weise zu lösen.\n\nWas meine Weise ist? Diebstahl, ganz einfach. Die Geologen der Venture Company zeigen ein auffälliges Interesse an den seltsamen blauen Kristallen, die sie bisweilen in den Minen finden. Bringt mir einige Proben dieser Steine von den Geologen; es ist mir völlig egal, was Ihr tun müsst, um an sie heranzukommen.", sourceObjective = "Beschafft 8 gerommelte Kristalle und bringt sie nach Beutebucht zu Kebok.", sourceObjectiveStatus = "unverified-source-field" }
quests[214] = { id = 214, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rote Seidenkopftücher", description = "Es ist kein Geheimnis, dass das Markenzeichen der Defiasbande ihre roten Kopftücher sind. Aber wir haben herausgefunden, dass das Material, aus dem diese Kopftücher gemacht sind, den Rang des Bandenmitglieds bezeichnet.\n\nJetzt, wo wir das wissen, möchte ich, dass Ihr so viele hochrangige Mitglieder der Defias eliminiert, wie Ihr könnt. Die Bandenmitglieder mit der höchsten Position findet Ihr zweifellos in van Cleefs Geheimversteck. Wenn Ihr fertig seid, bringt mir 10 rote Seidenkopftücher zum Beweis, dass sie tot sind, dann werde ich Euch belohnen. Viel Glück, {name}.", sourceObjective = "Späherin Riell am Turm auf der Späherkuppe möchte, dass Ihr ihr 10 rote Seidenkopftücher bringt.", sourceObjectiveStatus = "unverified-source-field" }
quests[215] = { id = 215, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheimnisse im Dschungel", description = "Danke, dass Ihr mich gerettet habt, {name}. Ich weiß, wie es aussieht, aber lasst mich bitte erklären!\n\nIch hatte von Leutnant Doren den Auftrag erhalten, mich wieder Kurzens Männern anzuschließen. Ich sollte sie ausspionieren und den Rebellen Informationen bringen, die sie bitter benötigen. Was Ihr hier miterlebt habt, war das, was ich für meine Chance hielt, Kurzens Truppenlager zu infiltrieren. Ich habe mich geirrt und ich muss Euch nochmals danken, dass Ihr mich gerettet habt.\n\nDiese Mission war streng geheim, Ihr dürft also niemandem davon erzählen. Aber wenn Ihr mit Doren sprecht, dann wird der Euch alles erklären.", sourceObjective = "Sprecht im Rebellenlager mit Leutnant Doren.", sourceObjectiveStatus = "unverified-source-field" }
quests[216] = { id = 216, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hart auf hart", description = "Die Distelfellfurbolgs bedrohen unsere Expansion! Das Lager der Distelfelle westlich von uns blockiert den Weg zwischen uns hier und dem Splitterholzposten. Dieser Weg würde das Dorf Astranaar umgehen; ohne ihn überlassen wir der Allianz eine zusätzliche Möglichkeit der Ausbreitung.\n\n{name}, wir dürfen keine Lücke in unseren Expansionspfaden erlauben!\n\nBegebt Euch ins Distelfelllager und dünnt die Furbolgs etwas aus. Ihr werdet für diese Aufgabe entschädigt werden, aber noch viel wichtiger ist, dass Ihr Eure Pflicht der Horde gegenüber tun werdet.", sourceObjective = "Karang Amakkar in Höllschreis Wacht möchte, dass Ihr 15 beliebige Furbolgs der Distelfelle im Distelfelllager ausschaltet.", completion = "Gut gemacht, {class}, gut gemacht! Ich werde weiterhin Truppen aussenden, um die Population der Furbolgs niedrig zu halten, aber ich kann auf mindestens einen weiteren Pfad zählen, der frei von Verstrickungen der Allianz ist. Die Eroberung des Eschentals durch die Horde ist jetzt in vollem Gang!\n\nIhr habt Euch heute Eure Bezahlung verdient. Ich ziehe den Hut vor Euch!", sourceObjectiveStatus = "unverified-source-field" }
quests[217] = { id = 217, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Entscheidungsschlag", description = "Mein Trick hat funktioniert. Wie es scheint, folgen diese Bestien am Loch Modan einem Häuptling namens Grawmug. Grawmug wird jedoch aufs Schwerste bewacht. Zwei seiner Elitewachen, Knirscher und Muskelprotz, weichen nie von seiner Seite.\n\nWenn Ihr Euch dem gewachsen fühlt, {name}, dann möchte ich, dass Ihr das Attentat auf Grawmug und seine beiden Schläger hier in dieser Höhle anführt. Geht! Ich werde mich von diesen Fesseln befreien und in Kürze zu Euch aufschließen.", sourceObjective = "Tötet den Anführer der Troggs, Grawmug, sowie seine beiden Wachen, Knirscher und Muskelprotz, und erstattet dann Hauptmann Rugelfuß in Thelsamar Bericht.", sourceObjectiveStatus = "unverified-source-field" }
quests[218] = { id = 218, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eis und Feuer", description = "Soren hat gut daran getan, Euch auf Erkundung zu schicken. Das sind wertvolle Informationen, die Ihr da bringt.\n\nDas Problem ist nur, dass uns das nur noch mehr Arbeit macht. So verwirrt die Trolle momentan zwar sind, würden sie die Zwerge noch immer am liebsten aus dem Eisklammtal hinauswerfen. Und ich werde ganz gewiss keinem dahergelaufenen Feuerdämon erlauben, unser verschneites Tal in einen Bergsee zu verwandeln.\n\nDer Trollanführer, seine Diener und die Feuerkreatur sollten alle in der Höhle im Südosten sein. Schaltet sie allesamt aus.", sourceObjective = "Tötet Grik'nir den Kalten, 6 Klingen der Frostmähnen, 3 Novizen der Frostmähnen und den unberechenbaren Feuerelementar.", progress = "{name}! Glück gehabt?", completion = "Ich bin froh, dass Ihr sicher zurückgekehrt seid, {name}. Zwar mag es im Moment nicht danach aussehen, aber Ihr habt Euch als eine überaus große Bereicherung für die Verteidigung Ambossars entpuppt.\n\nHier, nehmt dies als ein Zeichen meiner Dankbarkeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[219] = { id = 219, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vermisst", description = "Freunde der Allianz! Endlich!\n\nHelft... bitte... \n\nDas Letzte, an das ich mich erinnere, ist, dass diese abscheulichen Orcs unser Regiment überwältigten. Die meisten Männer wurden getötet; ich selbst erhielt einen Schlag an den Kopf und alles wurde schwarz. Jetzt werde ich in dieser Höhle gefangen gehalten. Bitte helft mir; ich bin schwer verletzt.\n\nIch brauche Hilfe auf dem Weg zurück in die Stadt... bitte... Ihr seid meine letzte Hoffnung...", sourceObjective = "Beschützt Korporal Keeshan auf dem Rückweg ins Rotkammgebirge.", sourceObjectiveStatus = "unverified-source-field" }
quests[220] = { id = 220, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf des Wassers", description = "Islen hat noch eine weitere Aufgabe für Euch, ehe Ihr zur Belohnung Euer nächstes Totem erhaltet. Die Phiole mit Wasser, die ich Euch gegeben habe, wird für diese Aufgabe gebraucht, um was auch immer es sich dabei handeln mag.\n\nGeht nun und sucht sie auf. Wir werden uns eines Tages wieder begegnen.", sourceObjective = "Bringt die Phiole mit reinstem Wasser zu Islen Wasserdeuter am Tidustritt im Brachland.", sourceObjectiveStatus = "unverified-source-field" }
quests[221] = { id = 221, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worgen in den Wäldern", description = "Habt Ihr vielleicht schon festgestellt, dass einige größere Worgen zusammen mit den Schattenwirkern im Wald herumziehen? Nach allem, was wir wissen, machen diese Dunkelläufer den Großteil der Worgen-Population aus.\n\nAuf meinen Wanderungen habe ich außerdem festgestellt, dass sie in den Verrottenden Obstgarten im Südwesten der Stadt eingefallen sind. Diese Worgen sind etwas zäher als die letzten, denen Ihr begegnet seid.\n\nAlso seht Euch vor.", sourceObjective = "Tötet für Calor aus Dunkelhain 12 Dunkelläufer der Nachtheuler.", sourceObjectiveStatus = "unverified-source-field" }
quests[222] = { id = 222, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worgen in den Wäldern", description = "Eure früheren Leistungen haben mich überzeugt, dass Ihr in der Lage seid, Euch mit den zähesten Worgen zu messen, die sich in den Wäldern eingenistet haben.\n\nVon all den Worgen, die plötzlich hier zu finden sind, haben sich die Faulreißer und die Besudelten als die gefährlichsten herausgestellt. Sie haben sich in der Nähe einiger Höhlen und in der Mine im Süden niedergelassen.\n\nNoch aus weiter Entfernung sieht man die Lichter ihrer Feuer...", sourceObjective = "Tötet für Calor aus Dunkelhain 8 Faulreißer der Nachtheuler und 8 besudelte Nachtheuler.", sourceObjectiveStatus = "unverified-source-field" }
quests[223] = { id = 223, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worgen in den Wäldern", description = "Hier, bitte schön, {name}. Bringt Meister Treuwein diese Nachricht.\n\n<Schnell zieht er ein Stück verblasstes Pergament hervor und reicht es Euch.>\n\nNoch ein paar mehr wie Ihr, dann sind wir bald mehr Kämpfer als die Nachtwache! Vielleicht können wir dann das Werk vollenden, an dem wir wenigen uns heute noch vergebens abmühen.", sourceObjective = "Bringt Calors Notiz zu Jonathan Treuwein.", sourceObjectiveStatus = "unverified-source-field" }
quests[224] = { id = 224, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verteidigung der Länder des Königs", description = "Wir müssen den Loch beschützen, {name}! Jetzt, wo so viele der Soldaten des Königs tapfer auf weit entfernten Schlachtfeldern kämpfen, sind wir nahe davor, an der Heimatfront überwältigt zu werden. Aus jedem Spalt graben sich Troggs an die Oberfläche! Die Troggplage stellt für Eisenschmiede die größte Gefahr dar. Diese widerwärtigen Mutanten müssen vernichtet werden.\n\nIhr, <tapferer Abenteurer/tapfere Abenteurerin>, müsst Euch für uns hinauswagen und der Bedrohung durch die Troggs ein Ende bereiten. Erschlagt 6 Splittersteintroggs und 6 Späher der Splittersteintroggs und erstattet dann wieder Bericht.", sourceObjective = "Gebirgsjäger Feuerkiesel in Thelsamar möchte, dass Ihr 6 Splittersteintroggs und 6 Späher der Splittersteintroggs tötet.", sourceObjectiveStatus = "unverified-source-field" }
quests[225] = { id = 225, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das verwitterte Grab", description = "Auf dem verwitterten Grabstein steht einfach:\n\nMORGAN LADIMORE\n\n<Als Ihr den Ort weiter untersucht, stellt Ihr fest, dass die Erde über dem Grab kürzlich umgegraben wurde und dass ein guter Teil der Erde entfernt worden zu sein scheint...>", sourceObjective = "Sprecht in Dunkelhain mit Sirra Von'Indi.", sourceObjectiveStatus = "unverified-source-field" }
quests[226] = { id = 226, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wölfe sind uns auf den Fersen", description = "Sven und mir stehen jetzt gefährliche Tage ins Haus, wo doch der Totenbeschwörer im Osten sitzt und all das. Und weil wir hier draußen allein sind, müssen wir auch selbst jagen, wenn wir etwas essen wollen. Es kommt mir so vor, als würden jedes Mal, wenn ich mit etwas Fleisch zum Lager zurückgehe, verhungernde oder tollwütige Terrorwölfe aus dem Wald kommen, die auch etwas abhaben möchten. Ja, eines steht fest, das Leben hier draußen ist gefährlich!\n\nAber wenn Ihr einige der Wölfe für uns erledigen könntet, dann wäre das Leben für uns etwas leichter. Meist streunen sie nördlich und östlich von hier herum, in der Nähe des Flusses.", sourceObjective = "Tötet 12 verhungernde Terrorwölfe und 8 tollwütige Terrorwölfe und kehrt dann zu Lars in Svens Lager an der westlichen Grenze des Dämmerwalds zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[227] = { id = 227, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Morgan Ladimore", description = "<Er sucht in den Regalen und kommt mit einem ledergebundenen Buch zurück.>\n\nWenn Ihr mehr wissen wollt, dann fragt Althea. Sie ist diejenige, die in letzter Zeit von dem... Ärger... mit ihm am meisten mitbekommen hat.", sourceObjective = "Sprecht in Dunkelhain mit Kommandantin Althea Schwarzhaupt.", sourceObjectiveStatus = "unverified-source-field" }
quests[228] = { id = 228, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mor'Ladim", description = "Meine Späher berichten mir, dass Mor'Ladim durch den ganzen Dämmerwald wandert und auf dem Friedhof einen seltsamen, gewundenen Weg einschlägt. Wir haben ihn hinter dem Haus auf dem Hügel begraben, wisst Ihr, wo das ist?\n\nEs gibt nichts, was ich tun könnte, um Euch zu helfen, aber ich wünsche Euch viel Glück.", sourceObjective = "Tötet Mor'Ladim und bringt seinen Schädel nach Dunkelhain zu Kommandantin Althea Schwarzhaupt.", sourceObjectiveStatus = "unverified-source-field" }
quests[229] = { id = 229, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die überlebende Tochter", description = "Ich hätte Euch dies schon früher sagen sollen...\n\nWie soll ich sagen...\n\nMorgan dachte zwar, dass seine ganze Familie umgekommen sei, aber seine Tochter Sarah Ladimore lebt noch: Sie ist jetzt eine Behüterin. Die... Umstände... unter denen ihr Vater zu Tode gekommen ist, haben sie immer sehr aufgewühlt. Vielleicht könntet Ihr zu ihr gehen und ihr mitteilen, was geschehen ist.", sourceObjective = "Sprecht in Dunkelhain mit Behüterin Sarah Ladimore.", sourceObjectiveStatus = "unverified-source-field" }
quests[230] = { id = 230, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Svens Lager", description = "Als Ihr durch den Haufen wühlt, findet Ihr ein kleines, schmutzbeflecktes Buch.\n\nDas Buch hat keinen Titel, aber... es enthält Informationen, die Sven bestimmt interessieren.", sourceObjective = "Bringt das Buch von Svens Hof zu Sven.", sourceObjectiveStatus = "unverified-source-field" }
quests[231] = { id = 231, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Liebe einer Tochter", description = "Hier, nehmt dies und legt es auf sein Grab. Vielleicht... vielleicht weiß er dann irgendwie, dass es mir gut geht und dass keiner von uns ihn für das verantwortlich macht, was geschehen ist.\n\n<Jetzt hat sie Tränen in den Augen, als sie einen Ring von der rechten Hand zieht und ihn Euch übergibt.>\n\nUnd... danke, {name}.", sourceObjective = "Bringt Sarah Ladimores Ring zu Morgan Ladimores Grab.", sourceObjectiveStatus = "unverified-source-field" }
quests[232] = { id = 232, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kurierdienst für Apothekerin Zinge", description = "Die Königliche Apothekenvereinigung benötigt Eure Hilfe. Hört gut zu und wir können beide von meinem Plan profitieren.\n\nApotheker Keifer im nächsten Raum mag... begabt sein..., aber seine Forschungen könnten Früchte tragen, wenn sie von einem gewandten Forscher... oder einer gewandten Forscherin verfolgt würden. Zum Glück bin ich eine solche Forscherin. Bringt diese Bestellung zu Alessandro Luca, dem Eigentümer von Blaumond Dies-und-Das. Er wird Euch ein Testset geben. Wenn Ihr es habt, bringt es zu mir zurück und ich werde Euch Eure Aufgabe im Detail erläutern.", sourceObjective = "Bringt die Bestellung nach Unterstadt zu Alessandro Luca.", sourceObjectiveStatus = "unverified-source-field" }
quests[233] = { id = 233, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Postbeförderung im Eisklammtal", description = "Hm, ich nehme nicht an, dass Ihr mir einen Gefallen tun würdet, <Jungchen/Mädchen>? Heute kam ein Stapel Briefe durch den Pass, aber ich habe nicht die Zeit, sie weiterzuleiten.\n\nSie sind alle an Talin Kühnauge adressiert. Ihr findet ihn ein Stück entlang der Straße im Westen. Er hat sein Lager am gefrorenen See aufgeschlagen.\n\nWas meint Ihr?", sourceObjective = "Liefert den Stapel Briefe bei Talin Kühnauge im Eisklammtal ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[234] = { id = 234, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Postbeförderung im Eisklammtal", description = "Wenn ich mich recht erinnere, hat Grelin sein Lager im Südosten, ein Stück die Straße hinunter. Ich bin sicher, er wartet schon sehnsüchtig auf seine Post.", sourceObjective = "Liefert den Brief bei Grelin Weißbart im Eisklammtal ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[235] = { id = 235, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Jagd im Eschental", description = "Achtung, junge Abenteurer! Die Wildnis des Eschentals erwartet Euch!\n\nDie Horde hat eine starke Präsenz in den Ländern nördlich des Brachlandes aufgebaut. Unsere beiden Außenposten - der Splitterholzposten und der Zoramstrandposten - wollen der Horde zu Ruhm gereichen! Diejenigen, die sich beweisen möchten, sollten dort nach Anleitung suchen. Wichtiger Hinweis: Senani Donnerherz im Splitterholzposten, direkt nördlich des Brachlandes, sucht Abenteurer, die an einer großen Jagd im Eschental teilnehmen wollen!", sourceObjective = "Sprecht mit Senani Donnerherz im Splitterholzposten im Eschental.", sourceObjectiveStatus = "unverified-source-field" }
quests[236] = { id = 236, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verwüster auftanken", description = "{name}! Wurde auch langsam Zeit, dass Ihr auftaucht. Die Schlacht mag vielleicht zu Ende sein, doch wir müssen uns noch immer auf die nächste vorbereiten. Reist zum Flammenkessel im südöstlichen Teil von Tausendwinter und holt mehrere Stück Immerglut.\n\nDie Glutstücke werden mit Kohle vermengt, um Treibstoff für die Verwüster und Belagerungsmaschinen zu liefern.\n\nOh, eins noch: Falls Ihr zufällig Anhänger der Horde im Flammenkessel sehen solltet, dann zögert nicht, tötet sie und nehmt ihre Glutstücke. Wir können nicht zulassen, dass sie in der nächsten Schlacht im Vorteil sind.", sourceObjective = "Belagerungsmeister Starkhand in der Tausendwinterfestung möchte, dass Ihr zum Flammenkessel geht und den Hordlern dort 10 Stück Immerglut abnehmt.", sourceObjectiveStatus = "unverified-source-field" }
quests[237] = { id = 237, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verteidigung der Länder des Königs", description = "Gebirgsjäger Feuerkiesel hat nur Gutes über Euch zu berichten gehabt, {race}. Daher werde ich Euch eine Mission von äußerster Wichtigkeit anvertrauen. Wir müssen den Druck auf die eindringenden Troggstreitkräfte aufrechterhalten, bis unsere Brüder, die Zwerge, von der Front der Allianz zurückkehren.\n\nBegebt Euch in die südlichen Hügel und tötet 10 Schädelhauer der Splittersteintroggs und 10 Seher der Splittersteintroggs. Eure Angriffe werden uns etwas Zeit verschaffen. Erstattet Bericht, sobald Ihr die Aufgabe erfüllt habt.", sourceObjective = "Gebirgsjäger Kieselwut im südlichen Wachturm möchte, dass Ihr 10 Schädelhauer der Splittersteintroggs und 10 Seher der Splittersteintroggs tötet und ihm anschließend Bericht erstattet.", sourceObjectiveStatus = "unverified-source-field" }
quests[238] = { id = 238, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kurierdienst für Apothekerin Zinge", description = "Das Set ist fertig, {name}. Die Apothekerin Zinge wird es zweifellos so schnell wie möglich haben wollen. Bringt es ihr ohne Verzögerung und lasst sie wissen, dass ich die Kosten für das Set mit auf die Rechnung der Gesellschaft schreiben werde. Richtet ihr bitte außerdem meine wärmsten Grüße aus.\n\nAlso los, steht nicht einfach so rum. So ist nun mal das Leben eines einfachen Kuriers, stimmt's?", sourceObjective = "Bringt das Feldprobenset nach Unterstadt zu Apothekerin Zinge.", sourceObjectiveStatus = "unverified-source-field" }
quests[239] = { id = 239, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hilfe für die Weststromgarnison", description = "Die Garnison an unserer westlichen Grenze berichtet von steigenden Aktivitäten der Gnolle und der Diebe. Sie bitten uns um die Entsendung weiterer Soldaten aus Sturmwind... aber wir können einfach keine entbehren!\n\nWenn Ihr helfen könntet - wir könnten die Hilfe wirklich gebrauchen. Geht, sprecht mit Stellvertreter Rainer in der Weststromgarnison und fragt ihn, was getan werden muss.\n\nDie Garnison liegt an der Straße im Westen. Wenn Ihr die Brücke über den kleinen Bach überquert habt, liegt sie auf der rechten Seite.", sourceObjective = "Begebt Euch zur Weststromgarnison und sprecht mit Stellvertreter Rainer.", completion = "Marschall Dughan hat Euch geschickt, wie? Ihr seid zwar nicht in der Armee, aber wenn Dughan Euch geschickt hat, dann soll mir das recht sein.\n\nUnsere Lage hier ist, um es gelinde auszudrücken, angespannt. Ich hoffe, Ihr könnt ein wenig aushelfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[240] = { id = 240, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zu Bibbers", description = "Und voilà - \"Krebs\"-Küchlein à la Grual!", sourceObjective = "Kehrt mit den schwärzlichen Krebsküchlein zu Bibbers zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[243] = { id = 243, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf ins Feld", description = "Ihr werdet Euch in die Tanariswüste begeben und die Gewebebeschaffenheit der Basilisken, Skorpide und Hyänen testen, die dort heimisch sind. Beschafft Gewebeproben und untersucht sie mit dem Testset; Ihr müsst davon ausgehen, dass eine Reihe der Proben unnütz sind. Ich benötige von jeder Kreaturenart acht akzeptable Proben.\n\nAußerdem verfügen die Goblins von Gadgetzan über eine Kraftquelle, die mit dieser Art von modifiziertem Set verwendet werden muss. Sprecht mit Chefingenieur Bilgenritzel und erwerbt eine für das Set.\n\nKehrt erst zu mir zurück, wenn Ihr erfolgreich wart.", sourceObjective = "Sprecht in Gadgetzan mit Chefingenieur Bilgenritzel über eine Kraftquelle für das Testset.\n\nBereitgestellter Gegenstand:", sourceObjectiveStatus = "unverified-source-field" }
quests[244] = { id = 244, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eindringende Gnolle", description = "Seid gegrüßt, {class}. Meine Aufgabe ist es, auf diesem Stück Straße zu patrouillieren. Obwohl die Straße im Augenblick sicher ist, habe ich nördlich und östlich von hier einige Lager von Gnollen gesehen.\n\nSeenhain muss erfahren, dass die Gnollstreitkräfte sich sammeln! Meldet Euch bei Stellvertreter Feldon in Seenhain und berichtet ihm von den Gnollen. Wenn Ihr dies tut, dann wird Feldon Euch bestimmt den Sold eines Spähers zahlen.\n\nGewöhnlich inspiziert Feldon das Gebiet südlich der Brücke nach Seenhain.", sourceObjective = "Erstattet Stellvertreter Feldon Bericht. Zu finden ist er an der Brücke südlich von Seenhain im Rotkammgebirge.", sourceObjectiveStatus = "unverified-source-field" }
quests[245] = { id = 245, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefahr auf acht Beinen", description = "Seid gegrüßt, {class}. Vielleicht habt Ihr die Spinnen gesehen, die die Grenze im Westen überrannt haben? Mit den achtbeinigen Monstern werden wir nicht fertig und der Kommandant hat nicht genug Leute, um sie so weit weg von Dunkelhain einsetzen zu können.\n\nIch bitte Euch wirklich nur sehr ungern darum, aber Ihr seht aus, als könntet Ihr mit ihnen fertigwerden. Ich kann Euch keine großen Schätze versprechen, aber ich kann Euch belohnen, wenn Ihr dabei helft, die dreckigen Biester auszurotten.\n\nAch, ein Ratschlag noch: Weicht ihrem Gift aus, wenn Ihr könnt.", sourceObjective = "Erledigt 15 Zwerggiftweberspinnen und meldet Euch dann wieder bei Behüter Dodds im Dämmerwald.", sourceObjectiveStatus = "unverified-source-field" }
quests[246] = { id = 246, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einschätzung der Gefahr", description = "Wir können keinen der Männer hier entbehren, aber mit diesen Gnollen, von denen Ihr mir berichtet habt, muss etwas passieren.\n\nSpäht das südliche Rotkammgebirge nach Gnollen aus. Bedrängt sie, tötet so viele Ihr könnt und erstattet mir dann Bericht über ihre Anzahl. Gebt mir auch eine Einschätzung der Gefahr, die sie darstellen. Möglicherweise findet Ihr Lager dieser Gnolle entlang der südlichen Straße im Rotkammgebirge.\n\nTut dies für die Armee von Sturmwind, {name}, und Ihr erhaltet eine Belohnung.", sourceObjective = "Tötet 10 Bastarde der Rotkammgnolle und 6 Wilderer der Rotkammgnolle und meldet Euch anschließend wieder bei Stellvertreter Feldon in Seenhain.", sourceObjectiveStatus = "unverified-source-field" }
quests[247] = { id = 247, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Jagd ist abgeschlossen" }
quests[248] = { id = 248, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weitere Beobachtungen", description = "Seit einer Weile schon beobachte ich den Turm von Ilgalar und ich habe herausgefunden, dass Morganth im Konflikt mit den Orcs von Burg Steinwacht liegt. Den Grund für ihren Streit kenne ich nicht, aber vielleicht könnt Ihr mir ja dabei helfen, diesem Rätsel auf die Spur zu kommen.\n\nNehmt eine weitere Glyphe von Azora und begebt Euch dann auf die Spitze des unversehrten Wachturms neben der Burg Steinwacht.\n\nFindet einen passenden Gegenstand, auf dem Ihr die Glyphe ablegen könnt. Eine Truhe oder ein Krug - irgendein Ort, an dem die Glyphe nicht auffällt - ist für meine Zwecke geeignet.", sourceObjective = "Steigt in den unversehrten Wachturm neben der Burg Steinwacht im Rotkammgebirge hinauf.\n\nFindet einen passenden Behälter für die Glyphe von Azora und legt diese dort ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[249] = { id = 249, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Morganth", description = "Nach langen Beobachtungen habe ich jetzt Morganths Pläne durchschaut.\n\nEr sucht nach der Sichel von Elune... und vielleicht hat er sie bereits gefunden! Wenn dem so ist, dann werden das Rotkammgebirge und das Königreich Sturmwind schon bald seine dunkle Macht zu spüren bekommen.\n\nIch selbst bin leider nicht bereit, mich gegen Morganth zu stellen, doch ich fürchte, er muss genau jetzt aufgehalten werden. Daher müsst Ihr Euch Zutritt zum Turm von Ilgalar verschaffen und Morganth entgegentreten.\n\nBesiegt ihn und bringt mir seinen Schattenanhänger. Wenn Ihr dies vermögt, dann schuldet das Königreich Euch viel.", sourceObjective = "Besiegt Morganth.\n\nBringt seinen Schattenanhänger zu Theocritus am Turm von Azora im Wald von Elwynn.", sourceObjectiveStatus = "unverified-source-field" }
quests[250] = { id = 250, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine dunkle Bedrohung", description = "Den Sternen sei Dank, jemand sorgt sich um den Damm. Erst die Zerstörung des Thandolübergangs, dann die Plünderung von Dun Modr! Ich hege keinerlei Zweifel, dass der Damm das Ziel des nächsten Anschlags der Dunkeleisenzwerge sein wird. Der größte Teil meiner Sicherheitsleute wurde an die Front der Allianz versetzt, einschließlich meines besten Kontrolleurs.\n\nUnd deswegen brauche ich Euch, {name}. Ich habe einige Pioniere der Dunkeleisenzwerge gesehen, die an der östlichen Rampe des Damms herumlungerten. Untersucht den Bereich und bringt einen Hinweis zurück.", sourceObjective = "Untersucht den Bereich um die östliche Dammrampe und bringt Chefingenieur Hinderweir einen Hinweis, der Auskunft darüber geben könnte, was die Dunkeleisenzwerge vorhaben.", sourceObjectiveStatus = "unverified-source-field" }
quests[251] = { id = 251, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Übersetzung von Calvinius' Notiz", description = "Bringt den Zettel, den Ihr mir gabt, zu Sirra Von'Indi. Er ist sehr gelehrt und kennt viele Sprachen und alte Künste - wenn überhaupt jemand diese Nachricht übersetzen kann, dann ist er das.", sourceObjective = "Bringt den Brief an Ello zu Sirra Von'Indi.", sourceObjectiveStatus = "unverified-source-field" }
quests[252] = { id = 252, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Übersetzung für Ello", description = "Oh je! Wenn das, was hier steht, wahr ist, dann hat Calvinius etwas... Unsägliches getan.\n\nBringt die übersetzte Notiz besser schnell zu Ello zurück.\n\nBeeilt Euch, denn ich fürchte, Unheil rollt bereits auf unsere Stadt zu...", sourceObjective = "Bringt Lord Ello Schwarzhaupt den übersetzten Brief.", sourceObjectiveStatus = "unverified-source-field" }
quests[253] = { id = 253, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Braut des Einbalsamierers", description = "Der Einbalsamierer... diesen Namen kennen wir aus einer Geschichte, die wir unseren Kindern erzählen. Er war ein freundlicher Alchemist, den der Tod seiner Frau Eliza in den Wahnsinn trieb. Er wollte sie wiederbeleben und so wandte er schwarze Magie an und pflanzte sein eigenes Herz in die Brust seiner toten Gattin ein.\n\nDies stellte Eliza wieder her, doch nun war sie verflucht... ein unstillbarer Hunger auf Menschenfleisch hatte sich ihrer bemächtigt und der Einbalsamierer musste sie in ihrem Grab liegen lassen.\n\nSeine Macht ruht in seinem Herzen. Findet das Grab seiner Frau, holt sein Herz und bringt es mir, solange es noch schlägt. Wenn Ihr dies tut, wird seine Macht gebrochen sein.", sourceObjective = "Findet Elizas Grab. Beschafft das Herz des Einbalsamierers, das sie in sich trägt, und kehrt zu Ello Schwarzhaupt zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[254] = { id = 254, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Graben in der Erde" }
quests[255] = { id = 255, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Söldner", description = "Tiere zu jagen wird nach einer Weile langweilig. Mir steht der Sinn nach größerer Beute...viel größerer. Oger, um genau zu sein.\n\nDie hiesigen Zwerge machen sich Sorgen über die Festung Mo'grosh im Nordwesten, haben aber nicht die Truppenstärke, um viel zu unternehmen. Wenn Ihr bei meiner Jagd mitmachen wollt, könnt Ihr gern jeden Oger töten, dem Ihr begegnet. Bringt mir Kunde von Euren Taten und ich teile die Belohnung mit Euch, die ich mit dem Magistraten vereinbart habe.", sourceObjective = "Kelt Thomasin vom Mo'grosh Lager hat Euch angeheuert, 4 Oger der Mo'grosh, 4 Schläger der Mo'grosh und 4 Vollstrecker der Mo'grosh zu töten.", sourceObjectiveStatus = "unverified-source-field" }
quests[256] = { id = 256, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Chok'sul", description = "Auf Befehl des Magistrats von Thelsamar:\n\nDer Tod von Chok'sul, dem Oger und mutmaßlichen Anführer und Kopf hinter den Angriffen auf die Stadt Thelsamar, den Steinwerkdamm und die Ausgrabungsstätte, wird unter allen Umständen gewünscht. Es darf zu jedem Mittel gegriffen werden, das notwendig ist.\n\nEine Barentschädigung kommt zur Auszahlung, wenn der Magistrat einen Beweis für Chok'suls Tod erhält.\n\nZuletzt wurde Chok'sul am Ogerlager im nordöstlichen Teil von Loch Modan gesehen.", sourceObjective = "Tötet Chok'sul und bringt Magistrat Stumpfnase seinen Kopf.", sourceObjectiveStatus = "unverified-source-field" }
quests[257] = { id = 257, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Prahlen eines Jägers", description = "Ihr glaubt wohl, Ihr könnt Euch mit Daryl dem Kühnen messen, hm? Das will ich auch nicht hoffen! Aber Ihr dürft es natürlich gern versuchen, wenn Ihr denn meint... Hier habt Ihr eine Herausforderung, der Ihr bestimmt nicht gewachsen seid. Also nehmt's nicht zu schwer, wenn Ihr damit nicht fertigwerdet.\n\nEin Schwarm Bussarde nistet hier am Loch Modan. Warum versucht Ihr nicht, einige von denen zu erledigen? Ich sag Euch was. Wenn Ihr meine Herausforderung annehmt, dann gebe ich Euch meinen Bogen oder mein Gewehr.\n\n<Er mustert Euch abschätzig.>\n\nScheint ja nicht, als ob Ihr viel zu verlieren hättet.", sourceObjective = "Tötet 8 Bergbussarde und kehrt zu Daryl dem Jüngling in die Jagdhütte der Weltenwanderer zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[258] = { id = 258, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Herausforderung eines Jägers", description = "{name}ath, stimmt's? Ich seh schon, Ihr platzt fast vor Stolz, dass Ihr den ersten Test bestanden habt. Aber ich hab Euch ja auch schon gesagt, dass das keine große Tat war.\n\nIhr solltet Euch mal an der Eberjagd versuchen. Glaubt mir, das sind andere Eber als im Eisklammtal, also solltet Ihr Euch vorsehen.\n\nSeid nicht zu traurig, wenn Ihr versagt. Ich würde Euch mein letztes Hemd geben, wenn Ihr es schaffen würdet!\n\nHabe ich Euch schon mal erzählt, wie ich an meine berühmte Narbe gekommen bin? Nein? Also, das war vor zwei Jahren...", sourceObjective = "Tötet 10 alte Bergeber und kehrt zu Daryl dem Jüngling in die Jagdhütte der Weltenwanderer zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[261] = { id = 261, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf dem Scharlachroten Pfad", description = "Ich werde offen mit Euch sein. Wir sind im Krieg mit der Geißel. Sie ist ein Übel, das unser Volk verderbt und unser Land infiziert. Sie muss aufgehalten werden, bevor sie uns übermannt und unsere Welt mit Schatten überzieht. Wir vom Scharlachroten Kreuzzug haben geschworen, die Geißel mit Leib und Seele zu bekämpfen.\n\nWenn Ihr auf unserer Seite steht, dann nehmt Euren Mut zusammen und beweist Eure Zugehörigkeit – zerstört die untoten Verheerer von Desolace im südlich gelegenen Tal der Knochen.\n\nTut dies, und der Kreuzzug wird Euch mit offenen Armen aufnehmen.", sourceObjective = "Vernichtet 30 untote Verheerer und kehrt dann zu Bruder Anton auf die Nijelspitze zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[262] = { id = 262, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schattengestalt", description = "Ich muss wissen, wen ich in der Nacht, in der meine Familie ermordet wurde, in den Schatten habe herumschleichen sehen.\n\nBitte, {name}, Ihr habt euren Einfallsreichtum bereits bewiesen. Bitte findet diese schattenhafte Gestalt. Ich muss wissen, was sie für Geheimnisse kennt!\n\nIch habe keine Hinweise, die Ihr nicht bereits hättet, aber hier - nehmt das Buch, das Ihr auf meinem Hof gefunden habt. Vielleicht können einige Stadtbewohner das Buch mit seinem Besitzer in Verbindung bringen.", sourceObjective = "Nehmt das Buch, das Ihr auf Svens Hof gefunden habt, und zeigt es den Einwohnern von Dunkelhain.", sourceObjectiveStatus = "unverified-source-field" }
quests[263] = { id = 263, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verteidigung der Länder des Königs", description = "Die Gebirgsjäger sagen mir, dass Ihr recht tapfer und fähig seid, {name}. <Ein/Eine:r> {race} wie Ihr wird hier draußen gebraucht. Wir bekommen das Troggproblem einfach nicht unter Kontrolle. Die Reserve wurde zur Front gerufen, und wir sind hier auf uns allein gestellt. Aber jetzt seid ja Ihr hier, <ein erfahrener/eine erfahrene:c> {class}, also wollen wir doch mal sehen, was Ihr ausrichten könnt.\n\nZieht los und tötet 8 Schamanen der Splittersteintroggs und 8 Knochenknacker der Splittersteintroggs. Wir werden sehen, ob Ihr Eurem Ruf gerecht werdet, <Troggtöter/Troggtöterin>.", sourceObjective = "Gebirgsjäger Wallbang im südlichen Wachturm möchte, dass Ihr 8 Schamanen der Splittersteintroggs und 8 Knochenknacker der Splittersteintroggs tötet.", sourceObjectiveStatus = "unverified-source-field" }
